window.__HSK_CHAPTER_DATA__['chapter_13'] = [{"meanings_summary": {"en": "saw (tool); hand saw", "es": "sierra; serrucho"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A toothed metal (钅) blade attached to a wooden handle forms a trusty saw (锯子).", "composite_memory_hook_es": "Una hoja metálica (钅) dentada convertida en herramienta básica constituye una sierra (锯子).", "cultural_and_cognitive_roots": "Attributed to master craftsman Lu Ban in the Warring States period, inspired by jagged mountain weeds cutting skin.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by neutral tone: 'jù zi' (51-neutral). Sharp descending drop on 'jù' followed by light, unstressed 'zi'."}, "semantic_boundary_contrasts": {"core_nuance": "锯子 specifically denotes a serrated pull-or-push toothed sawing tool, unlike impact or slicing blades.", "contrasts": [{"id": "1", "compared_word": "锯子 vs. 斧头", "pinyin": "fǔtou", "analysis": "斧头 splits heavy lumber using downward chopping impact force, whereas 锯子 cuts linearly using repetitive back-and-forth friction."}, {"id": "2", "compared_word": "锯子 vs. 刀子", "pinyin": "dāozi", "analysis": "刀子 has a continuous smooth cutting edge suited for carving, whereas 锯子 has serrated teeth for abrading hard timber."}, {"id": "3", "compared_word": "锯子 vs. 剪刀", "pinyin": "jiǎndāo", "analysis": "剪刀 works through double-blade shearing of flexible fabrics or thin sheets, while 锯子 removes dust Kerf from rigid materials."}]}, "traps_and_cognates": {"look_alikes": [{"character": "锯", "pinyin": "jù", "meaning_en": "saw", "distinction_note": "Contains metal radical 钅 with 居"}, {"character": "据", "pinyin": "jù", "meaning_en": "according to; seize", "distinction_note": "Contains hand radical 扌 instead of 钅"}, {"character": "剧", "pinyin": "jù", "meaning_en": "theatrical drama; acute", "distinction_note": "Contains knife radical 刂 on the right"}, {"character": "裾", "pinyin": "jū", "meaning_en": "hem of garment", "distinction_note": "Contains clothing radical 衤 on the left"}], "etymological_cognates": [{"character": "斧", "pinyin": "fǔ", "gloss_en": "axe; hatchet"}, {"character": "刨", "pinyin": "bào", "gloss_en": "plane (carpentry tool)"}, {"character": "凿", "pinyin": "záo", "gloss_en": "chisel; bore"}, {"character": "铲", "pinyin": "chǎn", "gloss_en": "shovel; trowel"}]}, "id": "1", "hanzi": "锯子", "pinyin": "jù zi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a cutting tool consisting of a toothed blade operated by hand or machine", "definition_es": "herramienta para cortar madera u otros materiales compuesta por una hoja dentada", "example_phrase": "一把锋利的锯子 (a sharp hand saw)"}], "example_sentences": [{"id": "#1", "hanzi": "老木匠熟练地拿起锯子，顺着墨线几下就把坚硬的红木板整齐地锯开了。", "pinyin": "Lǎo mùjiang shúliàn de ná qǐ jùzi, shùnzhe mòxiàn jǐ xià jiù bǎ jiānyìng de hóngmù bǎn zhěngqí de jù kāi le.", "en": "The veteran carpenter skillfully picked up the saw and neatly cut through the hard mahogany board along the marked ink line in just a few strokes.", "es": "El viejo carpintero tomó con destreza la sierra y, siguiendo la línea de tinta, cortó con pulcritud la dura tabla de caoba en pocos pases."}, {"id": "#2", "hanzi": "在现代建筑工地上，传统的简易锯子已经被高效精准的电动切割机所取代。", "pinyin": "Zài xiàndài jiànzhù gōngdì shang, chuántǒng de jiǎnyì jùzi yǐjīng bèi gāoxiào jīngzhǔn de diàndòng qiēgējī suǒ qǔdài.", "en": "On modern construction sites, traditional simple saws have largely been replaced by highly efficient and precise electric cutting machines.", "es": "En las obras de construcción modernas, las sierras manuales tradicionales han sido sustituidas por cortadoras eléctricas de gran eficiencia y precisión."}], "collocations": [{"hanzi": "用锯子锯断", "en": "saw through with a saw"}, {"hanzi": "一把锯子", "en": "a saw (classifier 把)"}, {"hanzi": "木工锯子", "en": "woodworking saw"}, {"hanzi": "钢锯子", "en": "hacksaw"}, {"hanzi": "拉锯子", "en": "pull a saw back and forth"}, {"hanzi": "锋利的锯子", "en": "sharp saw"}], "idioms": [{"hanzi": "锯齿齿", "pinyin": "jù chǐ chǐ", "meaning_en": "jagged like saw teeth; serrated"}, {"hanzi": "笨口拙舌", "pinyin": "bèn kǒu zhuō shé", "meaning_en": "clumsy in speech; tongue-tied like a stuck saw"}, {"hanzi": "斧锯齐下", "pinyin": "fǔ jù qí xià", "meaning_en": "axes and saws striking together; forceful radical overhaul"}, {"hanzi": "刻舟求剑", "pinyin": "kè zhōu qiú jiàn", "meaning_en": "notching boat to find fallen sword; rigid outdated methods"}], "character_decomposition": [{"character": "锯", "pinyin": "jù", "meaning_en": "saw; to saw; cut with a saw", "meaning_es": "sierra; serrar; cortar con sierra", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (metal blade)", "sound_component": "居 (jū / phonetic)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "Metal radical 钅 paired with 居; legend says Lu Ban observed serrated grass leaves cutting fingers and invented the iron saw blade.", "visual_mnemonic_story_en": "Lu Ban forged a strip of sharp metal (钅) with serrated teeth to slice wood where timber settled (居).", "visual_mnemonic_story_es": "Lu Ban forjó una hoja de metal (钅) con dientes afilados para cortar maderos donde se asentaban (居).", "tone_mnemonic_anchor": "51", "cangjie": "OPRJR", "traditional": "鋸"}, {"character": "子", "pinyin": "zi", "meaning_en": "noun suffix; child; son", "meaning_es": "sufijo sustantivo; hijo; crío", "radical": "子", "radical_meaning_en": "child / son", "meaning_component": "pictograph of swaddled infant", "sound_component": "子 (zǐ)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph depicting an infant with outstretched arms, serving here as a productive nominal suffix.", "visual_mnemonic_story_en": "An infant waving little arms (子), attached here to tool names to form common nouns.", "visual_mnemonic_story_es": "Un bebé con brazos abiertos (子), añadido a nombres de herramientas como sufijo nominal.", "tone_mnemonic_anchor": "neutral", "cangjie": "ND", "traditional": "子"}], "extended_reading_passages": [{"id": "#1", "hanzi": "相传古代工匠鲁班在陡峭的山上采集木料时，手指不慎被一种边缘带齿的野草割破。他深受启发，经过反复摸索试验，用铁片打制出带有密密麻麻细齿的锯子，大幅提高了伐木与建筑的作业效率。", "pinyin": "Xiāngchuán gǔdài gōngjiàng Lǔ Bān zài dǒuqiào de shān shang cǎijí mùliào shí, shǒuzhǐ búshèn bèi yī zhǒng biānyuán dài chǐ de yěcǎo gēpò. Tā shēn shòu qǐfā, jīngguò fǎnfù mōsuǒ shìyàn, yòng tiěpiàn dǎzhì chū dài yǒu mìmimámá xìchǐ de jùzi, dàfú tígāo le fámù yǔ jiànzhù de zuòyè xiàolǜ.", "en": "Legend tells that when ancient master craftsman Lu Ban was cutting timber on a steep mountain, his finger was cut by wild serrated grass. Deeply inspired, he hammered iron into toothed saws, dramatically boosting carpentry productivity.", "es": "Cuenta la leyenda que el célebre artesano Lu Ban, cortando madera en el monte, se hirió con una hierba de bordes dentados. Inspirado por ello, forjó sierras de hierro dentadas, elevando enormemente la eficiencia constructiva."}, {"id": "#2", "hanzi": "在早期篮球运动刚刚创立的阶段，人们直接把盛装桃子的竹筐钉在体育馆两端的栏杆上。每次投篮得分之后，工作人员都必须搬来高高的梯子爬上去把球取出，比赛过程因此变得断断续续。直到有人找来锯子直接锯开筐底，才彻底化繁为简。", "pinyin": "Zài zǎoqī lánqiú yùndòng gānggāng chuànglì de jiēduàn, rénmen zhíjiē bǎ chéngzhuāng táozi de zhúkuāng dīng zài tǐyùguǎn liǎngduān de lángān shang. Měicì tóulán défēn zhīhòu, gōngzuò rényuán dōu bìxū bān lái gāogāo de tīzi pá shàngqu bǎ qiú qǔchū, bǐsài guòchéng yīncǐ biàn de duànduàn-xùxù. Zhídào yǒurén zhǎolái jùzi zhíjiē jù kāi kuāngdǐ, cái chèdǐ huà fán wéi jiǎn.", "en": "During the early beginnings of basketball, peach baskets were nailed onto gymnasium railings. Every time a basket was made, staff had to haul tall ladders to retrieve the ball, interrupting the game. Only when someone brought a saw to cut off the bottom did the solution simplify.", "es": "En los albores del baloncesto, se clavaban cestas de melocotón en las barandillas. Tras cada canasta, un auxiliar debía trepar a una escalera para extraer el balón, cortando el ritmo. Bastó usar una sierra para cortar el fondo y simplificarlo todo."}]}, {"meanings_summary": {"en": "basket (open woven container)", "es": "cesta; canasta; cesto"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Bamboo (竹) strips woven into a protective rectangular frame (匡) become a carrying basket (筐).", "composite_memory_hook_es": "Tiras de bambú (竹) entretejidas sobre un armazón (匡) forman una práctica cesta de carga (筐).", "cultural_and_cognitive_roots": "Essential harvest container throughout Chinese agrarian history, woven from resilient southern bamboo.", "tone_sandhi_and_pitch_modulation": "High flat level tone: 'kuāng' (55). Maintain a sustained, resonant high-pitch ring without dropping."}, "semantic_boundary_contrasts": {"core_nuance": "筐 is typically a wide, lidless basket woven of bamboo or wicker, primarily used for coarse farm produce.", "contrasts": [{"id": "1", "compared_word": "筐 vs. 篮子", "pinyin": "lánzi", "analysis": "篮子 usually has an arching handle for carrying personal purchases, whereas 筐 is larger and carried with shoulder poles."}, {"id": "2", "compared_word": "筐 vs. 箱子", "pinyin": "xiāngzi", "analysis": "箱子 denotes a rigid rectangular trunk or box with walls and a closing lid, unlike the open breathable weave of 筐."}, {"id": "3", "compared_word": "筐 vs. 桶", "pinyin": "tǒng", "analysis": "桶 is a watertight wooden or plastic bucket for liquids, whereas 筐 has a porous woven mesh unfit for liquids."}]}, "traps_and_cognates": {"look_alikes": [{"character": "筐", "pinyin": "kuāng", "meaning_en": "basket", "distinction_note": "Has bamboo radical 竹 on top"}, {"character": "匡", "pinyin": "kuāng", "meaning_en": "frame; rectify", "distinction_note": "Base character without bamboo radical"}, {"character": "框", "pinyin": "kuàng", "meaning_en": "frame; casement", "distinction_note": "Has tree/wood radical 木 on the left"}, {"character": "眶", "pinyin": "kuàng", "meaning_en": "eye socket", "distinction_note": "Has eye radical 目 on the left"}], "etymological_cognates": [{"character": "篮", "pinyin": "lán", "gloss_en": "basket with handle"}, {"character": "篓", "pinyin": "lǒu", "gloss_en": "tall wicker hamper"}, {"character": "箱", "pinyin": "xiāng", "gloss_en": "box; chest"}, {"character": "笼", "pinyin": "lóng", "gloss_en": "cage; steamer basket"}]}, "id": "2", "hanzi": "筐", "pinyin": "kuāng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a container woven from split bamboo, wicker, or rattan used for carrying produce or objects", "definition_es": "recipiente tejido de tiras de bambú, mimbre o caña para transportar productos u objetos", "example_phrase": "装满新鲜果子的竹筐 (a bamboo basket filled with fresh fruit)"}], "example_sentences": [{"id": "#1", "hanzi": "果农们天不亮就挑着沉甸甸的竹筐赶往集市，筐里装满了刚采摘下来的水蜜桃。", "pinyin": "Guǒnóngmen tiān bú liàng jiù tiāo zhe chéndiāndiān de zhúkuāng gǎnwǎng jíshì, kuāng lǐ zhuāngmǎn le gāng cǎizhāi xiàlái de shuǐmìtáo.", "en": "Before daybreak, fruit farmers carried heavy bamboo baskets on shoulder poles to the market, the baskets filled with freshly picked juicy peaches.", "es": "Antes del amanecer, los fruticultores cargaban pesadas cestas de bambú camino al mercado, colmadas de melocotones recién cosechados."}, {"id": "#2", "hanzi": "最初发明篮球时，奈史密斯博士把两只装桃子的圆筐挂在墙头作为球门。", "pinyin": "Zuìchū fāmíng lánqiú shí, Nàishǐmīsī bóshì bǎ liǎng zhī zhuāng táozi de yuánkuāng guà zài qiángtóu zuòwéi qiúmén.", "en": "When basketball was first invented, Dr. Naismith hung two round peach baskets on the walls to serve as goals.", "es": "Al inventar el baloncesto, el doctor Naismith colgó dos cestas redondas de melocotones en la pared a modo de metas."}], "collocations": [{"hanzi": "竹筐", "en": "bamboo basket"}, {"hanzi": "一个筐", "en": "a basket (classifier 个)"}, {"hanzi": "筐底", "en": "bottom of a basket"}, {"hanzi": "菜筐", "en": "vegetable basket"}, {"hanzi": "果筐", "en": "fruit basket"}, {"hanzi": "装筐", "en": "pack into a basket"}], "idioms": [{"hanzi": "一筐倾尽", "pinyin": "yī kuāng qīng jìn", "meaning_en": "pour out an entire basket; give all one's resources"}, {"hanzi": "竹篮打水", "pinyin": "zhú lán dǎ shuǐ", "meaning_en": "drawing water with a bamboo basket; all in vain"}, {"hanzi": "同舟共济", "pinyin": "tóng zhōu gòng jì", "meaning_en": "cross the river in the same boat; cooperate in adversity"}, {"hanzi": "满载而归", "pinyin": "mǎn zài ér guī", "meaning_en": "return with a full load; come back richly rewarded"}], "character_decomposition": [{"character": "筐", "pinyin": "kuāng", "meaning_en": "basket", "meaning_es": "cesta; canasto", "radical": "竹", "radical_meaning_en": "bamboo", "meaning_component": "竹 (bamboo weave)", "sound_component": "匡 (kuāng / frame; phonetic)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Bamboo radical 竹 on top over frame 匡; traditionally woven with interlocking bamboo splits inside a rectangular or round frame.", "visual_mnemonic_story_en": "Strips of flexible bamboo (竹) woven inside a sturdy wooden frame (匡) create a spacious farm basket (筐).", "visual_mnemonic_story_es": "Tiras de bambú (竹) entrelazadas en un bastidor resistente (匡) conforman una espaciosa canasta (筐).", "tone_mnemonic_anchor": "55", "cangjie": "HSMG", "traditional": "筐"}], "extended_reading_passages": [{"id": "#1", "hanzi": "深秋时节的山村果园里，红彤彤的苹果压弯了枝头。乡亲们手脚麻利地将采摘下来的鲜果整齐码放进竹筐中，欢声笑语伴随着丰收的喜悦，在漫山遍野的清脆鸟鸣声中久久回荡。", "pinyin": "Shēnqiū shíjié de shāncūn guǒyuán lǐ, hóngtóngtóng de píngguǒ yāwān le zhītóu. Xiāngqīnmen shǒujiǎo málì de jiāng cǎizhāi xiàlái de xiānguǒ zhěngqí mǎfàng jìn zhúkuāng zhōng, huānshēng-xiàoyǔ bànsuí zhe fēngshōu de xǐyuè, zài mànshān-biànyě de qīngcuì niǎomíng shēng zhōng jiǔjiǔ huídàng.", "en": "In late autumn mountain orchards, crimson apples bent the branches. Villagers swiftly arranged freshly gathered fruit into bamboo baskets, their laughter and harvest joy echoing alongside crisp birdsong across the hills.", "es": "En los huertos serranos a finales de otoño, las manzanas doblaban las ramas. Con presteza, los lugareños acomodaban la fruta en cestas de bambú, resonando sus risas y júbilo por doquier entre trinos campestres."}, {"id": "#2", "hanzi": "当年在马萨诸塞州的春田学院，体育教师由于缺乏室内器械，便就地取材把两个盛桃的竹筐固定在离地十英尺的高处。这个不起眼的果筐，不仅成为了现代篮球运动的摇篮，也见证了体育规则在实践中的不断创新与完善。", "pinyin": "Dāngnián zài Mǎsàzhūsuāi zhōu de Chūntián xuéyuàn, tǐyù jiàoshī yóuyú quēfá shìnèi qìxiè, biàn jiùdì-qǔcái bǎ liǎng ge chéng táo de zhúkuāng gùdìng zài lí dì shí yīngchǐ de gāochù. Zhè ge bùqǐyǎn de guǒkuāng, bùjǐn chéngwéi le xiàndài lánqiú yùndòng de yáolán, yě jiànzhèng le tǐyù guīzé zài shíjiàn zhōng de búduàn chuàngxīn yǔ wánshàn.", "en": "Back then at Springfield College in Massachusetts, a gym teacher lacking indoor equipment attached two peach baskets ten feet off the ground. That humble basket not only cradled modern basketball but witnessed sports rules constantly evolving through practice.", "es": "En el Springfield College de Massachusetts, un profesor sin material colgó dos cestas de melocotón a diez pies de altura. Esa humilde cesta fue la cuna del baloncesto moderno y testigo de la evolución de sus reglas."}]}, {"meanings_summary": {"en": "to train; to drill; training", "es": "entrenar; adiestrar; entrenamiento; adiestramiento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Guiding words (训) combined with repetitive silk-like conditioning (练) produce thorough mastery (训练).", "composite_memory_hook_es": "La instrucción verbal (训) combinada con el pulido repetitivo como seda (练) forja el verdadero adiestramiento (训练).", "cultural_and_cognitive_roots": "Derives from ancient martial drills and silk purification metaphors where raw fiber is transformed into strong fabric.", "tone_sandhi_and_pitch_modulation": "Two falling fourth tones: 'xùn liàn' (51-51). Execute two decisive down-slopes without rushing."}, "semantic_boundary_contrasts": {"core_nuance": "训练 emphasizes systematic physical, behavioral, or tactical drill to achieve peak execution under pressure.", "contrasts": [{"id": "1", "compared_word": "训练 vs. 练习", "pinyin": "liànxí", "analysis": "练习 refers to general self-study practice exercises, whereas 训练 entails structured external coaching and discipline."}, {"id": "2", "compared_word": "训练 vs. 培养", "pinyin": "péiyǎng", "analysis": "培养 focuses on long-term nurturing of character, habits, or talent over years, while 训练 targets specific motor and tactical drills."}, {"id": "3", "compared_word": "训练 vs. 锻炼", "pinyin": "duànliàn", "analysis": "锻炼 denotes personal health fitness workout or undergoing hardship, whereas 训练 targets specific competitive standards."}]}, "traps_and_cognates": {"look_alikes": [{"character": "训", "pinyin": "xùn", "meaning_en": "train; instruct", "distinction_note": "Speech radical 讠 with 川"}, {"character": "圳", "pinyin": "zhèn", "meaning_en": "furrow; ditch", "distinction_note": "Earth radical 土 with 川 (e.g. 深圳)"}, {"character": "练", "pinyin": "liàn", "meaning_en": "practice", "distinction_note": "Silk radical 纟 on the left"}, {"character": "炼", "pinyin": "liàn", "meaning_en": "smelt metals; refine", "distinction_note": "Fire radical 火 on the left"}], "etymological_cognates": [{"character": "演", "pinyin": "yǎn", "gloss_en": "drill; perform; evolve"}, {"character": "习", "pinyin": "xí", "gloss_en": "practice; flap wings"}, {"character": "操", "pinyin": "cāo", "gloss_en": "operate; drill"}, {"character": "修", "pinyin": "xiū", "gloss_en": "cultivate; mend"}]}, "id": "3", "hanzi": "训练", "pinyin": "xùn liàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to instruct and exercise repeatedly to acquire physical skills or professional discipline", "definition_es": "instruir y ejercitar metódicamente para adquirir habilidades físicas o disciplina profesional", "example_phrase": "严格训练队员 (strictly train team members)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "systematic physical or mental instruction and practice", "definition_es": "serie de ejercicios sistemáticos de preparación física o técnica", "example_phrase": "高强度的体能训练 (high-intensity physical conditioning)"}], "example_sentences": [{"id": "#1", "hanzi": "为了在下个月的校际运动会上夺冠，长跑队队员们每天清晨都坚持进行五公里耐力训练。", "pinyin": "Wèile zài xià ge yuè de xiàojì yùndònghuì shang duóguàn, chángpǎoduì duìyuánmen měitiān qīngchén dōu jiānchí jìnxíng wǔ gōnglǐ nàilì xùnliàn.", "en": "To win the championship at next month's interschool athletic meet, the long-distance runners persisted in five-kilometer endurance training every dawn.", "es": "Para alzarse con el título en el torneo interescolar del mes próximo, los fondistas realizaban cada alba un entrenamiento de resistencia de cinco kilómetros."}, {"id": "#2", "hanzi": "新员工入职之后必须接受为期三周的系统技能培训与职业素养考核。", "pinyin": "Xīn yuángōng rùzhí zhīhòu bìxū jiēshòu wéiqī sān zhōu de xìtǒng jìnéng péixùn yǔ zhíyè sùyǎng kǎohé.", "en": "After joining, new employees must undergo three weeks of systematic technical training and professional competency assessments.", "es": "Tras incorporarse, los nuevos empleados deben completar tres semanas de capacitación técnica sistemática y evaluación de competencias profesionales."}], "collocations": [{"hanzi": "严格训练", "en": "strict training / drill"}, {"hanzi": "军事训练", "en": "military training"}, {"hanzi": "体能训练", "en": "physical fitness conditioning"}, {"hanzi": "训练有素", "en": "well-trained; seasoned"}, {"hanzi": "训练基地", "en": "training camp / base"}, {"hanzi": "接受训练", "en": "undergo training"}], "idioms": [{"hanzi": "训练有素", "pinyin": "xùn liàn yǒu sù", "meaning_en": "well-drilled; rigorously prepared through long training"}, {"hanzi": "熟能生巧", "pinyin": "shú néng shēng qiǎo", "meaning_en": "practice makes perfect; skill comes from practice"}, {"hanzi": "厉兵秣马", "pinyin": "lì bīng mò mǎ", "meaning_en": "whet weapons and feed horses; prepare intensively for battle"}, {"hanzi": "刻苦耐劳", "pinyin": "kè kǔ nài láo", "meaning_en": "endure hardships through tireless persevering effort"}], "character_decomposition": [{"character": "训", "pinyin": "xùn", "meaning_en": "teach; instruct; admonish", "meaning_es": "instruir; amaestrar; adoctrinar", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken instruction)", "sound_component": "川 (chuān / flow; phonetic)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Speech radical 讠 with river stream 川; originally guiding words to flow smoothly into understanding like smooth waterways.", "visual_mnemonic_story_en": "Spoken instructions (讠) flow continuously like a river (川) into learners' minds to train their conduct (训).", "visual_mnemonic_story_es": "Las palabras didácticas (讠) fluyen como un río (川) hacia la mente del aprendiz guiando su conducta (训).", "tone_mnemonic_anchor": "51", "cangjie": "IVLL", "traditional": "訓"}, {"character": "练", "pinyin": "liàn", "meaning_en": "practice; drill; refine", "meaning_es": "practicar; ejercitar; curtir", "radical": "纟", "radical_meaning_en": "silk thread", "meaning_component": "纟 (raw silk threads)", "sound_component": "东 / 练 (phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Silk radical 纟 beside 练; originally boiling and beating raw coarse silk repeatedly to make it white and supple.", "visual_mnemonic_story_en": "Rough silk fibers (纟) washed and boiled repeatedly under the eastern sun until perfected through practice (练).", "visual_mnemonic_story_es": "Hebras de seda (纟) lavadas y hervidas una y otra vez bajo el sol oriental hasta purificarse mediante la práctica (练).", "tone_mnemonic_anchor": "51", "cangjie": "VMDF", "traditional": "練"}], "extended_reading_passages": [{"id": "#1", "hanzi": "寒冬腊月里的训练基地格外安静，队员们却早已汗流浃背。教练一遍又一遍地拆解战术动作，纠正每一个细小的传球失误。正是在这种千百次枯燥重复的刻苦训练中，队伍培养出了默契与坚不可摧的团队意志。", "pinyin": "Hándōng-làyuè lǐ de xùnliàn jīdì géwài ānjìng, duìyuánmen què zǎoyǐ hànliújiābèi. Jiàoliàn yí biàn yòu yí biàn de chāijiě zhànshù dòngzuò, jiūzhèng měi yí ge xìxiǎo de chuánqiú shīwù. Zhèng shì zài zhè zhǒng qiānbǎicì kūzào chóngfù de kèkǔ xùnliàn zhōng, duìwù péiyǎng chū le mòqì yǔ jiānbùkěcuī de tuánduì yìzhì.", "en": "The training base was quiet in the bitter winter, yet the players were already drenched in sweat. The coach dismantled tactical movements repeatedly, correcting small passing errors. Through this grueling repetition, the team forged chemistry and indomitable will.", "es": "La base deportiva permanecía en silencio en el crudo invierno, mas los jugadores sudaban a mares. El entrenador desgranaba las tácticas corrigiendo cada pase. En esa ardua repetición, el equipo forjó compenetración y temple inquebrantable."}, {"id": "#2", "hanzi": "当年奈史密斯发明篮球运动的初衷，正是为了在漫长寒冷的冬季为学生提供一种无需面对面激烈冲撞的室内体能训练方式。然而随着时代发展，现代篮球训练对运动员的速度、爆发力及战术素养提出了更为严苛的综合要求。", "pinyin": "Dāngnián Nàishǐmīsī fāmíng lánqiú yùndòng de chūzhōng, zhèng shì wèile zài màncháng hánlěng de dōngjì wèi xuésheng tígōng yī zhǒng wúxū miànduìmiàn jīliè chōngzhuàng de shìnèi tǐnéng xùnliàn fāngshì. Rán'ér suízhe shídài fāzhǎn, xiàndài lánqiú xùnliàn duì yùndòngyuán de sùdù, bàofālì jí zhànshù sùyǎng tíchū le gèng wéi yánkē de zōnghé yāoqiú.", "en": "Naismith's original intention was to provide students with an indoor conditioning method free from violent collisions during harsh winters. As eras shifted, modern basketball training has raised demanding standards for speed, explosive power, and tactical prowess.", "es": "Naismith concibió el baloncesto para dotar a los alumnos de entrenamiento bajo techo sin colisiones bruscas durante el crudo invierno. No obstante, el entrenamiento actual exige una velocidad, potencia explosiva y lectura táctica superlativas."}]}, {"meanings_summary": {"en": "to lack; to be deficient in; shortage", "es": "carecer de; faltar; escasear; deficiencia"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When a chipped pottery bowl (缺) runs out of provisions, you suffer from a total lack (缺乏).", "composite_memory_hook_es": "Cuando una vasija desportillada (缺) agota sus víveres, se padece una total escasez (缺乏).", "cultural_and_cognitive_roots": "Derived from ancient grain storage metaphors where cracked vessels leak grain, resulting in impoverishment.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by rising tone: 'quē fá' (55-35). Hold a clean high pitch on 'quē', then soar upward on 'fá'."}, "semantic_boundary_contrasts": {"core_nuance": "缺乏 denotes the absence or insufficiency of intangible qualities or vital resources needed for success.", "contrasts": [{"id": "1", "compared_word": "缺乏 vs. 缺少", "pinyin": "quēshǎo", "analysis": "缺少 is often used for countable items or people (缺少两人), while 缺乏 applies to abstract qualities (缺乏经验, 缺乏耐心)."}, {"id": "2", "compared_word": "缺乏 vs. 贫乏", "pinyin": "pínfá", "analysis": "贫乏 implies utter cultural, spiritual, or linguistic poverty (语言贫乏), while 缺乏 simply means falling below necessary quota."}, {"id": "3", "compared_word": "缺乏 vs. 损失", "pinyin": "sǔnshī", "analysis": "损失 denotes tangible damage or loss of what was already possessed, while 缺乏 describes non-existence of resources."}]}, "traps_and_cognates": {"look_alikes": [{"character": "缺", "pinyin": "quē", "meaning_en": "lack; gap", "distinction_note": "Contains pottery radical 缶 on the left"}, {"character": "决", "pinyin": "jué", "meaning_en": "decide; determine", "distinction_note": "Contains ice/water radical 冫 with 夬"}, {"character": "乏", "pinyin": "fá", "meaning_en": "lacking; weary", "distinction_note": "4 strokes starting with slanted撇 and horizontal line"}, {"character": "之", "pinyin": "zhī", "meaning_en": "possessive particle; go", "distinction_note": "Top dot 丶 instead of slanted horizontal hook"}], "etymological_cognates": [{"character": "少", "pinyin": "shǎo", "gloss_en": "few; little"}, {"character": "短", "pinyin": "duǎn", "gloss_en": "short; deficient"}, {"character": "贫", "pinyin": "pín", "gloss_en": "poor; destitute"}, {"character": "耗", "pinyin": "hào", "gloss_en": "consume; deplete"}]}, "id": "4", "hanzi": "缺乏", "pinyin": "quē fá", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to not have enough of something necessary (resources, experience, vitality, or confidence)", "definition_es": "no disponer de la cantidad suficiente de algo indispensable o valioso", "example_phrase": "缺乏实际经验 (lack practical experience)"}], "example_sentences": [{"id": "#1", "hanzi": "由于长期缺乏户外运动和充足的阳光照射，不少办公室白领出现了亚健康症状。", "pinyin": "Yóuyú chángqī quēfá hùwài yùndòng hé chōngzú de yángguāng zhàoshè, bùshǎo bàngōngshì báilǐng chūxiàn le yàjiànkāng zhèngzhuàng.", "en": "Due to a prolonged lack of outdoor exercise and sufficient sunshine, many office white-collar workers exhibit sub-health symptoms.", "es": "Debido a una prolongada carencia de ejercicio al aire libre y luz solar, muchos oficinistas manifiestan síntomas de fatiga crónica."}, {"id": "#2", "hanzi": "这家初创公司在技术研发上极具前瞻性，但在海外市场开拓方面依然严重缺乏专业人才。", "pinyin": "Zhè jiā chūchuàng gōngsī zài jìshù yánfā shang jí jù qiánzhānxìng, dàn zài hǎiwài shìchǎng kāituò fāngmiàn yīrán yánzhòng quēfá zhuānyè réncái.", "en": "This startup is visionary in technology R&D, but still severely lacks experienced professionals in overseas market expansion.", "es": "Esta empresa emergente es visionaria en desarrollo técnico, pero aún acusa una grave falta de profesionales para expandirse al extranjero."}], "collocations": [{"hanzi": "缺乏经验", "en": "lack experience"}, {"hanzi": "缺乏资金", "en": "lack financial funds"}, {"hanzi": "缺乏信心", "en": "lack confidence"}, {"hanzi": "缺乏证据", "en": "lack evidence"}, {"hanzi": "严重缺乏", "en": "severely lack"}, {"hanzi": "缺乏耐心", "en": "lack patience"}], "idioms": [{"hanzi": "捉襟见肘", "pinyin": "zhuō jīn jiàn zhǒu", "meaning_en": "pull up sleeves and reveal elbows; severely strapped for resources"}, {"hanzi": "缺衣少食", "pinyin": "quē yī shǎo shí", "meaning_en": "short of food and clothing; living in dire poverty"}, {"hanzi": "供不应求", "pinyin": "gōng bù yìng qiú", "meaning_en": "supply falls short of demand; acute shortages"}, {"hanzi": "短斤少两", "pinyin": "duǎn jīn shǎo liǎng", "meaning_en": "give short weight; lack fair measure"}], "character_decomposition": [{"character": "缺", "pinyin": "quē", "meaning_en": "deficient; gap; lack", "meaning_es": "falta; defecto; hendidura", "radical": "缶", "radical_meaning_en": "earthenware pot", "meaning_component": "缶 (earthen jar with chipped rim)", "sound_component": "夬 (guài / break off; phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Pottery jar radical 缶 beside 夬 (archery glove/breach); an earthenware jar missing a chip on its rim, denoting an incomplete defect.", "visual_mnemonic_story_en": "A clay pottery jar (缶) chipped and cracked at the rim (夬) shows an obvious gap or deficiency (缺).", "visual_mnemonic_story_es": "Una vasija de arcilla (缶) desportillada en su borde (夬) muestra una hendidura o carencia (缺).", "tone_mnemonic_anchor": "55", "cangjie": "OUDK", "traditional": "缺"}, {"character": "乏", "pinyin": "fá", "meaning_en": "short of; tired; depleted", "meaning_es": "carente; exhausto; falto", "radical": "丿", "radical_meaning_en": "slash", "meaning_component": "distorted inverted pictograph of 正 (straight foot)", "sound_component": "乏 (fá)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Inversion of 正 (walking upright); walking in reverse or limping from exhaustion, depleted of strength and provisions.", "visual_mnemonic_story_en": "Footsteps wavering backward due to sheer exhaustion, signaling that vital energy has run out (乏).", "visual_mnemonic_story_es": "Pasos tambaleantes que retroceden por agotamiento, señal de que las provisiones se han vaciado (乏).", "tone_mnemonic_anchor": "35", "cangjie": "HINO", "traditional": "乏"}], "extended_reading_passages": [{"id": "#1", "hanzi": "年轻人在职业规划初期往往缺乏对行业全貌的清醒认识，容易在盲目跟风中迷失方向。唯有多向经验丰富的行业前辈请教，踏踏实实深入一线岗位磨练，才能有效弥补知识结构的短板与实战能力的匮乏。", "pinyin": "Niánqīngrén zài zhíyè guīhuà chūqī wǎngwǎng quēfá duì hángyè quánmào de qīngxǐng rènshi, róngyì zài mángmù gēnfēng zhōng míshī fāngxiàng. Wéi yǒu duō xiàng jīngyàn fēngfù de hángyè qiánbèi qǐngjiào, tātā-shíshí shēnrù yīxiàn gǎngwèi móliàn, cái néng yǒuxiào míbǔ zhīshi jiégòu de duǎnbǎn yǔ shízhàn nénglì de kuìfá.", "en": "Young people often lack clear insight into their industries early in their careers, easily drifting with trends. Only by consulting veterans and gaining solid frontline experience can they remedy blind spots in their knowledge.", "es": "Los jóvenes carecen a menudo de una visión lúcida de su profesión al inicio, perdiéndose en modas. Sólo consultando a veteranos y fogueándose en el terreno compensarán las lagunas de su formación práctica."}, {"id": "#2", "hanzi": "当年奈史密斯发明篮球运动时，学校正缺乏专门的室内器械与活动经费。然而物质条件的缺乏并没有阻碍创新的诞生，反倒逼迫他跳出思维惯性，用两只极为廉价的竹筐巧妙设计出风靡全球的体育项目。", "pinyin": "Dāngnián Nàishǐmīsī fāmíng lánqiú yùndòng shí, xuéxiào zhèng quēfá zhuānmén de shìnèi qìxiè yǔ huódòng jīngfèi. Rán'ér wùzhì tiáojiàn de quēfá bìng méiyǒu zǔ'ài chuàngxīn de dànshēng, fǎndào bīpò tā tiào chū sīwéi guànxìng, yòng liǎng zhī jíwéi liánjià de zhúkuāng qiǎomiào shèjì chū fēngmí quánqiú de tǐyù xiàngmù.", "en": "When Naismith invented basketball, the school lacked indoor apparatus and athletic funding. Yet this material scarcity never stifled innovation; instead, it prompted him to break mental ruts and use two cheap peach baskets to birth a worldwide sport.", "es": "Cuando Naismith ideó el baloncesto, la escuela carecía de equipamiento y fondos. Lejos de frenar la creatividad, tal escasez le forzó a quebrar la rutina, concibiendo con dos canastas baratas un deporte universal."}]}, {"meanings_summary": {"en": "project; program; sports event; item", "es": "proyecto; programa; disciplina deportiva; rubro"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Items checked off under the supervisor's neck (项) and watchful eyes (目) form a completed project (项目).", "composite_memory_hook_es": "Los rubros revisados bajo la nuca (项) y la atenta mirada (目) constituyen un proyecto culminado (项目).", "cultural_and_cognitive_roots": "Derived from classical Chinese cataloging where '项' and '目' formed tabular ledger columns for bureaucratic supervision.", "tone_sandhi_and_pitch_modulation": "Two falling fourth tones: 'xiàng mù' (51-51). Deliver both syllables with crisp, distinct downward force."}, "semantic_boundary_contrasts": {"core_nuance": "项目 designates an organized undertaking or a specific event category in sports or enterprise.", "contrasts": [{"id": "1", "compared_word": "项目 vs. 计划", "pinyin": "jìhuà", "analysis": "计划 refers to the forward-looking plan or schedule, whereas 项目 is the concrete endeavor encompassing funding, team, and deliverables."}, {"id": "2", "compared_word": "项目 vs. 方案", "pinyin": "fāng'àn", "analysis": "方案 is a proposed blueprint or problem-solving strategy, while 项目 is the overarching entity being implemented."}, {"id": "3", "compared_word": "项目 vs. 任务", "pinyin": "rènwu", "analysis": "任务 is a specific delegated assignment or task, whereas 项目 is broader and composed of hundreds of individual tasks."}]}, "traps_and_cognates": {"look_alikes": [{"character": "项", "pinyin": "xiàng", "meaning_en": "project; neck", "distinction_note": "Has 工 on left and 页 on right"}, {"character": "顶", "pinyin": "dǐng", "meaning_en": "top; peak; withstand", "distinction_note": "Has 丁 on left instead of 工"}, {"character": "目", "pinyin": "mù", "meaning_en": "eye; catalog", "distinction_note": "Vertical rectangle with two horizontal strokes inside"}, {"character": "日", "pinyin": "rì", "meaning_en": "sun; day", "distinction_note": "Has only one horizontal stroke inside"}], "etymological_cognates": [{"character": "案", "pinyin": "àn", "gloss_en": "case; record; plan"}, {"character": "划", "pinyin": "huà", "gloss_en": "plan; divide"}, {"character": "程", "pinyin": "chéng", "gloss_en": "journey; program"}, {"character": "款", "pinyin": "kuǎn", "gloss_en": "clause; fund"}]}, "id": "5", "hanzi": "项目", "pinyin": "xiàng mù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a planned endeavor undertaking a specific objective within defined scope and budget", "definition_es": "empresa o trabajo planificado con objetivos, plazos y recursos específicos", "example_phrase": "负责一个重大科研项目 (lead a major scientific research project)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a specific category in sports competitions or itemized list", "definition_es": "prueba o modalidad deportiva en competiciones", "example_phrase": "奥运会田径比赛项目 (track and field events in the Olympics)"}], "example_sentences": [{"id": "#1", "hanzi": "经过两年的刻苦攻关，研发团队终于提前完成了这座现代化跨海大桥的总体设计项目。", "pinyin": "Jīngguò liǎng nián de kèkǔ gōngguān, yánfā tuánduì zhōngyú tíqián wánchéng le zhè zuò xiàndàihuà kuàhǎi dàqiáo de zǒngtǐ shèjì xiàngmù.", "en": "After two years of hard research, the R&D team finally completed the overarching design project for this modern sea-crossing bridge ahead of schedule.", "es": "Tras dos años de intensa labor, el equipo completó antes del plazo previsto el proyecto de diseño integral del moderno puente marítimo."}, {"id": "#2", "hanzi": "篮球在十九世纪末作为一项全新的体育项目诞生，如今已成为全球参与人数最多的运动之一。", "pinyin": "Lánqiú zài shíjiǔ shìjì mò zuòwéi yī xiàng quánxīn de tǐyù xiàngmù dànshēng, rújīn yǐ chéngwéi quánqiú cānyù rénshù zuì duō de yùndòng zhī yī.", "en": "Basketball was born in the late 19th century as a brand-new sporting event, and has now become one of the most widely played sports in the world.", "es": "Nacido a finales del siglo XIX como una disciplina deportiva inédita, el baloncesto es hoy uno de los deportes más practicados del planeta."}], "collocations": [{"hanzi": "重大项目", "en": "major project"}, {"hanzi": "体育项目", "en": "sporting event / discipline"}, {"hanzi": "项目经理", "en": "project manager"}, {"hanzi": "启动项目", "en": "launch a project"}, {"hanzi": "投资项目", "en": "investment project"}, {"hanzi": "项目进展", "en": "project progress"}], "idioms": [{"hanzi": "立竿见影", "pinyin": "lì gān jiàn yǐng", "meaning_en": "set up pole and see shadow; yield instantaneous results"}, {"hanzi": "开宗明义", "pinyin": "kāi zōng míng yì", "meaning_en": "state the main purpose right at the beginning"}, {"hanzi": "各具特色", "pinyin": "gè jù tè sè", "meaning_en": "each having its own distinct characteristics"}, {"hanzi": "纲举目张", "pinyin": "gāng jǔ mù zhāng", "meaning_en": "lift main rope and mesh spreads; organize systematically"}], "character_decomposition": [{"character": "项", "pinyin": "xiàng", "meaning_en": "nape of neck; item; clause; sum", "meaning_es": "nuca; rubro; artículo; proyecto", "radical": "工", "radical_meaning_en": "work / craft", "meaning_component": "工 (artisan work) + 页 (head/neck pictograph)", "sound_component": "工 (gōng / phonetic connection)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Craft 工 beside head 页; originally the nape of the neck, extended metaphorically to individual bullet items on an official register.", "visual_mnemonic_story_en": "A clerk bowing his neck (页) over artisan blueprints (工), recording every distinct project clause (项).", "visual_mnemonic_story_es": "Un escriba inclinando la nuca (页) sobre los planos de obra (工), detallando cada rubro del proyecto (项).", "tone_mnemonic_anchor": "51", "cangjie": "MOMBO", "traditional": "項"}, {"character": "目", "pinyin": "mù", "meaning_en": "eye; item; catalog; index", "meaning_es": "ojo; índice; epígrafe; categoría", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "pictograph of human eye and pupil", "sound_component": "目 (mù)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph of an eyeball and eyelids turned vertically; extended to lines of sight and catalog entries.", "visual_mnemonic_story_en": "An observant eye (目) looking straight ahead, reviewing catalog items one by one.", "visual_mnemonic_story_es": "Un ojo atento (目) mirando de frente, catalogando cada apartado en la lista.", "tone_mnemonic_anchor": "51", "cangjie": "BU", "traditional": "目"}], "extended_reading_passages": [{"id": "#1", "hanzi": "大型跨国工程项目的成败，往往取决于项目经理对风险控制与多团队协同沟通的掌控能力。在错综复杂的施工过程中，任何一个关键节点的延误都可能导致连锁反应，甚至给整体工期带来不可挽回的巨大经济损失。", "pinyin": "Dàxíng kuàguó gōngchéng xiàngmù de chéngbài, wǎngwǎng qǔjué yú xiàngmù jīnglǐ duì fēngxiǎn kòngzhì yǔ duō tuánduì xiétóng gōutōng de zhǎngkòng nénglì. Zài cuòzōng-fùzá de shīgōng guòchéng zhōng, rènhé yí ge guānjiàn jiédiǎn de yánwù dōu kěnéng dǎozhì liánsuǒ fǎnyìng, shènzhì gěi zhěngtǐ gōngqī dài lái bùkě wǎnhuí de jùdà jīngjì sǔnshī.", "en": "The success of mega multinational engineering projects hinges on project managers' grasp of risk control and cross-team communication. In intricate workflows, any delay in key milestones can trigger domino reactions and huge economic losses.", "es": "El éxito de grandes proyectos de ingeniería depende del control de riesgos y la coordinación de equipos. En obras complejas, el retraso en un hito clave desencadena efectos dominó que conllevan cuantiosas pérdidas económicas."}, {"id": "#2", "hanzi": "篮球最初只是作为冬季避免学生受寒的室内辅助项目，谁料在短短数十年间，它便凭借极高的观赏性与竞技魅力迅速风靡五大洲。如今，它不仅是奥运会最引人瞩目的核心比赛项目，更催生了产值数十亿美元的全球体育产业链。", "pinyin": "Lánqiú zuìchū zhǐshì zuòwéi dōngjì bìmiǎn xuésheng shòuhán de shìnèi fǔzhù xiàngmù, shuí liào zài duǎnduǎn shùshí nián jiān, tā biàn píngjiè jí gāo de guānshǎngxìng yǔ jìngjì mèilì xùnsù fēngmí wǔ dàzhōu. Rújīn, tā bùjǐn shì Àoyùnhuì zuì yǐnrén zhǔmù de héxīn bǐsài xiàngmù, gèng cuīshēng le chǎnzhí shùshí yì měiyuán de quánqiú tǐyù chǎnyèliàn.", "en": "Basketball was originally an auxiliary indoor program to protect students from the winter chill. Yet within decades, its athletic allure captivated five continents. Today, it is not only an Olympic cornerstone but drives a multibillion-dollar global sports empire.", "es": "El baloncesto nació como una disciplina bajo techo contra el frío invernal. En pocas décadas, su espectacularidad conquistó el mundo. Hoy es una prueba olímpica cumbre que impulsa un sector comercial multimillonario."}]}, {"meanings_summary": {"en": "peach (fruit or tree)", "es": "melocotón; durazno"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A sacred fruit tree (木) bearing auspicious omen-marked pits (兆) gives sweet peaches (桃).", "composite_memory_hook_es": "Un árbol (木) cuyos frutos encierran un hueso de buen agüero (兆) es el melocotonero (桃).", "cultural_and_cognitive_roots": "Revered in Daoist myth as the Queen Mother's divine fruit of immortality (蟠桃), representing longevity and warding against evil spirits.", "tone_sandhi_and_pitch_modulation": "Rising second tone: 'táo' (35). Rise cleanly from mid-pitch to high, smooth and resonant."}, "semantic_boundary_contrasts": {"core_nuance": "桃 refers specifically to the peach tree or its downy sweet stone fruit, rich in longevity symbolism.", "contrasts": [{"id": "1", "compared_word": "桃 vs. 李", "pinyin": "lǐ", "analysis": "桃 is larger with downy skin and furrowed stone, whereas 李 (plum) has smooth skin and is more tart."}, {"id": "2", "compared_word": "桃 vs. 杏", "pinyin": "xìng", "analysis": "杏 (apricot) is smaller with orange-golden flesh, while 桃 has pink-tinged juicy flesh."}, {"id": "3", "compared_word": "桃 vs. 苹果", "pinyin": "píngguǒ", "analysis": "苹果 has a crisp interior core with multiple seeds, while 桃 possesses a single hard woody central stone."}]}, "traps_and_cognates": {"look_alikes": [{"character": "桃", "pinyin": "táo", "meaning_en": "peach", "distinction_note": "Tree radical 木 on left"}, {"character": "挑", "pinyin": "tiāo", "meaning_en": "pick; carry on pole", "distinction_note": "Hand radical 扌 on left"}, {"character": "逃", "pinyin": "táo", "meaning_en": "flee; escape", "distinction_note": "Movement radical 辶 at the bottom"}, {"character": "眺", "pinyin": "tiào", "meaning_en": "look far into distance", "distinction_note": "Eye radical 目 on left"}], "etymological_cognates": [{"character": "李", "pinyin": "lǐ", "gloss_en": "plum"}, {"character": "杏", "pinyin": "xìng", "gloss_en": "apricot"}, {"character": "梨", "pinyin": "lí", "gloss_en": "pear"}, {"character": "枣", "pinyin": "zǎo", "gloss_en": "jujube / date"}]}, "id": "6", "hanzi": "桃", "pinyin": "táo", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a round, juicy, sweet fruit with soft downy skin and a rough furrowed stone; also the peach tree", "definition_es": "fruta redonda de pulpa jugosa, piel aterciopelada y hueso rugoso; también el árbol melocotonero", "example_phrase": "鲜嫩多汁的蜜桃 (tender and juicy honey peach)"}], "example_sentences": [{"id": "#1", "hanzi": "每年七八月份正是蜜桃成熟的黄金季节，满树沉甸甸的粉红果实散发出诱人的甜香。", "pinyin": "Měinián qī-bā yuèfèn zhèng shì mìtáo chéngshú de huángjīn jìjié, mǎn shù chéndiāndiān de fěnhóng guǒshí sànfā chū yòurén de tiánxiāng.", "en": "Every July and August marks the peak season for honey peaches, when trees bowed under pink fruits give off enticing sweet fragrances.", "es": "Julio y agosto marcan el apogeo de los melocotones; los árboles cargados de frutos rosados despiden un dulce aroma tentador."}, {"id": "#2", "hanzi": "在我国传统文化中，桃子因其吉祥寓意常被用作庆祝老人大寿的贺礼寿桃。", "pinyin": "Zài wǒguó chuántǒng wénhuà zhōng, táozi yīn qí jíxiáng yùyì cháng bèi yòng zuò qìngzhù lǎorén dàshòu de hèlǐ shòutáo.", "en": "In traditional Chinese culture, peaches symbolize longevity and are frequently given as congratulatory longevity peaches on seniors' birthdays.", "es": "En la cultura china, el melocotón simboliza longevidad y se ofrenda tradicionalmente en banquetes de cumpleaños de ancianos."}], "collocations": [{"hanzi": "水蜜桃", "en": "honey peach"}, {"hanzi": "寿桃", "en": "longevity peach (confectionery/fruit)"}, {"hanzi": "桃树", "en": "peach tree"}, {"hanzi": "桃花", "en": "peach blossom"}, {"hanzi": "桃子", "en": "peach (common noun)"}, {"hanzi": "核桃", "en": "walnut"}], "idioms": [{"hanzi": "世外桃源", "pinyin": "shì wài táo yuán", "meaning_en": "the Peach Blossom Spring; a hidden haven of peace"}, {"hanzi": "投桃报李", "pinyin": "tóu táo bào lǐ", "meaning_en": "give a peach and get a plum in return; exchange mutual courtesies"}, {"hanzi": "桃李满天下", "pinyin": "táo lǐ mǎn tiān xià", "meaning_en": "peaches and plums across the land; distinguished students everywhere"}, {"hanzi": "人面桃花", "pinyin": "rén miàn táo huā", "meaning_en": "a fair lady's face like peach blossoms; nostalgia for past beauty"}], "character_decomposition": [{"character": "桃", "pinyin": "táo", "meaning_en": "peach", "meaning_es": "melocotón; durazno", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (fruit tree / wood)", "sound_component": "兆 (zhào / split; omen; phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Tree radical 木 beside 兆 (cracking turtle plastron); the fruit of the peach tree with its deeply cleft stone, highly esteemed for warding off evil.", "visual_mnemonic_story_en": "A fruitful tree (木) bearing sacred fruits with omen-like cleft pits (兆): the blessed peach (桃).", "visual_mnemonic_story_es": "Un árbol frutal (木) cuyos frutos tienen un hueso hendido con presagio propicio (兆): el melocotón (桃).", "tone_mnemonic_anchor": "35", "cangjie": "DLMO", "traditional": "桃"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代文人常将桃树视为超脱尘俗的象征，陶渊明笔下的《桃花源记》便描绘了一个没有赋税徭役、民风淳朴安详的理想国度。千百年来，那一树树芬芳灿烂的桃花，寄托了中国人对安宁生活的无限憧憬。", "pinyin": "Zhōngguó gǔdài wénrén cháng jiāng táoshù shìwéi chāotuō chénsú de xiàngzhēng, Táo Yuānmíng bǐxià de Táo Huā Yuán Jì biàn miáohuì le yí ge méiyǒu fùshuì yáoyì, mínfēng chúnpǔ ānxiáng de lǐxiǎng guódù. Qiānbǎinián lái, nà yí shùshù fēnfāng cànlàn de táohuā, jìtuō le Zhōngguórén duì ānníng shēnghuó de wúxiàn chōngjǐng.", "en": "Ancient Chinese scholars revered peach trees as symbols of transcending vulgarity; Tao Yuanming's Peach Blossom Spring depicted a tranquil haven free from taxes. For centuries, radiant peach blossoms embodied enduring yearnings for peace.", "es": "Los literatos chinos veían en el melocotonero un símbolo utópico; Tao Yuanming retrató en su célebre fábula un remanso sin tributos ni discordias. Esas flores encarnaron el anhelo secular de una existencia sosegada."}, {"id": "#2", "hanzi": "篮球运动在起步之初，所使用的球筐正是从当地果农手中找来的两个装桃子的竹筐。谁也没有料到，这个本用来盛放鲜桃的简陋农具，竟然在无意间成就了一项世界级的伟大体育发明，并在百年时光中持续带给全人类无尽的欢乐。", "pinyin": "Lánqiú yùndòng zài qǐbù zhī chū, suǒ shǐyòng de qiúkuāng zhèng shì cóng dāngdì guǒnóng shǒuzhōng zhǎolái de liǎng ge zhuāng táozi de zhúkuāng. Shuí yě méiyǒu liàodào, zhè ge běn yònglái chéngfàng xiāntáo de jiǎnlòu nóngjù, jìngrán zài wúyì jiān chéngjiù le yí xiàng shìjièjí de wěidà tǐyù fāmíng, bìng zài bǎinián shíguāng zhōng chíxù dài gěi quán rénlèi wújìn de huānlè.", "en": "At its inception, basketball used two peach baskets sourced from local orchardists. No one anticipated that these humble farm containers, meant for sweet fruit, would serendipitously birth a legendary sport that has brought boundless joy to mankind for over a century.", "es": "En sus inicios, el baloncesto empleó dos cestas de melocotón cedidas por campesinos. Nadie previó que un apero rural para cargar fruta alumbraría un invento deportivo monumental, brindando dicha a millones durante más de un siglo."}]}, {"meanings_summary": {"en": "to load; pack; hold; install; pretend; outfit", "es": "cargar; empacar; contener; instalar; fingir; vestimenta"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A sturdy warrior (壮) dressing in heavy clothing (衣) packs supplies and installs gear (装).", "composite_memory_hook_es": "Un guerrero fuerte (壮) poniéndose ropa (衣) para empacar y montar su equipo de viaje (装).", "cultural_and_cognitive_roots": "Began as preparing baggage and outfitting oneself for distant expeditions along trade routes.", "tone_sandhi_and_pitch_modulation": "Level high tone: 'zhuāng' (55). Pronounce with sustained high vocal pitch without fading."}, "semantic_boundary_contrasts": {"core_nuance": "装 covers both placing contents into a container and mounting/fixing parts onto a frame.", "contrasts": [{"id": "1", "compared_word": "装 vs. 盛", "pinyin": "chéng", "analysis": "盛 specifically refers to ladling or holding food/liquids in open bowls (盛饭, 盛汤), while 装 applies broadly to packing luggage or freight."}, {"id": "2", "compared_word": "装 vs. 载", "pinyin": "zài", "analysis": "载 focuses on transportation vehicles bearing payload weight (载重, 载客), while 装 emphasizes the manual packing action."}, {"id": "3", "compared_word": "装 vs. 假装", "pinyin": "jiǎzhuāng", "analysis": "假装 exclusively denotes psychological pretense, whereas 装 has rich mechanical and physical cargo meanings."}]}, "traps_and_cognates": {"look_alikes": [{"character": "装", "pinyin": "zhuāng", "meaning_en": "pack; install; pretend", "distinction_note": "Has clothing radical 衣 at bottom"}, {"character": "妆", "pinyin": "zhuāng", "meaning_en": "makeup; cosmetics", "distinction_note": "Has woman radical 女 beside 丬"}, {"character": "壮", "pinyin": "zhuàng", "meaning_en": "sturdy; strong", "distinction_note": "Upper part without the 衣 base"}, {"character": "袋", "pinyin": "dài", "meaning_en": "bag; sack", "distinction_note": "Has 代 on top over 衣"}], "etymological_cognates": [{"character": "载", "pinyin": "zài", "gloss_en": "load; carry onboard"}, {"character": "盛", "pinyin": "chéng", "gloss_en": "hold in vessel; ladle"}, {"character": "填", "pinyin": "tián", "gloss_en": "fill; stuff"}, {"character": "配", "pinyin": "pèi", "gloss_en": "mate; equip; configure"}]}, "id": "7", "hanzi": "装", "pinyin": "zhuāng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to put things into a container; pack or load goods", "definition_es": "meter o colocar objetos dentro de un recipiente o medio de transporte", "example_phrase": "把行李装进后备箱 (pack luggage into the car trunk)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to assemble, fit, or install equipment", "definition_es": "fijar, acoplar o montar un mecanismo o dispositivo", "example_phrase": "在墙上装空调 (install an air conditioner on the wall)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to pretend; feign; disguise oneself", "definition_es": "aparentar o disimular un estado o sentimiento que no es real", "example_phrase": "装作不知情 (pretend not to know)"}], "example_sentences": [{"id": "#1", "hanzi": "出发去机场前，她把所有重要证件和笔记本电脑都仔细地装进了随身背包里。", "pinyin": "Chūfā qù jīchǎng qián, tā bǎ suǒyǒu zhòngyào zhèngjiàn hé bǐjìběn diànnǎo dōu zǐxì de zhuāng jìn le suíshēn bēibāo lǐ.", "en": "Before setting off for the airport, she carefully packed all her vital documents and laptop into her carry-on backpack.", "es": "Antes de salir hacia el aeropuerto, guardó minuciosamente en su mochila todos los documentos esenciales y el portátil."}, {"id": "#2", "hanzi": "技术工人正在实验室内给新型机器人安装高精度的激光雷达传感器。", "pinyin": "Jìshù gōngrén zhèng zài shíyànshì nèi gěi xīnxíng jīqìrén ānzhuāng gāo jīngdù de jīguāng léidá chuángǎnqì.", "en": "Technicians in the laboratory are currently installing high-precision LiDAR sensors onto the prototype robot.", "es": "Los técnicos montaban en el laboratorio sensores láser de alta precisión en el nuevo prototipo robótico."}], "collocations": [{"hanzi": "装满", "en": "filled up with; pack full"}, {"hanzi": "安装", "en": "install; assemble"}, {"hanzi": "包装", "en": "package; wrap"}, {"hanzi": "装车", "en": "load onto a vehicle"}, {"hanzi": "伪装", "en": "disguise; camouflage"}, {"hanzi": "装模作样", "en": "put on an act; affect airs"}], "idioms": [{"hanzi": "装模作样", "pinyin": "zhuāng mú zuò yàng", "meaning_en": "put on an act; behave with affectation"}, {"hanzi": "装聋作哑", "pinyin": "zhuāng lóng zuò yǎ", "meaning_en": "pretend to be deaf and mute; play dumb"}, {"hanzi": "乔装打扮", "pinyin": "qiáo zhuāng dǎ bàn", "meaning_en": "disguise oneself in elaborate clothes"}, {"hanzi": "满载而归", "pinyin": "mǎn zài ér guī", "meaning_en": "return fully loaded with riches"}], "character_decomposition": [{"character": "装", "pinyin": "zhuāng", "meaning_en": "load; pack; attire; install", "meaning_es": "cargar; vestir; montar; fingir", "radical": "衣", "radical_meaning_en": "clothing", "meaning_component": "衣 (garments / outer cover)", "sound_component": "壮 (zhuàng / sturdy; phonetic)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Sturdy 壮 on top over clothing 衣; packing oneself into robust travel attire, later expanded to packing goods and installing fixtures.", "visual_mnemonic_story_en": "A sturdy warrior (壮) donning protective travel clothes (衣) and packing his provisions (装).", "visual_mnemonic_story_es": "Un recio soldado (壮) vistiéndose con atuendos resistentes (衣) y cargando sus vituallas (装).", "tone_mnemonic_anchor": "55", "cangjie": "VGHO", "traditional": "裝"}], "extended_reading_passages": [{"id": "#1", "hanzi": "母亲总觉得出门在外的游子照顾不好自己。每次临别前，她都会把亲手腌制的小菜和厚实的防寒衣物，一层一层结结实实地装满整个行李箱。那沉甸甸的分量里，装载着道不尽的挂念与深情。", "pinyin": "Mǔqīn zǒng juéde chūmén zàiwài de yóuzǐ zhàogù bù hǎo zìjǐ. Měicì línbié qián, tā dōu huì bǎ qīnshǒu yānzhì de xiǎocài hé hòushi de fánghán yīwù, yì céng yì céng jiējiē-shíshí de zhuāngmǎn zhěnggè xínglǐxiāng. Nà chéndiāndiān de fènliàng lǐ, zhuāngzài zhe dào bú jìn de guàniàn yǔ shēnqíng.", "en": "Mother always worried her traveling child could not care for himself. Before departures, she packed homemade preserves and heavy winter coats tightly into his suitcase. Within that heavy load lay inexhaustible maternal tenderness.", "es": "La madre temía que su hijo pasara privaciones lejos de casa. Antes de cada despedida, empacaba en la maleta viandas caseras y ropa de abrigo. En aquel equipaje repleto viajaba un cariño maternal incondicional."}, {"id": "#2", "hanzi": "在奈史密斯发明篮球之初，工人们把两只用来装桃子的竹筐安装在阳台栏杆下方。然而每次球投进筐里后，都需要人专门踩着梯子把球取出来。为了解决这个麻烦，人们后来才锯掉筐底，实现了篮球顺畅下落的连贯比赛节奏。", "pinyin": "Zài Nàishǐmīsī fāmíng lánqiú zhī chū, gōngrénmen bǎ liǎng zhī yònglái zhuāng táozi de zhúkuāng ānzhuāng zài yángtái lángān xiàfāng. Rán'ér měicì qiú tóu jìn kuāng lǐ hòu, dōu xūyào rén zhuānmén cǎi zhe tīzi bǎ qiú qǔ chūlái. Wèile jiějué zhè ge máfan, rénmen hòulái cái jù diào kuāngdǐ, shíxiàn le lánqiú shùnchàng xiàluò de liánguàn bǐsài jiézòu.", "en": "At basketball's birth, workers mounted two baskets once used to hold peaches beneath the gallery railing. But after each goal, someone had to climb a ladder to extract the ball. To solve this hassle, they later sawed off the basket bottoms to let the ball drop through freely.", "es": "En los orígenes del baloncesto, se instalaron canastas de melocotones bajo la galería. Mas tras cada canasta, se requería trepar a una escalera para sacar el balón. Para agilizar el juego, se serruchó el fondo, permitiendo un flujo continuo."}]}, {"meanings_summary": {"en": "to enlighten; to inspire; inspiration", "es": "inspirar; iluminar; suscitar; inspiración"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Unlocking the mental doorway (启) lets creative insight burst forth like a flying arrow (发) to inspire (启发).", "composite_memory_hook_es": "Abrir la puerta de la mente (启) permite que la inspiración brote como una flecha en vuelo (发) para iluminar (启发).", "cultural_and_cognitive_roots": "Derived from Confucius in the Analects: '不愤不启，不悱不发' (I do not enlighten someone who is not eager to know).", "tone_sandhi_and_pitch_modulation": "Dipping third tone followed by high level tone: 'qǐ fā' (214-55). Dip down deeply on 'qǐ' before ascending to a sustained high 'fā'."}, "semantic_boundary_contrasts": {"core_nuance": "启发 centers on unlocking latent human understanding by giving subtle hints rather than spoon-feeding.", "contrasts": [{"id": "1", "compared_word": "启发 vs. 启示", "pinyin": "qǐshì", "analysis": "启发 is primarily a verb or internal cognitive spark, while 启示 is usually a noun denoting profound religious or philosophical revelation."}, {"id": "2", "compared_word": "启发 vs. 鼓励", "pinyin": "gǔlì", "analysis": "鼓励 focuses on boosting morale, emotional courage, and motivation, whereas 启发 triggers intellectual problem-solving."}, {"id": "3", "compared_word": "启发 vs. 指导", "pinyin": "zhǐdǎo", "analysis": "指导 provides explicit directions and step-by-step instructions, whereas 启发 gently steers one to discover answers independently."}]}, "traps_and_cognates": {"look_alikes": [{"character": "启", "pinyin": "qǐ", "meaning_en": "open; enlighten", "distinction_note": "Single door 户 on top over 口"}, {"character": "扇", "pinyin": "shān", "meaning_en": "fan; flap wings", "distinction_note": "Has 羽 (feathers) inside 户"}, {"character": "房", "pinyin": "fáng", "meaning_en": "room; house", "distinction_note": "Has 方 inside 户"}, {"character": "发", "pinyin": "fā", "meaning_en": "emit; hair", "distinction_note": "5 strokes with upper crossing slant"}], "etymological_cognates": [{"character": "迪", "pinyin": "dí", "gloss_en": "enlighten; guide"}, {"character": "示", "pinyin": "shì", "gloss_en": "show; reveal"}, {"character": "诱", "pinyin": "yòu", "gloss_en": "induce; entice"}, {"character": "导", "pinyin": "dǎo", "gloss_en": "lead; instruct"}]}, "id": "8", "hanzi": "启发", "pinyin": "qǐ fā", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stimulate someone to think and discover truth or creative solutions on their own", "definition_es": "estimular la reflexión en alguien para que descubra soluciones o ideas por sí mismo", "example_phrase": "受到大自然奇妙现象的启发 (inspired by wondrous natural phenomena)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "insight or creative spark obtained from an observation or event", "definition_es": "chispa de comprensión o idea súbita provocada por un suceso", "example_phrase": "这番话给了我很大启发 (these remarks gave me great inspiration)"}], "example_sentences": [{"id": "#1", "hanzi": "在课堂讨论中，老师没有直接给出标准答案，而是通过层层设问来启发学生独立思考。", "pinyin": "Zài kètáng tǎolùn zhōng, lǎoshī méiyǒu zhíjiē gěi chū biāozhǔn dá'àn, érshì tōngguò céngcéng shèwèn lái qǐfā xuésheng dúlì sīkǎo.", "en": "During class discussions, the teacher never handed out standard answers, instead asking probing questions to inspire students to think independently.", "es": "Durante el debate en clase, el profesor no dio respuestas hechas, sino que formuló preguntas para estimular el criterio independiente de los alumnos."}, {"id": "#2", "hanzi": "仿生科学家从荷叶不沾泥水的自洁原理中受到启发，成功研发出了革命性的防水防油纳米涂层。", "pinyin": "Fǎngshēng kēxuéjiā cóng héyè bù zhān níshuǐ de zìjié yuánlǐ zhōng shòudào qǐfā, chénggōng yánfā chū le gémìngxìng de fángshuǐ fángyóu nàmǐ túcéng.", "en": "Biomimetic scientists drew inspiration from the lotus leaf's self-cleaning property, developing revolutionary waterproof and oleophobic nano-coatings.", "es": "Científicos biomiméticos se inspiraron en la flor de loto para crear un revolucionario nanorrevestimiento impermeable y repelente de aceites."}], "collocations": [{"hanzi": "深受启发", "en": "deeply inspired"}, {"hanzi": "启发式教学", "en": "heuristic / elicitation teaching"}, {"hanzi": "受到启发", "en": "receive inspiration"}, {"hanzi": "启发思维", "en": "stimulate thinking"}, {"hanzi": "给予启发", "en": "provide inspiration"}, {"hanzi": "灵感启发", "en": "spark of inspiration"}], "idioms": [{"hanzi": "举一反三", "pinyin": "jǔ yī fǎn sān", "meaning_en": "infer three things from one fact; learn by analogy"}, {"hanzi": "触类旁通", "pinyin": "chù lèi páng tōng", "meaning_en": "comprehend an entire category by understanding one instance"}, {"hanzi": "恍然大悟", "pinyin": "huǎng rán dà wù", "meaning_en": "suddenly see the light; sudden dawn of comprehension"}, {"hanzi": "茅塞顿开", "pinyin": "máo sè dùn kāi", "meaning_en": "thickets of doubt suddenly cleared; suddenly enlightened"}], "character_decomposition": [{"character": "启", "pinyin": "qǐ", "meaning_en": "open; enlighten; initiate", "meaning_es": "abrir; alumbrar; iniciar", "radical": "户", "radical_meaning_en": "single door", "meaning_component": "户 (single door leaflet) + 口 (mouth speaking)", "sound_component": "启 (qǐ)", "stroke_count": "7", "composition_type": "半包围结构", "etymology_and_mnemonic": "Single leaf door 户 over mouth 口; opening the door and speaking words of wisdom to illuminate the uninitiated.", "visual_mnemonic_story_en": "Unlocking a closed doorway (户) with enlightening words (口) to awaken the mind (启).", "visual_mnemonic_story_es": "Abrir una puerta trancada (户) mediante palabras elocuentes (口) para despejar la mente (启).", "tone_mnemonic_anchor": "214", "cangjie": "ISR", "traditional": "啟"}, {"character": "发", "pinyin": "fā", "meaning_en": "send out; expand; develop", "meaning_es": "lanzar; manifestar; florecer", "radical": "又", "radical_meaning_en": "right hand", "meaning_component": "pictograph of releasing an arrow from a drawn bow", "sound_component": "发 (fā)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A drawn bow releasing an arrow; metaphorically emitting, manifesting, and spurring forward development.", "visual_mnemonic_story_en": "Releasing an arrow from a drawn bow, sparking rapid outward flight and expansion (发).", "visual_mnemonic_story_es": "Soltar una flecha tensada en el arco que vuela rauda hacia el blanco manifestándose (发).", "tone_mnemonic_anchor": "55", "cangjie": "IVE", "traditional": "發"}], "extended_reading_passages": [{"id": "#1", "hanzi": "孔子曾说‘不愤不启，不悱不发’，强调教育应当注重时机与意愿。真正优秀的导师从不生硬灌输现成结论，而是善于捕捉求知者心智困顿的节点适度点拨，从而启发他们自己去勘破迷局、领悟人生真谛。", "pinyin": "Kǒngzǐ céng shuō 'bú fèn bù qǐ, bú fěi bù fā', qiángdiào jiàoyù yīngdāng zhùzhòng shíjī yǔ yìyuàn. Zhēnzhèng yōuxiù de dǎoshī cóngbù shēngyìng guànshū xiànchéng jiélùn, érshì shànyú bǔzhuō qiúzhīzhě xīnjié kùndùn de jiédiǎn shìdù diǎnbō, cóng'ér qǐfā tāmen zìjǐ qù kānpò míjú, lǐngwù rénshēng zhēndì.", "en": "Confucius famously asserted that teaching requires receptivity. Great mentors never force-feed conclusions; they identify moments of doubt to drop subtle hints, inspiring seekers to unravel perplexities and grasp life's truths.", "es": "Confucio sostenía que la enseñanza requiere receptividad. Un buen mentor jamás impone conclusiones; detecta las dudas del aprendiz y aporta pistas sutiles, incitándole a disipar enigmas y asimilar la verdad."}, {"id": "#2", "hanzi": "面对工人们每次投篮后不得不反复搬梯子取球的繁琐困扰，一个在场边玩耍的小男孩好奇地问：‘为什么不把筐底直接剪开呢？’这句看似天真无邪的童言，却如同当头棒喝瞬间启发了在场的大人，彻底打破了思维的桎梏。", "pinyin": "Miànduì gōngrénmen měicì tóulán hòu bùdébù fǎnfù bān tīzi qǔ qiú de fánsuǒ kùnrǎo, yí ge zài chǎngbiān wánshuǎ de xiǎo nánhái hàoqí de wèn: 'Wèishénme bù bǎ kuāngdǐ zhíjiē jiǎn kāi ne?' Zhè jù kànsì tiānzhēn-wúxié de tóngyán, què rútóng dāngtóu-bànghè shùnjiān qǐfā le zàichǎng de dàren, chèdǐ dǎpò le sīwéi de zhìgù.", "en": "Faced with the nuisance of fetching ladders after every scored basket, a boy playing courtside innocently asked: 'Why not just cut open the basket bottom?' This naive remark struck the adults like a lightning bolt, inspiring them to shatter rigid mindsets.", "es": "Ante el tedio de subir a una escalera tras cada canasta, un niño preguntó: '¿Por qué no recortan el fondo?' Aquella ingenua observación iluminó a los adultos, quebrando de golpe sus prejuicios mentales."}]}, {"meanings_summary": {"en": "to install; to set up; to mount", "es": "instalar; montar; ensamblar; armar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Carefully settling parts into secure shelter (安) and fastening the fixtures (装) achieves proper installation (安装).", "composite_memory_hook_es": "Asentar piezas con seguridad (安) ajustando los componentes (装) da como resultado una instalación perfecta (安装).", "cultural_and_cognitive_roots": "Evolved from domestic carpentry to modern mechanical engineering and software configuration.", "tone_sandhi_and_pitch_modulation": "Two high level tones: 'ān zhuāng' (55-55). Pronounce with sustained, even pitch across both syllables."}, "semantic_boundary_contrasts": {"core_nuance": "安装 specifically denotes assembling, mounting, or configuring physical fixtures or software.", "contrasts": [{"id": "1", "compared_word": "安装 vs. 组装", "pinyin": "zǔzhuāng", "analysis": "组装 focuses on assembling dispersed components into a finished product, while 安装 emphasizes mounting the finished unit onto a wall or system."}, {"id": "2", "compared_word": "安装 vs. 安置", "pinyin": "ānzhì", "analysis": "安置 means settling people, refugees, or furniture into living spaces, while 安装 deals with technical equipment or software."}, {"id": "3", "compared_word": "安装 vs. 修理", "pinyin": "xiūlǐ", "analysis": "修理 means repairing broken machinery, whereas 安装 is putting brand-new machinery into place initially."}]}, "traps_and_cognates": {"look_alikes": [{"character": "安", "pinyin": "ān", "meaning_en": "peace; install", "distinction_note": "Roof 宀 over 女"}, {"character": "按", "pinyin": "àn", "meaning_en": "press; according to", "distinction_note": "Hand radical 扌 on left of 安"}, {"character": "案", "pinyin": "àn", "meaning_en": "table; case; record", "distinction_note": "Wood radical 木 underneath 安"}, {"character": "装", "pinyin": "zhuāng", "meaning_en": "install; pack", "distinction_note": "Has 衣 at bottom"}], "etymological_cognates": [{"character": "配", "pinyin": "pèi", "gloss_en": "match; allocate; equip"}, {"character": "设", "pinyin": "shè", "gloss_en": "establish; setup"}, {"character": "置", "pinyin": "zhì", "gloss_en": "place; install"}, {"character": "架", "pinyin": "jià", "gloss_en": "frame; erect"}]}, "id": "9", "hanzi": "安装", "pinyin": "ān zhuāng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to place equipment, machinery, fixtures, or software into position and connect ready for use", "definition_es": "fijar y conectar maquinaria, aparatos o programas informáticos dejándolos listos para su uso", "example_phrase": "安装净水器 (install a water purifier)"}], "example_sentences": [{"id": "#1", "hanzi": "装修师傅仅用半天时间，就将全套现代化的智能厨卫设施安装调试完毕了。", "pinyin": "Zhuāngxiū shīfu jǐn yòng bàntiān shíjiān, jiù jiāng quántào xiàndàihuà de zhìnéng chúwèi shèshī ānzhuāng tiáoshì wánbì le.", "en": "In merely half a day, the technician finished installing and tuning the complete suite of modern smart kitchen and bathroom facilities.", "es": "El técnico tardó apenas media jornada en montar y verificar todo el equipamiento inteligente de la cocina y el baño."}, {"id": "#2", "hanzi": "为了保证办公网络环境的数据安全，企业要求所有员工的电脑必须统一定期安装最新的安全补丁。", "pinyin": "Wèile bǎozhèng bàngōng wǎngluò huánjìng de shùjù ānquán, qǐyè yāoqiú suǒyǒu yuángōng de diànnǎo bìxū tǒngyī dìngqī ānzhuāng zuìxīn de ānquán bǔdīng.", "en": "To guarantee data security across office networks, the enterprise requires all employees' computers to regularly install the latest security patches.", "es": "Para garantizar la seguridad en la red corporativa, la empresa exige instalar con regularidad los últimos parches de seguridad en los equipos."}], "collocations": [{"hanzi": "安装调试", "en": "install and calibrate"}, {"hanzi": "安装软件", "en": "install software"}, {"hanzi": "上门安装", "en": "on-site installation service"}, {"hanzi": "安装设备", "en": "install equipment"}, {"hanzi": "免费安装", "en": "free installation"}, {"hanzi": "重新安装", "en": "reinstall"}], "idioms": [{"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live in peace and work with contentment"}, {"hanzi": "转危为安", "pinyin": "zhuǎn wēi wéi ān", "meaning_en": "turn peril into safety; avert danger"}, {"hanzi": "乔装打扮", "pinyin": "qiáo zhuāng dǎ bàn", "meaning_en": "disguise oneself carefully"}, {"hanzi": "安营扎寨", "pinyin": "ān yíng zhā zhài", "meaning_en": "pitch camps and build fortifications; settle down"}], "character_decomposition": [{"character": "安", "pinyin": "ān", "meaning_en": "safe; secure; quiet; settle", "meaning_es": "seguro; tranquilo; asentar", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (roof / sheltered home) + 女 (woman peacefully at home)", "sound_component": "安 (ān)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "A woman 女 sitting safely under a solid roof 宀; ancient symbol of security, calmness, and proper positioning.", "visual_mnemonic_story_en": "A woman (女) seated peacefully beneath a warm roof (宀) embodies safety and settling into place (安).", "visual_mnemonic_story_es": "Una mujer (女) descansando a salvo bajo un hogar seguro (宀) evoca estabilidad y sosiego (安).", "tone_mnemonic_anchor": "55", "cangjie": "JV", "traditional": "安"}, {"character": "装", "pinyin": "zhuāng", "meaning_en": "fit; mount; outfit; load", "meaning_es": "montar; vestir; empacar", "radical": "衣", "radical_meaning_en": "clothing", "meaning_component": "衣 (cover / outfit) + 壮 (sturdy support)", "sound_component": "壮 (zhuàng)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Clothing 衣 affixed upon sturdy 壮 frame; mounting and fitting items securely into place.", "visual_mnemonic_story_en": "Fastening sturdy fixtures (壮) dressed in protective casing (衣) to complete an installation (装).", "visual_mnemonic_story_es": "Fijar piezas robustas (壮) protegidas por carcasas (衣) para ultimar un ensamblaje (装).", "tone_mnemonic_anchor": "55", "cangjie": "VGHO", "traditional": "裝"}], "extended_reading_passages": [{"id": "#1", "hanzi": "智能家居工程师在施工现场一丝不苟地对中央空调与全屋温控系统进行安装。他仔细核对线路图纸，严格排查每处管道接口，以确保这套复杂的自动化设施在未来的日常运转中能够长期保持零故障与高能效。", "pinyin": "Zhìnéng jiājū gōngchéngshī zài shīgōng xiànchǎng yìsī-bùgǒu de duì zhōngyāng kōngtiáo yǔ quánwū wēnkòng xìtǒng jìnxíng ānzhuāng. Tā zǐxì héduì xiànlù túzhǐ, yángé páichá měi chù guǎndào jiēkǒu, yǐ quèbǎo zhè tào fùzá de zìdònghuà shèshī zài wèilái de rìcháng yùnzhuǎn zhōng nénggòu chángqī bǎochí líng gùzhàng yǔ gāo néngxiào.", "en": "The smart home engineer meticulously installed the central air conditioning and whole-house climate control systems on site. He verified wiring schematics and checked pipe joints to ensure the complex automation ran smoothly.", "es": "El técnico de domótica instalaba minuciosamente el climatizador central en la vivienda. Cotejó planos e inspeccionó empalmes para garantizar que el complejo sistema funcionara sin fallos y con óptima eficiencia energética."}, {"id": "#2", "hanzi": "当年奈史密斯发明篮球时，指派学校校工将两只盛桃竹筐安装在室内体育馆两头的栏杆上。谁也没有预料到，这项当时临时起意、极为粗糙的体育设施安装，竟在往后的岁月里演变为一个在全球拥有数以亿计忠实球迷的传奇运动。", "pinyin": "Dāngnián Nàishǐmīsī fāmíng lánqiú shí, zhǐpài xuéxiào xiàogōng jiāng liǎng zhī chéng táo zhúkuāng ānzhuāng zài shìnèi tǐyùguǎn liǎngtóu de lángān shang. Shuí yě méiyǒu yùliào dào, zhè xiàng dāngshí línshí-qǐyì, jíwéi cūcāo de tǐyù shèshī ānzhuāng, jìng zài wǎnghòu de suìyuè lǐ yǎnbiàn wéi yí ge zài quánqiú yǒngyǒu shù yǐ yì jì zhōngshí qiúmí de chuánqí yùndòng.", "en": "When Naismith created basketball, he instructed the custodian to mount two peach baskets onto railings at each end of the gym. No one dreamed that this impromptu installation would grow into a legendary sport with hundreds of millions of devotees.", "es": "Naismith mandó clavar dos cestas de melocotón en las barandillas del gimnasio escolar. Nadie imaginó que aquel tosco montaje improvisado acabaría convirtiéndose en un deporte legendario con cientos de millones de seguidores."}]}, {"meanings_summary": {"en": "railing; balustrade; banister; barrier", "es": "barandilla; pasamanos; baranda; valla"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Wooden boundary fences (栏) supported by upright posts (杆) create a protective railing (栏杆).", "composite_memory_hook_es": "Tablas protectoras de madera (栏) sostenidas por postes verticales (杆) componen una barandilla (栏杆).", "cultural_and_cognitive_roots": "Focal motif in Chinese classical poetry (辛弃疾 '把吴钩看了，栏杆拍遍') expressing patriotic yearning when leaning over grand vistas.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by level high tone: 'lán gān' (35-55). Ascend smoothly on 'lán', then keep a sustained high level pitch on 'gān'."}, "semantic_boundary_contrasts": {"core_nuance": "栏杆 refers strictly to a slotted waist-high safety barrier along balconies, bridges, or stairs.", "contrasts": [{"id": "1", "compared_word": "栏杆 vs. 扶手", "pinyin": "fúshǒu", "analysis": "扶手 is specifically the top grip rail grasped by hands for balance, while 栏杆 includes the whole assembly of vertical balusters and uprights."}, {"id": "2", "compared_word": "栏杆 vs. 栅栏", "pinyin": "zhàlan", "analysis": "栅栏 denotes ground-level outdoor fencing around gardens or pastures, whereas 栏杆 is mounted on elevated balconies, staircases, and bridges."}, {"id": "3", "compared_word": "栏杆 vs. 围墙", "pinyin": "wéiqiáng", "analysis": "围墙 is a solid brick or stone masonry enclosure blocking vision and passage, whereas 栏杆 is a see-through safety rail."}]}, "traps_and_cognates": {"look_alikes": [{"character": "栏", "pinyin": "lán", "meaning_en": "railing; pen", "distinction_note": "Tree radical 木 with 兰 on right"}, {"character": "拦", "pinyin": "lán", "meaning_en": "block; stop; intercept", "distinction_note": "Hand radical 扌 on left instead of 木"}, {"character": "杆", "pinyin": "gān", "meaning_en": "pole; shaft", "distinction_note": "Tree radical 木 with 干 on right"}, {"character": "竿", "pinyin": "gān", "meaning_en": "bamboo rod/pole", "distinction_note": "Bamboo radical 竹 on top"}], "etymological_cognates": [{"character": "栅", "pinyin": "zhà", "gloss_en": "palisade; railings"}, {"character": "篱", "pinyin": "lí", "gloss_en": "bamboo fence; hedge"}, {"character": "柱", "pinyin": "zhù", "gloss_en": "pillar; column"}, {"character": "墙", "pinyin": "qiáng", "gloss_en": "wall; barrier"}]}, "id": "10", "hanzi": "栏杆", "pinyin": "lán gān", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a barrier made of horizontal rails and vertical posts preventing falls along stairs, balconies, or bridges", "definition_es": "armazón compuesto de barras o balaustres que sirve de protección en balcones, escaleras o puentes", "example_phrase": "倚在阳台栏杆上看日落 (lean against the balcony railing watching the sunset)"}], "example_sentences": [{"id": "#1", "hanzi": "景区在临崖栈道的陡峭外侧安装了坚固的不锈钢防护栏杆，以确保游客观景时的绝对安全。", "pinyin": "Jǐngqū zài lín yá zhàndào de dǒuqiào wàicè ānzhuāng le jiāngù de búxiùgāng fánghù lángān, yǐ quèbǎo yóukè guānjǐng shí de juéduì ānquán.", "en": "The scenic park installed sturdy stainless steel guard railings along the steep cliffside walkways to guarantee the safety of sightseeing visitors.", "es": "El parque natural colocó firmes barandillas de acero inoxidable al borde del precipicio para salvaguardar a los turistas mientras contemplan las vistas."}, {"id": "#2", "hanzi": "小男孩调皮地想翻越马路中央的隔离栏杆，被路口执勤的交通警察及时吹哨制止了。", "pinyin": "Xiǎo nánhái tiáopí de xiǎng fānyuè mǎlù zhōngyāng de gélí lángān, bèi lùkǒu zhíqín de jiāotōng jǐngchá jíshí chuīshào zhìzhǐ le.", "en": "The mischievous little boy tried to climb over the median barrier railing, but the traffic officer on duty whistled to stop him immediately.", "es": "El travieso chiquillo intentó saltar la valla que divide la calzada, pero el agente de tráfico le pitó al instante frenando su imprudencia."}], "collocations": [{"hanzi": "扶着栏杆", "en": "hold onto the railing"}, {"hanzi": "防护栏杆", "en": "protective barrier / guardrail"}, {"hanzi": "阳台栏杆", "en": "balcony balustrade"}, {"hanzi": "楼梯栏杆", "en": "staircase banister"}, {"hanzi": "跨过栏杆", "en": "step over the railing"}, {"hanzi": "雕花栏杆", "en": "carved marble/wood balustrade"}], "idioms": [{"hanzi": "栏杆拍遍", "pinyin": "lán gān pāi biàn", "meaning_en": "strike railings repeatedly in patriotic grief or surging emotion"}, {"hanzi": "雕栏玉砌", "pinyin": "diāo lán yù qì", "meaning_en": "carved balustrades and jade steps; opulent imperial palaces"}, {"hanzi": "闭门造车", "pinyin": "bì mén zào chē", "meaning_en": "build cart behind closed doors; divorce theory from reality"}, {"hanzi": "倚窗远眺", "pinyin": "yǐ chuāng yuǎn tiào", "meaning_en": "lean on windowsill gazing into distant horizon"}], "character_decomposition": [{"character": "栏", "pinyin": "lán", "meaning_en": "railing; pen; column in newspaper", "meaning_es": "baranda; corral; columna", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (wooden post)", "sound_component": "兰 (lán / orchid; phonetic)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Tree radical 木 with phonetic 兰; a wooden pen or protective fence to keep livestock safe and delineate boundaries.", "visual_mnemonic_story_en": "Wooden posts (木) arranged gracefully like fragrant orchids (兰) to form a barrier fence (栏).", "visual_mnemonic_story_es": "Maderos alineados (木) con la pulcritud de orquídeas (兰) formando una cerca protectora (栏).", "tone_mnemonic_anchor": "35", "cangjie": "DAMM", "traditional": "欄"}, {"character": "杆", "pinyin": "gān", "meaning_en": "pole; rod; shaft", "meaning_es": "poste; pértiga; vara", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (wooden timber)", "sound_component": "干 (gān / shield; trunk; phonetic)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Tree radical 木 beside 干; a tall straight wooden pole used as an upright post or flag staff.", "visual_mnemonic_story_en": "A straight wooden tree trunk (木) standing upright like a sturdy shield post (干) to make a pole (杆).", "visual_mnemonic_story_es": "El tronco recto de un árbol (木) erigido como un poste defensivo (干) formando una pértiga (杆).", "tone_mnemonic_anchor": "55", "cangjie": "DMJ", "traditional": "桿"}], "extended_reading_passages": [{"id": "#1", "hanzi": "暮色苍茫时分，诗人独自倚靠在江南古桥那饱经风霜的汉白玉栏杆旁。水面上微波荡漾，渔火点点，微凉的晚风吹拂着青衫，那一排雕琢精美的石桥栏杆，默默见证着岁月的流逝与人世间的聚散悲欢。", "pinyin": "Mùsè cāngmáng shífēn, shīrén dúzì yǐkào zài Jiāngnán gǔqiáo nà bǎojīng-fēngshuāng de hànbáiyù lángān páng. Shuǐmiàn shang wēibō dàngyàng, yúhuǒ diǎndiǎn, wēiliáng de wǎnfēng chuīfú zhe qīngshān, nà yì pái diāozhuó jīngměi de shíqiáo lángān, mòmò jiànzhèng zhe suìyuè de liúshì yǔ rénshìjiān de jùsàn bēihuān.", "en": "At twilight, the poet leaned alone against weathered white marble railings on an ancient Jiangnan bridge. Ripples shimmered with fishing fires as evening breezes ruffled his robes; the carved railings stood silent witness to passing eras and earthly sorrow.", "es": "Al caer el crepúsculo, el poeta se apoyaba en la barandilla de mármol del viejo puente fluvial. Ondulaban las aguas con destellos de barcas mientras la brisa acariciaba su túnica; los balaustres esculpidos contemplaban en silencio el paso inexorable del tiempo."}, {"id": "#2", "hanzi": "体育馆二楼环形看台下方的木质栏杆，原本只是为了防止观众失足跌落的防护设施。而奈史密斯别出心裁地将两只桃筐固定在距离地面三米多高的栏杆边沿，无意间确立了百年来篮球运动篮筐的标准垂直高度。", "pinyin": "Tǐyùguǎn èrlóu huánxíng kàntái xiàfāng de mùzhì lángān, yuánběn zhǐshì wèile fángzhǐ guānzhòng shīzú diēluò de fánghù shèshī. Ér Nàishǐmīsī biéchūxīncái de jiāng liǎng zhī táokuāng gùdìng zài jùlí dìmbiàn sān mǐ duō gāo de lángān biānyán, wúyì jiān quèlì le bǎinián lái lánqiú yùndòng lánkuāng de biāozhǔn chuízhí gāodù.", "en": "The wooden railings beneath the second-floor gymnasium balcony were originally mere safety barriers against falls. Yet Naismith ingeniously nailed two peach baskets onto those railings ten feet up, inadvertently establishing the universal rim height for basketball.", "es": "La barandilla del graderío en el gimnasio sólo buscaba evitar caídas. Sin embargo, Naismith fijó allí dos cestas a más de tres metros de altura, fijando sin proponérselo la cota reglamentaria del aro que perdura hasta nuestros días."}]}, {"meanings_summary": {"en": "first (in series); shell; armor; Party A", "es": "primero; caparazón; armadura; parte A"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A hard protective shield or turtle shell plate (甲) always ranks first in rank and resilience.", "composite_memory_hook_es": "Una coraza de escudo o caparazón de tortuga (甲) encabeza siempre la jerarquía como primera en rango.", "cultural_and_cognitive_roots": "First of the Ten Heavenly Stems (天干) used for ancient astronomical reckoning, calendars, and formal contract drafting.", "tone_sandhi_and_pitch_modulation": "Dipping third tone: 'jiǎ' (214). Drop into the lower register and rebound with clarity."}, "semantic_boundary_contrasts": {"core_nuance": "甲 designates the foremost serial marker in lists, contracts, and paired competition.", "contrasts": [{"id": "1", "compared_word": "甲 vs. 乙", "pinyin": "yǐ", "analysis": "甲 is the first item or party in a legal contract, whereas 乙 represents the second counterpart."}, {"id": "2", "compared_word": "甲 vs. 第一", "pinyin": "dì-yī", "analysis": "第一 is a general numerical cardinal/ordinal ranking, while 甲 is formal bureaucratic/categorical labeling."}, {"id": "3", "compared_word": "甲 vs. 首", "pinyin": "shǒu", "analysis": "首 denotes headship or initial beginning in time, while 甲 designates a formal tabular class."}]}, "traps_and_cognates": {"look_alikes": [{"character": "甲", "pinyin": "jiǎ", "meaning_en": "first; shell", "distinction_note": "Vertical stroke extends downward from bottom"}, {"character": "由", "pinyin": "yóu", "meaning_en": "from; cause", "distinction_note": "Vertical stroke extends upward through the top"}, {"character": "申", "pinyin": "shēn", "meaning_en": "extend; ninth Earthly Branch", "distinction_note": "Vertical stroke extends both above and below"}, {"character": "田", "pinyin": "tián", "meaning_en": "field", "distinction_note": "Enclosed square without extending strokes"}], "etymological_cognates": [{"character": "乙", "pinyin": "yǐ", "gloss_en": "second Heavenly Stem"}, {"character": "丙", "pinyin": "bǐng", "gloss_en": "third Heavenly Stem"}, {"character": "丁", "pinyin": "dīng", "gloss_en": "fourth Heavenly Stem"}, {"character": "魁", "pinyin": "kuí", "gloss_en": "chief; first place"}]}, "id": "11", "hanzi": "甲", "pinyin": "jiǎ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the first of the ten Heavenly Stems, used to denote the first person, place, or grade in a sequence", "definition_es": "primero de los diez Troncos Celestiales, empleado para designar el primer elemento, grado o sujeto en una serie", "example_phrase": "甲乙两队 (Team A and Team B)"}], "example_sentences": [{"id": "#1", "hanzi": "在今天下午举行的年级篮球友谊赛中，甲队凭借默契的战术配合始终占据场上优势。", "pinyin": "Zài jīntiān xiàwǔ jǔxíng de niánjí lánqiú yǒuyìsài zhōng, jiǎ duì píngjiè mòqì de zhànshù pèihé shǐzhōng zhànjù chǎngshang yōushì.", "en": "In this afternoon's grade-level basketball friendly match, Team A consistently held the upper hand through seamless tactical chemistry.", "es": "En el amistoso de baloncesto escolar de esta tarde, el equipo A dominó el encuentro gracias a una impecable compenetración táctica."}, {"id": "#2", "hanzi": "商业合同的开头明确规定：甲方负责提供核心技术支持，乙方负责后续的市场开拓与运维服务。", "pinyin": "Shāngyè hétong de kāitóu míngquè guīdìng: jiǎfāng fùzé tígōng héxīn jìshù zhīchí, yǐfāng fùzé hòuxù de shìchǎng kāituò yǔ yùnwéi fúwù.", "en": "The preamble of the commercial contract clearly stipulates: Party A supplies core tech support, while Party B oversees market expansion and maintenance.", "es": "El contrato estipula claramente al inicio: la Parte A aportará el soporte técnico central, mientras que la Parte B asumirá la comercialización y el mantenimiento."}], "collocations": [{"hanzi": "甲方", "en": "Party A (contractor)"}, {"hanzi": "甲等", "en": "first grade / top class"}, {"hanzi": "指甲", "en": "fingernail"}, {"hanzi": "盔甲", "en": "armor and helmet"}, {"hanzi": "甲级联赛", "en": "first division league"}, {"hanzi": "甲天下", "en": "number one in the world"}], "idioms": [{"hanzi": "桂林山水甲天下", "pinyin": "Guì lín shān shuǐ jiǎ tiān xià", "meaning_en": "Guilin's scenery is supreme under heaven"}, {"hanzi": "披山带河", "pinyin": "pī shān dài hé", "meaning_en": "clad in mountains and girt by rivers; fortified land"}, {"hanzi": "富甲一方", "pinyin": "fù jiǎ yī fāng", "meaning_en": "wealthiest across an entire region"}, {"hanzi": "抛砖引玉", "pinyin": "pāo zhuān yǐn yù", "meaning_en": "toss brick to attract jade; offer modest starter"}], "character_decomposition": [{"character": "甲", "pinyin": "jiǎ", "meaning_en": "first; shell; armor", "meaning_es": "primero; caparazón; armadura", "radical": "田", "radical_meaning_en": "field", "meaning_component": "pictograph of turtle shell plate or warrior's protective cuirass", "sound_component": "甲 (jiǎ)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient oracle bone pictograph of a ribbed turtle shell or wooden shield plate; later first of the Heavenly Stems.", "visual_mnemonic_story_en": "A turtle's hard segmented back shell (田) extending down into a strong protective plate (甲).", "visual_mnemonic_story_es": "El duro caparazón segmentado de un galápago (田) prolongado en una coraza protectora (甲).", "tone_mnemonic_anchor": "214", "cangjie": "WL", "traditional": "甲"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代天干地支纪年法源远流长，以‘甲子’为六十循环之首。千百年来，‘甲’字不仅被广泛运用于历法纪年与科举功名排行，更深深烙印在契约文书与世俗日常中，成为首屈一指与无可替代的文化符号。", "pinyin": "Zhōngguó gǔdài tiāngān-dìzhī jìnián fǎ yuányuǎn-liúcháng, yǐ 'jiǎzǐ' wéi liùshí xúnhuán zhī shǒu. Qiānbǎinián lái, 'jiǎ' zì bùjǐn bèi guǎngfàn yùnyòng yú lìfǎ jìnián yǔ kējǔ gōngmíng páiháng, gèng shēnshēn làoyìn zài qìyuē wénshū yǔ shìsú rìcháng zhōng, chéngwéi shǒuqū-yìzhǐ yǔ wúkětìdài de wénhuà fúhào.", "en": "The ancient Chinese Sexagenary Cycle traces back millennia, with Jiazi heading the sixty-year rotation. The character 'Jia' not only marked imperial exams and calendars, but was imprinted on commercial deeds as the quintessential emblem of primacy.", "es": "El ciclo sexagesimal chino encabeza su rotación con 'Jiazi'. Durante siglos, 'Jia' no sólo fijó los anales y oposiciones imperiales, sino que se grabó en contratos y fueros como emblema de máxima jerarquía."}, {"id": "#2", "hanzi": "在一场别开生面的室内篮球模拟测试中，教练员将学员划分为甲队和乙队展开全场对抗。由于场地两头安装的桃筐缺乏漏底结构，甲队每当投篮得分后，乙队队员都必须暂停防守等待裁判取球，这让比赛气氛大打折扣。", "pinyin": "Zài yì chǎng biékāi-shēngmiàn de shìnèi lánqiú mónǐ cèshì zhōng, jiàoliànyuán jiāng xuéyuán huàfēn wéi jiǎ duì hé yǐ duì zhǎnkāi quánchǎng duìkàng. Yóuyú chǎngdì liǎngtóu ānzhuāng de táokuāng quēfá lòudǐ jiégòu, jiǎ duì měidāng tóulán défēn hòu, yǐ duì duìyuán dōu bìxū zàntíng fángshǒu děngdài cáipàn qǔ qiú, zhè ràng bǐsài qìfēn dàdǎ-zhékòu.", "en": "In an experimental indoor basketball test, the coach split trainees into Team A and Team B for a full-court scrimmage. Because peach baskets lacked open bottoms, whenever Team A scored, Team B had to halt defenses waiting for referees to extract the ball, dampening the atmosphere.", "es": "En un ensayo de baloncesto, el preparador dividió a los alumnos en equipos A y B. Como las canastas no tenían fondo abierto, cada tanto del equipo A obligaba al B a esperar que el árbitro sacara el balón, lastrando el ritmo."}]}, {"meanings_summary": {"en": "second (in series); Party B; second Heavenly Stem", "es": "segundo; parte B; segundo Tronco Celestial"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A single curved stroke like a winding sprout (乙) marks the second tier in traditional ranking.", "composite_memory_hook_es": "Un único trazo curvado semejante a un brote (乙) designa la segunda posición en el orden tradicional.", "cultural_and_cognitive_roots": "Second of the Heavenly Stems, symbolizing the budding flexibility of springtime vegetation breaking soil.", "tone_sandhi_and_pitch_modulation": "Dipping third tone: 'yǐ' (214). Drop cleanly and lift slightly at the finish."}, "semantic_boundary_contrasts": {"core_nuance": "乙 denotes the immediate sequel or counterpart paired with 甲 in formal categorizations.", "contrasts": [{"id": "1", "compared_word": "乙 vs. 甲", "pinyin": "jiǎ", "analysis": "甲 precedes as the initiating partner or primary category, while 乙 follows as the responsive counterpart."}, {"id": "2", "compared_word": "乙 vs. 第二", "pinyin": "dì-èr", "analysis": "第二 is plain ordinal ranking, while 乙 serves in bilateral agreements and codified schemas."}, {"id": "3", "compared_word": "乙 vs. 亚军", "pinyin": "yàjūn", "analysis": "亚军 refers strictly to the silver medalist in sporting contests, not a logical category marker."}]}, "traps_and_cognates": {"look_alikes": [{"character": "乙", "pinyin": "yǐ", "meaning_en": "second; stem", "distinction_note": "A single continuous stroke with horizontal, turn, and curved hook"}, {"character": "一", "pinyin": "yī", "meaning_en": "one", "distinction_note": "Straight horizontal bar"}, {"character": "已", "pinyin": "yǐ", "meaning_en": "already; stop", "distinction_note": "Half-open box with 3 strokes"}, {"character": "己", "pinyin": "jǐ", "meaning_en": "self", "distinction_note": "Fully open upper box with 3 strokes"}], "etymological_cognates": [{"character": "甲", "pinyin": "jiǎ", "gloss_en": "first Heavenly Stem"}, {"character": "次", "pinyin": "cì", "gloss_en": "second; secondary"}, {"character": "亚", "pinyin": "yà", "gloss_en": "inferior; runner-up"}, {"character": "副", "pinyin": "fù", "gloss_en": "deputy; vice-"}]}, "id": "12", "hanzi": "乙", "pinyin": "yǐ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the second of the ten Heavenly Stems, used to denote the second person, grade, or party in a series", "definition_es": "segundo de los diez Troncos Celestiales, empleado para designar el segundo elemento, grado o contraparte en una serie", "example_phrase": "甲乙双方签署协议 (Parties A and B sign the agreement)"}], "example_sentences": [{"id": "#1", "hanzi": "在学术研讨会上，甲组主张激进创新，而乙组则偏向稳健审慎，双方辩论非常热烈。", "pinyin": "Zài xuéshù yántǎohuì shang, jiǎ zǔ zhǔzhāng jījìn chuàngxīn, ér yǐ zǔ zé piānxiàng wěnjiàn shěnshèn, shuāngfāng biànlùn fēicháng rèliè.", "en": "At the academic symposium, Group A advocated radical innovation while Group B favored prudent stability, sparking a spirited debate.", "es": "En el simposio académico, el grupo A defendió una innovación audaz mientras que el B apostó por la prudencia, entablándose un vivo debate."}, {"id": "#2", "hanzi": "根据保密协议条款，未经甲方书面许可，乙方不得将相关技术文档透露给第三方机构。", "pinyin": "Gēnjù bǎomì xiéyì tiáokuǎn, wèijīng jiǎfāng shūmiàn xǔkě, yǐfāng bùdé jiāng xiāngguān jìshù wéndàng tòulù gěi dì-sān fāng jīgòu.", "en": "According to the non-disclosure agreement, without Party A's prior written consent, Party B shall not disclose relevant technical documents to any third party.", "es": "Conforme al acuerdo de confidencialidad, la Parte B no divulgará documentos técnicos a terceros sin el consentimiento expreso y por escrito de la Parte A."}], "collocations": [{"hanzi": "乙方", "en": "Party B (contractee)"}, {"hanzi": "乙等", "en": "second grade / class B"}, {"hanzi": "乙级联赛", "en": "second division league"}, {"hanzi": "乙醇", "en": "ethanol; alcohol"}, {"hanzi": "甲乙", "en": "Party A and Party B; serial sequence"}, {"hanzi": "乙烯", "en": "ethylene"}], "idioms": [{"hanzi": "各执一词", "pinyin": "gè zhí yī cí", "meaning_en": "each sticks to his own version; mutually conflicting stances"}, {"hanzi": "伯仲之间", "pinyin": "bó zhòng zhī jiān", "meaning_en": "hard to choose between older and younger brother; closely matched"}, {"hanzi": "相得益彰", "pinyin": "xiāng dé yì zhāng", "meaning_en": "bring out the best in each other; mutual complement"}, {"hanzi": "不相上下", "pinyin": "bù xiāng shàng xià", "meaning_en": "equally matched; on par with each other"}], "character_decomposition": [{"character": "乙", "pinyin": "yǐ", "meaning_en": "second; bent; Heavenly Stem", "meaning_es": "segundo; curvo; Tronco Celestial", "radical": "乙", "radical_meaning_en": "second / bent", "meaning_component": "pictograph of a sprouting seedling pushing its curved shoot up through soil", "sound_component": "乙 (yǐ)", "stroke_count": "1", "composition_type": "单一结构", "etymology_and_mnemonic": "Single graceful winding stroke representing a tender shoot curving upward as it breaks through hard ground in spring.", "visual_mnemonic_story_en": "A tender green sprout curving gently (乙) as it pushes through earth, following Jia as the second stem.", "visual_mnemonic_story_es": "Un tierno brote curvándose (乙) al despuntar de la tierra, siguiendo a Jia como segundo tronco.", "tone_mnemonic_anchor": "214", "cangjie": "N", "traditional": "乙"}], "extended_reading_passages": [{"id": "#1", "hanzi": "古人在订立买卖田契与借贷字据时，通篇皆以甲乙二人代称交易双方。这种简明规范的表述不仅清晰界定了彼此的权利与义务，更深刻影响了后世合同法律文书的行文体例，成为契约文明延续千年的重要载体。", "pinyin": "Gǔrén zài dìnglì mǎimài tiánqì yǔ jièdài zìjù shí, tōngpiān jiē yǐ jiǎ-yǐ èr rén dàichēng jiāoyì shuāngfāng. Zhè zhǒng jiǎnmíng guīfàn de biǎoshù bùjǐn qīngxī jièdìng le bǐcǐ de quánlì yǔ yìwù, gèng shēnkè yǐngxiǎng le hòushì hétong fǎlǜ wénshū de xíngwén tǐlì, chéngwéi qìyuē wénmíng yánxù qiānnián de zhòngyào zàitǐ.", "en": "In ancient deeds of sale and loans, the two trading sides were universally styled Party A and Party B. This standardized phrasing defined mutual rights and duties with precision, laying enduring stylistic foundations for modern contract jurisprudence.", "es": "Antiguamente, en escrituras de compraventa y préstamos, las partes se designaban como A y B. Esa fórmula concisa deslindaba con precisión derechos y deberes, influyendo decisivamente en la redacción de contratos hasta nuestros días."}, {"id": "#2", "hanzi": "在春田学院最初的十八人对抗赛中，詹姆士·奈史密斯将学员随机平分为甲乙两组。由于早期的投篮规则极为严密，乙队即便凭借精湛球技屡屡突破得分，也常常被频繁中断比赛搬梯子取球的环节打乱节奏，球员们迫切盼望能有更为高效顺畅的比赛规则。", "pinyin": "Zài Chūntián xuéyuàn zuìchū de shíbā rén duìkàngsài zhōng, Zhānmǔshì Nàishǐmīsī jiāng xuéyuán suíjī píngfēn wéi jiǎ-yǐ liǎng zǔ. Yóuyú zǎoqī de tóulán guīzé jíwéi yánmì, yǐ duì jíbiàn píngjiè jīngzhàn qiújì lǚlǚ tūpò défēn, yě chángcháng bèi pínfán zhòngduàn bǐsài bān tīzi qǔ qiú de huánjié dǎluàn jiézòu, qiúyuánmen pòqiè pànwàng néng yǒu gèng wéi gāoxiào shùnchàng de bǐsài guīzé.", "en": "In the inaugural 18-player contest at Springfield College, James Naismith divided students equally into Teams A and B. Although Team B frequently scored with fine skill, their momentum was broken by paused matches to fetch ladders, fueling desires for smoother rules.", "es": "En el partido inaugural de 18 jugadores en Springfield, Naismith dividió a los alumnos en grupos A y B. Aunque el equipo B encestaba con pericia, las pausas para subir a la escalera quebraban su ritmo, ansiando un reglamento más ágil."}]}, {"meanings_summary": {"en": "tool; instrument; implement; means", "es": "herramienta; instrumento; útil; medio"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The carpenter's framing square (工) paired with handy workshop equipment (具) constitutes a trusty tool (工具).", "composite_memory_hook_es": "La escuadra del artesano (工) unida al equipo de taller listo para su uso (具) compone una herramienta útil (工具).", "cultural_and_cognitive_roots": "Tool making is recognized in Chinese philosophy (荀子 '善假于物也') as the hallmark distinguishing human wisdom from wild beasts.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling fourth tone: 'gōng jù' (55-51). Hold 'gōng' steady on a high pitch, then drop sharply on 'jù'."}, "semantic_boundary_contrasts": {"core_nuance": "工具 primarily refers to physical implements held in the hand or instruments used for specific tasks.", "contrasts": [{"id": "1", "compared_word": "工具 vs. 仪器", "pinyin": "yíqì", "analysis": "仪器 denotes precision laboratory apparatus with calibrated measuring scales, unlike ordinary rugged manual 工具."}, {"id": "2", "compared_word": "工具 vs. 机械", "pinyin": "jīxiè", "analysis": "机械 refers to motorized, heavy automated industrial machinery, whereas 工具 are typically hand-held implements."}, {"id": "3", "compared_word": "工具 vs. 武器", "pinyin": "wǔqì", "analysis": "武器 designates offensive or defensive combat arms meant for warfare, not constructive craft tasks."}]}, "traps_and_cognates": {"look_alikes": [{"character": "工", "pinyin": "gōng", "meaning_en": "work; craft", "distinction_note": "3 strokes with top/bottom horizontal bars"}, {"character": "土", "pinyin": "tǔ", "meaning_en": "earth; soil", "distinction_note": "Upper horizontal stroke is shorter"}, {"character": "具", "pinyin": "jù", "meaning_en": "tool; utensil", "distinction_note": "Has 3 horizontal bars inside the 目 framework"}, {"character": "真", "pinyin": "zhēn", "meaning_en": "true; real", "distinction_note": "Has a top horizontal line with vertical stroke over 目"}], "etymological_cognates": [{"character": "器", "pinyin": "qì", "gloss_en": "utensil; implement; vessel"}, {"character": "械", "pinyin": "xiè", "gloss_en": "machinery; device"}, {"character": "用", "pinyin": "yòng", "gloss_en": "use; employ"}, {"character": "件", "pinyin": "jiàn", "gloss_en": "item; component"}]}, "id": "13", "hanzi": "工具", "pinyin": "gōng jù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an implement or machine used to carry out a particular physical or technical function", "definition_es": "objeto o utensilio manual o mecánico destinado a realizar un trabajo determinado", "example_phrase": "一套修理汽车的专用工具 (a set of specialized car repair tools)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a means or instrument employed to achieve an objective", "definition_es": "recurso o medio instrumental para alcanzar un propósito", "example_phrase": "语言是人类沟通的重要工具 (language is an essential tool for communication)"}], "example_sentences": [{"id": "#1", "hanzi": "老电工随身携带的皮质工具箱里，整齐排列着螺丝刀、万用表和绝缘钳等常用工具。", "pinyin": "Lǎo diàngōng suíshēn xiédài de pízì gōngjùxiāng lǐ, zhěngqí páiliè zhe luósīdāo, wànyòngbiǎo hé juéyuánqián děng chángyòng gōngjù.", "en": "Inside the leather toolbox carried by the senior electrician, common tools like screwdrivers, multimeters, and insulated pliers were neatly arrayed.", "es": "En la caja de herramientas de cuero del veterano electricista se alineaban destornilladores, polímetros y alicates aislados."}, {"id": "#2", "hanzi": "现代互联网和人工智能已经从前沿探索全面融入日常生产，成为人类认知世界与提升效率的得力工具。", "pinyin": "Xiàndài hùliánwǎng hé réngōng zhìnéng yǐjīng cóng qiányán tànsuǒ quánmiàn róngrù rìcháng shēngchǎn, chéngwéi rénlèi rènzhī shìjiè yǔ tíshēng xiàolǜ de délì gōngjù.", "en": "The modern internet and artificial intelligence have integrated into daily production, serving as powerful tools for humanity to comprehend the world and boost efficiency.", "es": "Internet y la inteligencia artificial se han integrado de lleno en el trabajo diario, alzándose como herramientas clave para potenciar la productividad humana."}], "collocations": [{"hanzi": "交通工具", "en": "means of transportation"}, {"hanzi": "工具箱", "en": "toolbox / tool kit"}, {"hanzi": "辅助工具", "en": "auxiliary tool / aid"}, {"hanzi": "专用工具", "en": "specialized tool"}, {"hanzi": "通讯工具", "en": "communication tool"}, {"hanzi": "工具书", "en": "reference book / dictionary"}], "idioms": [{"hanzi": "工欲善其事", "pinyin": "gōng yù shàn qí shì", "meaning_en": "a workman must sharpen his tools if he is to do his work well"}, {"hanzi": "巧夺天工", "pinyin": "qiǎo duó tiān gōng", "meaning_en": "superb craftsmanship outdoing nature"}, {"hanzi": "莫衷一是", "pinyin": "mò zhōng yī shì", "meaning_en": "unable to agree on which is right; lack consensus"}, {"hanzi": "游刃有余", "pinyin": "yóu rèn yǒu yú", "meaning_en": "handling a butcher's blade with ample leeway; doing with ease"}], "character_decomposition": [{"character": "工", "pinyin": "gōng", "meaning_en": "work; craft; carpenter's square", "meaning_es": "trabajo; oficio; escuadra de carpintero", "radical": "工", "radical_meaning_en": "work / craft", "meaning_component": "pictograph of an ancient carpenter's plumb square", "sound_component": "工 (gōng)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph of a carpenter's framing square tool; symbolizes skilled manual fabrication and labor.", "visual_mnemonic_story_en": "A carpenter's sturdy level square (工) used by craftsmen to measure perfect right angles.", "visual_mnemonic_story_es": "La escuadra de madera (工) usada por el carpintero para medir ángulos rectos en su oficio.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": "工"}, {"character": "具", "pinyin": "jù", "meaning_en": "tool; possess; prepare; utensils", "meaning_es": "útil; poseer; disponer; vajilla", "radical": "八", "radical_meaning_en": "eight", "meaning_component": "鼎 (cauldron) held by two hands 廾 (represented by 八)", "sound_component": "具 (jù)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Two hands holding up a sacrificial bronze vessel full of food; extended to all equipment, utensils, and gear ready for use.", "visual_mnemonic_story_en": "Two hands (八) lifting a laden food vessel with multiple compartments, preparing table gear (具).", "visual_mnemonic_story_es": "Dos manos (八) elevando una vasija bien abastecida, preparando utensilios necesarios (具).", "tone_mnemonic_anchor": "51", "cangjie": "BAMC", "traditional": "具"}], "extended_reading_passages": [{"id": "#1", "hanzi": "人类之所以能够脱离茹毛饮血的原始蛮荒，关键就在于发明并使用劳动工具。从打制粗糙石斧到冶炼锋利青铜，工具的每一次重大技术迭代，都如同杠杆般撬动着生产力飞跃，深刻重塑着人类社会文明的发展轨迹。", "pinyin": "Rénlèi zhī suǒyǐ nénggòu tuōlí rúmáo-yǐnxuè de yuánshǐ mánhuāng, guānjiàn jiù zàiyú fāmíng bìng shǐyòng láodòng gōngjù. Cóng dǎzhì cūcāo shí fǔ dào yěliàn fēnglì qīngtóng, gōngjù de měi yí cì zhòngdà jìshù jiédài, dōu rútóng gànggǎn bān qiàodòng zhe shēngchǎnlì fēiyuè, shēnkè chóngsù zhe rénlèi shèhuì wénmíng de fāzhǎn guǐjì.", "en": "Humanity emerged from savage antiquity largely by inventing and mastering tools. From crude stone axes to cast bronze, each major technological leap in tools acted like a lever hoisting productivity and reshaping human civilization.", "es": "La humanidad abandonó el salvajismo primordial gracias a la creación de herramientas de trabajo. Del tosco hacha lítica al bronce afilado, cada salto instrumental multiplicó la fuerza productiva, transformando el curso de la civilización."}, {"id": "#2", "hanzi": "当年奈史密斯发明篮球时，学校体育馆里既缺乏专门护具，也没有合手的投篮工具。面对反复踩梯子取球的笨拙局面，工匠找来最为寻常的锯子这一简单手工工具锯掉了竹筐底部，以极低的成本攻克了比赛流程中的巨大阻碍。", "pinyin": "Dāngnián Nàishǐmīsī fāmíng lánqiú shí, xuéxiào tǐyùguǎn lǐ jì quēfá zhuānmén hùjù, yě méiyǒu héshǒu de tóulán gōngjù. Miànduì fǎnfù cǎi tīzi qǔ qiú de bènzhuō júmiàn, gōngjiàng zhǎolái zuìwéi xúncháng de jùzi zhè yí jiǎndān shǒugōng gōngjù jù diào le zhúkuāng dǐbù, yǐ jí dī de chéngběn gōngkè le bǐsài liúchéng zhōng de jùdà zǔ'ài.", "en": "When Naismith created basketball, the gym lacked specialized gear and convenient scoring equipment. Faced with awkward ladder-climbing to retrieve balls, a craftsman grabbed an ordinary saw—a simple tool—to cut off the bottoms, solving the bottleneck at minimal cost.", "es": "Al nacer el baloncesto, el gimnasio carecía de protecciones e implementos adecuados. Ante el engorro de subir a escaleras para recuperar el balón, un conserje usó una modesta sierra para abrir el fondo, solventando el escollo con suma sencillez."}]}, {"meanings_summary": {"en": "to shoot (basketball); to shoot a hoop", "es": "tirar a canasta; encestar; lanzar a la cesta"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Flinging with your hand (投) toward the elevated bamboo hoop (篮) is shooting a basket (投篮).", "composite_memory_hook_es": "Lanzar el balón con la mano (投) hacia la canasta suspendida de bambú (篮) es tirar a canasta (投篮).", "cultural_and_cognitive_roots": "Direct translation of basketball 'shooting', combining ancient hurling archery terms with modern team sports.", "tone_sandhi_and_pitch_modulation": "Two rising second tones: 'tóu lán' (35-35). Rise cleanly across both syllables with crisp, ascending inflection."}, "semantic_boundary_contrasts": {"core_nuance": "投篮 specifically denotes shooting the ball at the basket hoop in basketball.", "contrasts": [{"id": "1", "compared_word": "投篮 vs. 传球", "pinyin": "chuánqiú", "analysis": "传球 means passing the ball to a teammate to advance play, whereas 投篮 aims directly at scoring points."}, {"id": "2", "compared_word": "投篮 vs. 射门", "pinyin": "shèmén", "analysis": "射门 denotes kicking or striking the ball into a soccer/hockey goal net, not shooting into an elevated hoop."}, {"id": "3", "compared_word": "投篮 vs. 扣篮", "pinyin": "kòulán", "analysis": "扣篮 (dunk) involves leaping and forcefully slamming the ball downward through the rim, a subset of scoring attempts."}]}, "traps_and_cognates": {"look_alikes": [{"character": "投", "pinyin": "tóu", "meaning_en": "throw; cast", "distinction_note": "Hand radical 扌 on left with 殳"}, {"character": "没", "pinyin": "méi", "meaning_en": "not have; sink", "distinction_note": "Water radical 氵 on left"}, {"character": "篮", "pinyin": "lán", "meaning_en": "basket", "distinction_note": "Bamboo radical 竹 on top over 监"}, {"character": "蓝", "pinyin": "lán", "meaning_en": "blue color", "distinction_note": "Grass radical 艹 on top over 监"}], "etymological_cognates": [{"character": "掷", "pinyin": "zhì", "gloss_en": "hurl; fling"}, {"character": "抛", "pinyin": "pāo", "gloss_en": "toss; cast aside"}, {"character": "扔", "pinyin": "rēng", "gloss_en": "throw; discard"}, {"character": "射", "pinyin": "shè", "gloss_en": "shoot; emit"}]}, "id": "14", "hanzi": "投篮", "pinyin": "tóu lán", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to throw or shoot the basketball toward the hoop to score points", "definition_es": "lanzar el balón hacia la canasta o aro para anotar puntos en baloncesto", "example_phrase": "三分线外果断投篮 (shoot decisively from outside the three-point line)"}], "example_sentences": [{"id": "#1", "hanzi": "在全场比赛只剩最后两秒的生死关头，主力后卫顶住防守压力后仰投篮，皮球压哨空心入网。", "pinyin": "Zài quánchǎng bǐsài zhǐ shèng zuìhòu liǎng miǎo de shēngsǐ guāntóu, zhǔlì hòuwèi dǐngzhù fángshǒu yālì hòuyǎng tóulán, píqiú yāshào kōngxīn rùwǎng.", "en": "With merely two seconds left on the clock, the lead guard braved tight defense and sank a buzzer-beating fadeaway jumper cleanly through the net.", "es": "Con dos segundos en el marcador, el base titular desafió el marcaje y encestó en suspensión un triple limpio sobre la bocina."}, {"id": "#2", "hanzi": "要想显著提高比赛中的投篮命中率，运动员必须经过日复一日成千上万次肌肉记忆的强化训练。", "pinyin": "Yào xiǎng xiǎnzhù tígāo bǐsài zhōng de tóulán mìngzhònglǜ, yùndòngyuán bìxū jīngguò rì-fù-yírì chéngqiān-shàngwàn cì jīròu jìyì de qiánghuà xùnliàn.", "en": "To substantially improve in-game shooting accuracy, players must undergo tens of thousands of repetitions to build muscle memory day after day.", "es": "Para mejorar la eficacia de tiro en competición, los jugadores deben acumular miles de lanzamientos diarios consolidando la memoria muscular."}], "collocations": [{"hanzi": "投篮命中率", "en": "field goal shooting percentage"}, {"hanzi": "后仰投篮", "en": "fadeaway jump shot"}, {"hanzi": "跳起投篮", "en": "jump shot"}, {"hanzi": "定点投篮", "en": "set shot / spot-up shooting"}, {"hanzi": "投篮得分", "en": "score by shooting a basket"}, {"hanzi": "三分投篮", "en": "three-point shot"}], "idioms": [{"hanzi": "百步穿杨", "pinyin": "bǎi bù chuān yáng", "meaning_en": "shoot willow leaf from hundred paces; pinpoint shooting accuracy"}, {"hanzi": "箭无虚发", "pinyin": "jiàn wú xū fā", "meaning_en": "no arrow shot in vain; every shot hits target"}, {"hanzi": "一发中的", "pinyin": "yī fā zhòng dì", "meaning_en": "hit the bullseye with a single shot; hit the nail on the head"}, {"hanzi": "百发百中", "pinyin": "bǎi fā bǎi zhòng", "meaning_en": "hit the target a hundred times out of a hundred"}], "character_decomposition": [{"character": "投", "pinyin": "tóu", "meaning_en": "cast; throw; fling; plunge", "meaning_es": "lanzar; arrojar; tirar", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hand hurling) + 殳 (lance / missile)", "sound_component": "殳 (shū / phonetic association)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Hand radical 扌 beside 殳 (hand holding a missile pole); the action of forcefully flinging or tossing a projectile toward a target.", "visual_mnemonic_story_en": "A muscular hand (扌) whipping forward to hurl a javelin missile (殳) toward the target ring (投).", "visual_mnemonic_story_es": "Una mano enérgica (扌) lanzando una jabalina (殳) con precisión hacia la meta (投).", "tone_mnemonic_anchor": "35", "cangjie": "QHE", "traditional": "投"}, {"character": "篮", "pinyin": "lán", "meaning_en": "basket; goal hoop", "meaning_es": "cesta; canasta; aro", "radical": "竹", "radical_meaning_en": "bamboo", "meaning_component": "竹 (bamboo weave) + 监 (reflecting supervisor basin)", "sound_component": "监 (jiān / phonetic)", "stroke_count": "16", "composition_type": "上下结构", "etymology_and_mnemonic": "Bamboo radical 竹 over 监; a deep woven basket with handles, extended to the basketball target basket.", "visual_mnemonic_story_en": "A round basket woven from bamboo (竹) hung overhead for supervision (监), catching every ball (篮).", "visual_mnemonic_story_es": "Una canasta tejida de bambú (竹) suspendida en alto (监), lista para recibir el balón (篮).", "tone_mnemonic_anchor": "35", "cangjie": "HWTIT", "traditional": "籃"}], "extended_reading_passages": [{"id": "#1", "hanzi": "黄昏的社区球场上，少年一遍又一遍地练习着中距离急停投篮。每一次高高跃起、手腕轻柔拨动皮球的瞬间，橙色的篮球便在空中划出一道优美圆润的弧线。汗水浸透了衣衫，但那声清脆的擦网声就是对坚持最好的奖赏。", "pinyin": "Huánghūn de shèqū qiúchǎng shang, shàonián yí biàn yòu yí biàn de liànxí zhe zhōng jùlí jítíng tóulán. Měi yí cì gāogāo yuèqǐ, shǒuwàn qīngróu bōdòng píqiú de shùnjiān, chéngsè de lánqiú biàn zài kōngzhōng huà chū yí dào yōuměi yuánrùn de húxiàn. Hànshuǐ jìntòu le yīshān, dàn nà shēng qīngcuì de cā wǎng shēng jiùshì duì jiānchí zuì hǎo de jiǎngshǎng.", "en": "On the community court at twilight, the boy practiced pull-up jump shots repeatedly. Every time he leaped and gently flicked his wrist, the orange ball traced a graceful arc through the air. Sweat drenched his jersey, but the crisp swish was the sweetest reward.", "es": "En la cancha del barrio al anochecer, el joven ensayaba tiros en suspensión una y otra vez. Cada salto y sutil giro de muñeca dibujaban en el aire una parábola perfecta. Empapado en sudor, el chasquido de la red premiaba su constancia."}, {"id": "#2", "hanzi": "在一百多年前篮球刚被发明时，运动员投篮命中后的取球过程极为繁琐。因为球筐底部是封闭的，每次投篮成功后比赛都必须被迫中断，工作人员必须搬来长梯把球掏出来。直到人们锯掉筐底，投篮才真正成为连续、激烈且扣人心弦的高速竞技过程。", "pinyin": "Zài yìbǎi duō nián qián lánqiú gāng bèi fāmíng shí, yùndòngyuán tóulán mìngzhòng hòu de qǔ qiú guòchéng jíwéi fánsuǒ. Yīnwèi qiúkuāng dǐbù shì fēngbì de, měicì tóulán chénggōng hòu bǐsài dōu bìxū bèipò zhòngduàn, gōngzuò rényuán bìxū bān lái chángtī bǎ qiú tāo chūlái. Zhídào rénmen jù diào kuāngdǐ, tóulán cái zhēnzhèng chéngwéi liánxù, jīliè qiě kòurénxīnxuán de gāosù jìngjì guòchéng.", "en": "Over a century ago when basketball was invented, retrieving balls after a made basket was tedious. Because basket bottoms were sealed, every score halted the game for staff to haul ladders and fish out the ball. Only when bottoms were sawed open did shooting become a thrilling, continuous thrill.", "es": "Hace más de un siglo, recuperar el balón tras encestar era engorroso. Con canastas de fondo cerrado, cada acierto obligaba a parar el partido para bajar la bola con escalera. Al abrir el fondo, el tiro se tornó en un espectáculo trepidante y fluido."}]}, {"meanings_summary": {"en": "to step on; tread; stamp on; depress (pedal)", "es": "pisar; pisotear; presionar (pedal)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Your active foot (足) stepping onto the ground while harvesting (采) means to step on (踩).", "composite_memory_hook_es": "Poner el pie (足) apoyándolo con firmeza mientras cosechas (采) equivale a pisar (踩).", "cultural_and_cognitive_roots": "Everyday physical verb expressing physical foot pressure, stepping on rungs, or driving pedals.", "tone_sandhi_and_pitch_modulation": "Dipping third tone: 'cǎi' (214). Drop into the lower vocal pit and curve gently up."}, "semantic_boundary_contrasts": {"core_nuance": "踩 focuses on placing weight downward with the foot onto a surface or pedal.", "contrasts": [{"id": "1", "compared_word": "踩 vs. 踏", "pinyin": "tà", "analysis": "踏 is more literary and formal (脚踏实地, 踏步), while 踩 is the predominant colloquial term in daily life (踩刹车, 踩脚)."}, {"id": "2", "compared_word": "踩 vs. 踢", "pinyin": "tī", "analysis": "踢 involves swinging the leg forward or sideways to strike a ball, whereas 踩 presses straight downward with body weight."}, {"id": "3", "compared_word": "踩 vs. 跺", "pinyin": "duò", "analysis": "跺 emphasizes violently stomping one's feet in anger or cold (跺脚), unlike ordinary stepping (踩)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "踩", "pinyin": "cǎi", "meaning_en": "step on; tread", "distinction_note": "Foot radical 足 on left"}, {"character": "采", "pinyin": "cǎi", "meaning_en": "pluck; gather; spirit", "distinction_note": "Base character without foot radical"}, {"character": "彩", "pinyin": "cǎi", "meaning_en": "colorful; prize", "distinction_note": "Has 彡 (hair/feather brush) on right"}, {"character": "睬", "pinyin": "cǎi", "meaning_en": "pay attention to; heed", "distinction_note": "Eye radical 目 on left"}], "etymological_cognates": [{"character": "踏", "pinyin": "tà", "gloss_en": "tread; step firmly"}, {"character": "蹬", "pinyin": "dēng", "gloss_en": "pedal; kick down"}, {"character": "跨", "pinyin": "kuà", "gloss_en": "step across; straddle"}, {"character": "踱", "pinyin": "duó", "gloss_en": "pace; stroll slowly"}]}, "id": "15", "hanzi": "踩", "pinyin": "cǎi", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to put one's foot down upon something; to tread or stamp", "definition_es": "poner el pie sobre algo presionándolo con el peso corporal", "example_phrase": "踩着梯子爬上去 (climb up stepping on a ladder)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to depress a vehicle pedal (accelerator, brake)", "definition_es": "accionar un pedal mecánico con el pie", "example_phrase": "紧急踩刹车 (slam on the emergency brakes)"}], "example_sentences": [{"id": "#1", "hanzi": "司机在雨天湿滑的路段行驶时突然发现前方有障碍物，连忙果断踩下了防抱死紧急刹车。", "pinyin": "Sījī zài yǔtiān shīhuá de lùduàn xíngshǐ shí tūrán fāxiàn qiánfāng yǒu zhàng'àiwù, liánmáng guǒduàn cǎi xià le fángbàosǐ jǐnjí shāchē.", "en": "Driving along the wet and slippery road, the driver suddenly spotted an obstacle ahead and promptly stepped hard on the anti-lock emergency brakes.", "es": "Conducía sobre el asfalto mojado cuando divisó un obstáculo adelante, pisando de inmediato y con firmeza el freno de emergencia con ABS."}, {"id": "#2", "hanzi": "为了在早春季节修剪屋檐下的枯树枝，园艺工小心翼翼地踩着折叠木梯一步步往上爬。", "pinyin": "Wèile zài zǎochūn jìjié xiūjiǎn wūyán xià de kū shùzhī, yuányìgōng xiǎoxīn-yìyì de cǎi zhe zhédié mùtī yíbùbù wǎng shàng pá.", "en": "To prune dead branches beneath the eaves in early spring, the gardener cautiously climbed up, stepping carefully on the folding wooden ladder.", "es": "Para podar ramas secas bajo el alero a principios de primavera, el jardinero subió paso a paso pisando con sumo tiento la escalera plegable."}], "collocations": [{"hanzi": "踩刹车", "en": "step on the brake pedal"}, {"hanzi": "踩油门", "en": "step on the gas accelerator"}, {"hanzi": "踩在脚下", "en": "trample under foot"}, {"hanzi": "踩着梯子", "en": "step on the rungs of a ladder"}, {"hanzi": "不小心踩到", "en": "accidentally step on"}, {"hanzi": "踩点", "en": "arrive right on the dot / stake out"}], "idioms": [{"hanzi": "脚踏实地", "pinyin": "jiǎo tà shí dì", "meaning_en": "have one's feet planted on solid ground; conscientious and practical"}, {"hanzi": "步步为营", "pinyin": "bù bù wéi yíng", "meaning_en": "build camp at every step; proceed cautiously and firmly"}, {"hanzi": "登高望远", "pinyin": "dēng gāo wàng yuǎn", "meaning_en": "scale heights to gaze into distance; broad perspective"}, {"hanzi": "践踏公义", "pinyin": "jiàn tà gōng yì", "meaning_en": "trample upon public justice and fair play"}], "character_decomposition": [{"character": "踩", "pinyin": "cǎi", "meaning_en": "step on; tread; trample", "meaning_es": "pisar; pisotear", "radical": "足", "radical_meaning_en": "foot", "meaning_component": "足 (foot / stepping leg)", "sound_component": "采 (cǎi / gather; phonetic)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Foot radical 足 beside 采 (hand plucking); placing one's foot firmly downward to step or tread upon something.", "visual_mnemonic_story_en": "A nimble foot (足) stepping down firmly while reaching hands gather (采) fruit from overhead.", "visual_mnemonic_story_es": "Un pie firme (足) que pisa con aplomo mientras las manos recolectan (采) fruta de lo alto.", "tone_mnemonic_anchor": "214", "cangjie": "RMBD", "traditional": "踩"}], "extended_reading_passages": [{"id": "#1", "hanzi": "深秋清晨的古朴庭院里落满了厚厚的金黄银杏叶，踩上去发出沙沙的轻响，宛如踏在一张柔软温暖的金色地毯上。晨练的老人放慢了脚步，生怕惊扰了这一片静谧祥和的秋意。", "pinyin": "Shēnqiū qīngchén de gǔpǔ tíngyuàn lǐ luòmǎn le hòuhòu de jīnhuáng yínxìng yè, cǎi shàngqu fāchū shāshā de qīngxiǎng, wǎnrú tà zài yì zhāng róuruǎn wēnnuǎn de jīnsè dìtǎn shang. Chénliàn de lǎorén fàngmàn le jiǎobù, shēngpà jīngrǎo le zhè yí piàn jìngmì xiánghé de qiūyì.", "en": "In the courtyard on a late autumn morning, thick golden ginkgo leaves blanketed the flagstones, rustling softly underfoot like a warm carpet. An elderly jogger slowed his pace, reluctant to disturb the serene autumn calm.", "es": "En el patio señorial de otoño yacían hojas de ginkgo doradas, que crujían con suavidad bajo las pisadas como una alfombra mullida. El anciano paseante aminoró el paso para no turbar la apacible quietud del alba."}, {"id": "#2", "hanzi": "在早期篮球比赛中，每当皮球落入竹筐，比赛就不得不被迫叫停。工作人员必须搬来折叠木梯，小心翼翼地踩着晃晃悠悠的梯恩子爬到三米多高处把球取出来。这种不断搬梯子、踩梯子的繁琐过程，极大消磨了现场观众和球员的激情。", "pinyin": "Zài zǎoqī lánqiú bǐsài zhōng, měidāng píqiú luòrù zhúkuāng, bǐsài jiù bùdébù bèipò jiàotíng. Gōngzuò rényuán bìxū bān lái zhédié mùtī, xiǎoxīn-yìyì de cǎi zhe huànghuang-yōuyōu de tīzi pá dào sān mǐ duō gāochù bǎ qiú qǔ chūlái. Zhè zhǒng búduàn bān tīzi, cǎi tīzi de fánsuǒ guòchéng, jídà xiāomó le xiànchǎng guānzhòng hé qiúyuán de jīqíng.", "en": "In early basketball games, whenever the ball lodged in the basket, play had to be paused. Custodians dragged over folding ladders, gingerly stepping up rickety rungs ten feet high to dislodge it. Continually hauling and stepping onto ladders severely drained players' passion.", "es": "Al comienzo del baloncesto, cada enceste paralizaba el juego. El personal arrastraba una escalera de madera y subía con cautela a más de tres metros para retirar la pelota. Aquel trajín de pisar peldaños enfriaba el fervor de jugadores y público."}]}, {"meanings_summary": {"en": "repeatedly; time and again; over and over", "es": "reiteradamente; una y otra vez; repetidamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Doing once (一) and then once again (再) means doing something repeatedly (一再).", "composite_memory_hook_es": "Hacerlo una vez (一) y de inmediato otra vez más (再) expresa actuar reiteradamente (一再).", "cultural_and_cognitive_roots": "Expresses strong intentional insistence or unavoidable recurrence in classical and contemporary rhetoric.", "tone_sandhi_and_pitch_modulation": "Tone sandhi: 'yī' changes to rising second tone before fourth tone 'zài': 'yí zài' (35-51). Rise on 'yí', then drop forcefully on 'zài'."}, "semantic_boundary_contrasts": {"core_nuance": "一再 indicates intentional human speech, insistence, or action recurring multiple times consecutively.", "contrasts": [{"id": "1", "compared_word": "一再 vs. 再次", "pinyin": "zàicì", "analysis": "再次 simply denotes doing something a second time or once more, while 一再 emphasizes persistent multiple repetitions (一再申明)."}, {"id": "2", "compared_word": "一再 vs. 常常", "pinyin": "chángcháng", "analysis": "常常 describes habitual customary actions over time, whereas 一再 emphasizes insistent recurrence in a specific context."}, {"id": "3", "compared_word": "一再 vs. 重新", "pinyin": "chóngxīn", "analysis": "重新 means starting over completely from the beginning, while 一再 signifies reiterating or repeating an existing act."}]}, "traps_and_cognates": {"look_alikes": [{"character": "再", "pinyin": "zài", "meaning_en": "again; once more", "distinction_note": "Has horizontal stroke through top of 冂 and base line"}, {"character": "在", "pinyin": "zài", "meaning_en": "at; in; exist", "distinction_note": "Starts with 𠂇 and has earth radical 土 at bottom"}, {"character": "冉", "pinyin": "rǎn", "meaning_en": "gradually; drooping", "distinction_note": "Middle vertical stroke extends downward"}, {"character": "甫", "pinyin": "fǔ", "meaning_en": "just; ancient honorific", "distinction_note": "Has a top dot and crossing vertical stroke"}], "etymological_cognates": [{"character": "屡", "pinyin": "lǚ", "gloss_en": "repeatedly; frequently"}, {"character": "频", "pinyin": "pín", "gloss_en": "frequency; repeatedly"}, {"character": "复", "pinyin": "fù", "gloss_en": "duplicate; repeat"}, {"character": "迭", "pinyin": "dié", "gloss_en": "alternate; repeatedly"}]}, "id": "16", "hanzi": "一再", "pinyin": "yí zài", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "doing something repeatedly, multiple times, often regarding reminders, warnings, or occurrences", "definition_es": "hacer algo reiteradas veces, especialmente en advertencias, solicitudes o retrasos", "example_phrase": "一再强调安全生产 (repeatedly emphasize workplace safety)"}], "example_sentences": [{"id": "#1", "hanzi": "班主任在出发前一再叮嘱同学们，在野外徒步考察时必须听从领队指挥，切勿私自脱离团队行动。", "pinyin": "Bānzhǔrèn zài chūfā qián yízài dīngzhǔ tóngxuémen, zài yěwài túbù kǎochá shí bìxū tīngcóng lǐngduì zhǐhuī, qièwù sīsì tuōlí tuánduì xíngdòng.", "en": "Before setting off, the teacher repeatedly urged students to heed the group leader's orders during field hikes and never wander off alone.", "es": "Antes de partir, el tutor insistió repetidamente a los alumnos en obedecer al guía durante la excursión y no alejarse jamás del grupo."}, {"id": "#2", "hanzi": "尽管项目组一再压缩开支并优化施工流程，但因国际原材料价格暴涨，整体预算依然超出了预期。", "pinyin": "Jǐnguǎn xiàngmùzǔ yízài yāsuō kāizhī bìng yōuhuà shīgōng liúchéng, dàn yīn guójì yuáncáiliào jiàgé bàozhǎng, zhěngtǐ yùsuàn yīrán chāochū le yùqī.", "en": "Although the project team repeatedly compressed expenses and streamlined operations, surging global raw material prices still drove budgets beyond expectations.", "es": "Aunque el equipo recortó gastos reiteradamente y optimizó los procesos, el alza internacional de materias primas disparó el presupuesto por encima de lo previsto."}], "collocations": [{"hanzi": "一再强调", "en": "repeatedly emphasize"}, {"hanzi": "一再推迟", "en": "repeatedly postpone / delay"}, {"hanzi": "一再重申", "en": "reiterate time and again"}, {"hanzi": "一再表示", "en": "express repeatedly"}, {"hanzi": "一再要求", "en": "request insistently"}, {"hanzi": "一再保证", "en": "guarantee repeatedly"}], "idioms": [{"hanzi": "三番五次", "pinyin": "sān fān wǔ cì", "meaning_en": "time and time again; over and over repeatedly"}, {"hanzi": "再三再四", "pinyin": "zài sān zài sì", "meaning_en": "again and again; repeated endlessly"}, {"hanzi": "苦口婆心", "pinyin": "kǔ kǒu pó xīn", "meaning_en": "admonish with earnest patient words"}, {"hanzi": "言犹在耳", "pinyin": "yán yóu zài ěr", "meaning_en": "words still ringing in one's ears"}], "character_decomposition": [{"character": "一", "pinyin": "yī", "meaning_en": "one; single; whole", "meaning_es": "uno; solo; entero", "radical": "一", "radical_meaning_en": "one", "meaning_component": "pictograph of single counting rod", "sound_component": "一 (yī)", "stroke_count": "1", "composition_type": "单一结构", "etymology_and_mnemonic": "Single horizontal line representing the primordial unity and initial starting point in counting.", "visual_mnemonic_story_en": "A single straight horizontal beam (一), marking the foundation of all counting.", "visual_mnemonic_story_es": "Una sola viga horizontal recta (一), base y principio de todo cálculo numérico.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": "一"}, {"character": "再", "pinyin": "zài", "meaning_en": "again; once more; second time", "meaning_es": "otra vez; de nuevo; reiterar", "radical": "冂", "radical_meaning_en": "down open box", "meaning_component": "two strokes stacked over a frame base", "sound_component": "再 (zài)", "stroke_count": "6", "composition_type": "单一结构", "etymology_and_mnemonic": "Originally a pair of horizontal counting sticks tied together, indicating two times, repetition, or renewal.", "visual_mnemonic_story_en": "Stacking another crossbar across the wooden frame, signifying repeating an action once more (再).", "visual_mnemonic_story_es": "Añadir otro travesaño sobre el bastidor, denotando repetir una acción una vez más (再).", "tone_mnemonic_anchor": "51", "cangjie": "GBY", "traditional": "再"}], "extended_reading_passages": [{"id": "#1", "hanzi": "科学家在发布气候变化评估报告时一再警告，全球气温持续上升将引发极端风暴与严重干旱。如果各国不能尽快达成碳减排约束性协议，人类社会赖以生存的生态平衡系统将在不远的将来面临不可逆转的灾难性崩溃。", "pinyin": "Kēxuéjiā zài fābù qìhòu biànhuà pínggū bàogào shí yízài jǐnggào, quánqiú qìwēn chíxù shàngshēng jiāng yǐnfā jíduān fēngbào yǔ yánzhòng gānhàn. Rúguǒ gèguó bùnéng jǐnkuài dáchéng tàn jiǎnpái yuēshùxìng xiéyì, rénlèi shèhuì làiyǐ shēngcún de shēngtài pínghéng xìtǒng jiāng zài bù yuǎn de jiānglái miànlín bùkě nìzhuǎn de zāinànxìng bēngkuì.", "en": "Scientists issuing climate assessment reports warned repeatedly that rising temperatures will trigger extreme storms and droughts. Without binding carbon reduction pacts, the ecological equilibrium sustaining civilization faces irreversible collapse.", "es": "Al presentar su informe climático, los científicos advirtieron reiteradamente del riesgo de tormentas extremas y sequías por el calentamiento. Sin pactos vinculantes de emisiones, el equilibrio ecológico del planeta colapsará de forma irreversible."}, {"id": "#2", "hanzi": "在早期篮球教学实践中，学生们对每次投篮后不得不搬梯子取球的笨拙流程一再抱怨。比赛节奏的一再中断，让激烈的对抗气氛大打折扣。正是面对这种频繁发生的困扰，体育工匠才下定决心拿起锯子锯掉筐底，彻底革除了这一弊端。", "pinyin": "Zài zǎoqī lánqiú jiàoxué shíjiàn zhōng, xuéshengmen duì měicì tóulán hòu bùdébù bān tīzi qǔ qiú de bènzhuō liúchéng yízài bàoyuàn. Bǐsài jiézòu de yízài zhòngduàn, ràng jīliè de duìkàng qìfēn dàdǎ-zhékòu. Zhèng shì miànduì zhè zhǒng pínfán fāshēng de kùnrǎo, tǐyù gōngjiàng cái xiàdìng juéxīn ná qǐ jùzi jù diào kuāngdǐ, chèdǐ géchú le zhè yí bìduān.", "en": "During early basketball training, students complained repeatedly about fetching ladders after each score. The repeated game interruptions dampened the fierce competition. Prompted by these constant annoyances, craftsmen resolved to saw off the basket bottoms, eliminating the hassle forever.", "es": "En los primeros entrenamientos de baloncesto, los alumnos se quejaban reiteradamente de tener que acarrear escaleras tras cada canasta. El ritmo roto enfriaba el duelo, empujando a los conserjes a serrar el fondo para desterrar el problema."}]}, {"meanings_summary": {"en": "to repeat; duplicate; reiterate; repetition", "es": "repetir; duplicar; reiterar; repetición"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Layering over (重) and retracing footsteps back (复) leads to identical repetition (重复).", "composite_memory_hook_es": "Apilar capas (重) y desandar los pasos hacia el inicio (复) da lugar a una repetición idéntica (重复).", "cultural_and_cognitive_roots": "Foundational in cognitive learning theory (熟能生巧) and scientific experimentation where replicability validates truth.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'chóng fù' (35-51). Soar upward on 'chóng', then drive down decisively on 'fù'."}, "semantic_boundary_contrasts": {"core_nuance": "重复 indicates the identical recurrence of an action, sound, or state without substantial variation.", "contrasts": [{"id": "1", "compared_word": "重复 vs. 反复", "pinyin": "fǎnfù", "analysis": "反复 often connotes back-and-forth instability or wavering (病情反复, 反复无常), whereas 重复 means straightforward copying or reiteration."}, {"id": "2", "compared_word": "重复 vs. 循环", "pinyin": "xúnhuán", "analysis": "循环 implies a closed systemic loop (血液循环), while 重复 can be an isolated second occurrence of an event."}, {"id": "3", "compared_word": "重复 vs. 重建", "pinyin": "chóngjiàn", "analysis": "重建 means building from ruins or reconstructing an organization, whereas 重复 merely repeats an action."}]}, "traps_and_cognates": {"look_alikes": [{"character": "重", "pinyin": "chóng/zhòng", "meaning_en": "repeat; heavy", "distinction_note": "Single vertical axis piercing horizontal bars"}, {"character": "童", "pinyin": "tóng", "meaning_en": "child; youth", "distinction_note": "Has 立 (stand) on top instead of 千"}, {"character": "复", "pinyin": "fù", "meaning_en": "repeat; complex", "distinction_note": "Has 夂 at bottom"}, {"character": "夏", "pinyin": "xià", "meaning_en": "summer", "distinction_note": "Has 目-like head under the upper horizontal canopy"}], "etymological_cognates": [{"character": "叠", "pinyin": "dié", "gloss_en": "stack; fold; repeat"}, {"character": "蹈", "pinyin": "dǎo", "gloss_en": "tread; repeat steps"}, {"character": "循", "pinyin": "xún", "gloss_en": "follow; cycle"}, {"character": "环", "pinyin": "huán", "gloss_en": "ring; loop"}]}, "id": "17", "hanzi": "重复", "pinyin": "chóng fù", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to do, say, or undergo something again; to recur identically", "definition_es": "volver a hacer, decir o experimentar algo de forma idéntica", "example_phrase": "请把刚才的话重复一遍 (please repeat what you just said)"}], "example_sentences": [{"id": "#1", "hanzi": "由于网络信号在隧道中出现中断，会议主持人不得不把刚才的核心议题又向大家重复了一遍。", "pinyin": "Yóuyú wǎngluò xìnhào zài suìdào zhōng chūxiàn zhòngduàn, huìyì zhǔchírén bùdébù bǎ gāngcái de héxīn yìtí yòu xiàng dàjiā chóngfù le yí biàn.", "en": "Because network signals dropped inside the tunnel, the meeting host had to repeat the core agenda item to everyone once more.", "es": "Al cortarse la conexión en el túnel, el moderador de la reunión tuvo que repetir a los asistentes el punto central tratado."}, {"id": "#2", "hanzi": "历史经验告诉我们，只有深刻汲取教训并完善制度，才能避免在相同的危机面前重复过去的错误。", "pinyin": "Lìshǐ jīngyàn gàosù wǒmen, zhǐyǒu shēnkè jíqǔ jiàoxùn bìng wánshàn zhìdù, cái néng bìmiǎn zài xiāngtóng de wēijī miànqián chóngfù guòqù de cuòwù.", "en": "Historical experience teaches that only by profoundly absorbing lessons and refining institutions can we avoid repeating past mistakes during similar crises.", "es": "La historia demuestra que sólo aprendiendo de los errores y mejorando las instituciones evitaremos repetir pasadas equivocaciones ante crisis semejantes."}], "collocations": [{"hanzi": "重复一遍", "en": "repeat once again"}, {"hanzi": "机械重复", "en": "mechanical mindless repetition"}, {"hanzi": "重复建设", "en": "redundant construction / duplication"}, {"hanzi": "重复使用", "en": "reuse / repeated use"}, {"hanzi": "避免重复", "en": "avoid duplication"}, {"hanzi": "重复劳动", "en": "repetitive manual toil"}], "idioms": [{"hanzi": "重蹈覆辙", "pinyin": "chóng dǎo fù zhé", "meaning_en": "follow the overturned cart track; repeat the disastrous mistake"}, {"hanzi": "周而复始", "pinyin": "zhōu ér fù shǐ", "meaning_en": "circle round and begin anew; cyclical recurrence"}, {"hanzi": "日复一日", "pinyin": "rì fù yí rì", "meaning_en": "day after day; routine uninterrupted persistence"}, {"hanzi": "老生常谈", "pinyin": "lǎo shēng cháng tán", "meaning_en": "old scholar's platitude; familiar shopworn talk"}], "character_decomposition": [{"character": "重", "pinyin": "chóng", "meaning_en": "repeat; layer; again", "meaning_es": "repetir; capa; de nuevo", "radical": "里", "radical_meaning_en": "village / inside", "meaning_component": "pictograph of heavy baggage piled up in layers", "sound_component": "重 (chóng/zhòng)", "stroke_count": "9", "composition_type": "单一结构", "etymology_and_mnemonic": "A person standing over a layered bundle or heavy grain sack; dual reading as heavy (zhòng) and layered repetition (chóng).", "visual_mnemonic_story_en": "Multiple heavy bundles stacked on top of one another layer upon layer (重).", "visual_mnemonic_story_es": "Múltiples fardos pesados apilados uno sobre otro capa tras capa (重).", "tone_mnemonic_anchor": "35", "cangjie": "HJG", "traditional": "重"}, {"character": "复", "pinyin": "fù", "meaning_en": "return; repeat; complex", "meaning_es": "regresar; duplicar; complejo", "radical": "夂", "radical_meaning_en": "go / step", "meaning_component": "夂 (trailing footsteps) + 畐 (vessel)", "sound_component": "复 (fù)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Footsteps 夂 tracing a path back to a walled settlement; returning along original tracks to repeat an action.", "visual_mnemonic_story_en": "Footsteps (夂) turning around and retracing their exact path back to the starting point (复).", "visual_mnemonic_story_es": "Pasos (夂) que dan media vuelta desandando el camino exacto hacia el punto de partida (复).", "tone_mnemonic_anchor": "51", "cangjie": "OAE", "traditional": "複"}], "extended_reading_passages": [{"id": "#1", "hanzi": "科研工作者在实验室里日复一日地重复着枯燥的数据测定与化学配比实验。正是这种严谨求实、不厌其烦的高精度重复验证，才最终剥离掉偶然误差的干扰，让颠扑不破的科学真理在严苛检验中熠熠生辉。", "pinyin": "Kēyán gōngzuòzhě zài shíyànshì lǐ rì-fù-yírì de chóngfù zhe kūzào de shùjù cèdìng yǔ huàxué pèibǐ shíyàn. Zhèng shì zhè zhǒng yánjǐn qiúshí, bùyàn-qífán de gāo jīngdù chóngfù yànzhèng, cái zuìzhōng bōlí diào ǒurán wùchā de gānrǎo, ràng diānpū-bùpò de kēxué zhēnlǐ zài yánkē jiǎnyàn zhōng yìyì-shēnghuī.", "en": "Researchers repeated tedious data calibrations and chemical ratios day after day in the laboratory. It was this rigorous, untiring repetition that stripped away accidental errors, allowing immutable scientific truth to shine through.", "es": "Los científicos repetían mediciones y formulaciones día tras día en el laboratorio. Esa meticulosa comprobación reiterada permitió descartar errores fortuitos, corroborando con rigor la verdad científica ante la prueba experimental."}, {"id": "#2", "hanzi": "早期的篮球比赛每得一分，裁判和队员都必须重复相同的繁琐动作：暂停走表、搬出梯子、爬上去把球取出、再放回场中重新跳球。这种单调机械的重复不仅打断了比赛的连贯性，更严重制约了体育竞技激情的释放。", "pinyin": "Zǎoqī de lánqiú bǐsài měi dé yì fēn, cáipàn hé duìyuán dōu bìxū chóngfù xiāngtóng de fánsuǒ dòngzuò: zàntíng zǒu biǎo, bān chū tīzi, pá shàngqu bǎ qiú qǔ chū, zài fàng huí chǎngzhōng chóngxīn tiào qiú. Zhè zhǒng dāndiào jīxiè de chóngfù bùjǐn dǎduàn le bǐsài de liánguànxìng, gèng yánzhòng zhìyuē le tǐyù jìngjì jīqíng de shìfàng.", "en": "Every scored point in early basketball forced players and referees to repeat the same tedious cycle: stop the clock, drag out a ladder, climb up to dislodge the ball, and resume with a jump ball. Such mechanical repetition crippled the game's continuity and spirit.", "es": "En los albores del baloncesto, cada canasta obligaba a repetir el mismo engorro: parar el reloj, arrastrar la escalera, descolgar el balón y hacer un salto entre dos. Esa pesada rutina cortaba la fluidez ahogando la emoción del juego."}]}, {"meanings_summary": {"en": "intermittent; off and on; discontinuous; fitful", "es": "intermitente; entrecortado; discontinuo; a saltos"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Breaking apart (断) and tying back together (续) over and over creates an intermittent rhythm (断断续续).", "composite_memory_hook_es": "Romper (断) y volver a empalmar (续) sucesivamente da lugar a una cadencia intermitente (断断续续).", "cultural_and_cognitive_roots": "A classic AABB four-character reduplicative adjective conveying rhythmic hesitation, fragmentation, or sporadic recurrence.", "tone_sandhi_and_pitch_modulation": "Four syllables: 'duàn duàn xù xù' (51-51-51-51). Pronounce with staccato, rhythmic falling tones mirroring fitful pauses."}, "semantic_boundary_contrasts": {"core_nuance": "断断续续 expresses discontinuous cadence, halting pauses, or erratic recurrence.", "contrasts": [{"id": "1", "compared_word": "断断续续 vs. 陆陆续续", "pinyin": "lùlù-xùxù", "analysis": "陆陆续续 describes people arriving or events happening one after another over time without back-and-forth breaking, while 断断续续 stresses intermittent interruption."}, {"id": "2", "compared_word": "断断续续 vs. 连续不断", "pinyin": "liánxù-búduàn", "analysis": "连续不断 denotes smooth unbroken continuity, the direct antonym of 断断续续."}, {"id": "3", "compared_word": "断断续续 vs. 偶尔", "pinyin": "ǒu'ěr", "analysis": "偶尔 means occasional isolated instances, while 断断续续 implies an ongoing stream plagued by frequent stops and starts."}]}, "traps_and_cognates": {"look_alikes": [{"character": "断", "pinyin": "duàn", "meaning_en": "break; snap", "distinction_note": "Axe radical 斤 on the right"}, {"character": "继", "pinyin": "jì", "meaning_en": "succeed; follow", "distinction_note": "Has 纟 on left with 米 and 乚"}, {"character": "续", "pinyin": "xù", "meaning_en": "continue; join", "distinction_note": "Has 纟 on left with 卖 on right"}, {"character": "读", "pinyin": "dú", "meaning_en": "read; study", "distinction_note": "Speech radical 讠 on left with 卖"}], "etymological_cognates": [{"character": "停", "pinyin": "tíng", "gloss_en": "stop; halt"}, {"character": "歇", "pinyin": "xiē", "gloss_en": "rest; pause"}, {"character": "顿", "pinyin": "dùn", "gloss_en": "pause; sudden"}, {"character": "缀", "pinyin": "zhuì", "gloss_en": "stitch together; embellish"}]}, "id": "18", "hanzi": "断断续续", "pinyin": "duàn duàn xù xù", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "stopping and starting repeatedly at irregular intervals; discontinuous in time, sound, or action", "definition_es": "que cesa y recomienza sucesivamente con interrupciones frecuentes de tiempo o sonido", "example_phrase": "断断续续的琴声 (intermittent piano notes)"}], "example_sentences": [{"id": "#1", "hanzi": "深夜的山谷里下起了断断续续的微雨，清凉的雨滴敲打着窗外的芭蕉叶，伴随着淅淅沥沥的水声传入耳畔。", "pinyin": "Shēnyè de shāngǔ lǐ xià qǐ le duànduàn-xùxù de wēiyǔ, qīngliáng de yǔdī qiāodǎ zhe chuāngwài de bājiāoyè, bànsuí zhe xīxī-lìlì de shuǐshēng chuán rù ěrpàn.", "en": "In the valley at midnight, intermittent drizzle began to fall, cool raindrops tapping upon banana leaves outside the window with gentle splashes.", "es": "A medianoche caía una llovizna intermitente en el valle; las frescas gotas golpeaban los bananeros del patio arrullando el sueño con su leve rumor."}, {"id": "#2", "hanzi": "由于山区基站遭受雷击损坏，前线救援队员只能依靠断断续续的卫星无线电信号与指挥中心保持微弱联络。", "pinyin": "Yóuyú shānqū jīzhàn shòuzāo léijī sǔnhuài, qiánxiàn jiùyuánduìyuán zhǐ néng yīkào duànduàn-xùxù de wèixīng wúxiàndiàn xìnhào yǔ zhǐhuī zhōngxīn bǎochí wēiruò liánluò.", "en": "Because mountain cell towers were damaged by lightning, rescue teams had to rely on intermittent satellite radio signals to maintain faint contact with headquarters.", "es": "Averiada la antena por un rayo, los rescatistas sólo pudieron mantener una débil comunicación con la base mediante señales de radio intermitentes."}], "collocations": [{"hanzi": "断断续续的雨", "en": "intermittent rain / showers"}, {"hanzi": "断断续续的声音", "en": "broken, intermittent sound"}, {"hanzi": "断断续续地进行", "en": "proceed in fits and starts"}, {"hanzi": "断断续续的记忆", "en": "patchy, fragmentary memories"}, {"hanzi": "信号断断续续", "en": "spotty / intermittent signal"}, {"hanzi": "断断续续地讲述", "en": "recount haltingly"}], "idioms": [{"hanzi": "时断时续", "pinyin": "shí duàn shí xù", "meaning_en": "stopping and starting alternately; intermittent"}, {"hanzi": "声断气噎", "pinyin": "shēng duàn qì yē", "meaning_en": "sobbing fitfully with broken gasps"}, {"hanzi": "连绵不断", "pinyin": "liánmián bú duàn", "meaning_en": "continuous and unbroken; stretching endlessly"}, {"hanzi": "藕断丝连", "pinyin": "ǒu duàn sī lián", "meaning_en": "lotus root snapped but fibers still cling; lingering ties"}], "character_decomposition": [{"character": "断", "pinyin": "duàn", "meaning_en": "snap; break off; sever; decide", "meaning_es": "romper; quebrar; seccionar; decidir", "radical": "斤", "radical_meaning_en": "axe", "meaning_component": "斤 (axe chopping) + 米 (silk threads / grain bundles)", "sound_component": "断 (duàn)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "An axe 斤 chopping through bundled skeins of thread 米; severing connection and snapping in two.", "visual_mnemonic_story_en": "An axe blade (斤) slicing straight through skeins of silk thread (米) to break them apart (断).", "visual_mnemonic_story_es": "El filo de un hacha (斤) cortando hebras de seda (米) para seccionarlas en dos (断).", "tone_mnemonic_anchor": "51", "cangjie": "VIDH", "traditional": "斷"}, {"character": "续", "pinyin": "xù", "meaning_en": "continue; replenish; tie together", "meaning_es": "continuar; reanudar; enlazar", "radical": "纟", "radical_meaning_en": "silk thread", "meaning_component": "纟 (silk cords) + 卖 (prolonged trade)", "sound_component": "卖 (mài / phonetic association)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Silk radical 纟 beside 卖; tying broken ends of silk filaments together to maintain an unbroken continuum.", "visual_mnemonic_story_en": "Tying loose silk cords (纟) together at the marketplace (卖) to keep the thread going (续).", "visual_mnemonic_story_es": "Empatar cabos de seda sueltos (纟) para que la línea continúe sin romperse (续).", "tone_mnemonic_anchor": "51", "cangjie": "VFGND", "traditional": "續"}], "extended_reading_passages": [{"id": "#1", "hanzi": "病榻上的老红军呼吸微弱，拉着孙子的手断断续续地回忆起战火纷飞的峥嵘岁月。那些零散破碎的字句，虽被剧烈的咳嗽屡次打断，却依然如重锤般撞击着年轻人的心灵，传递着穿越时空的坚贞信仰。", "pinyin": "Bìngtà shang de lǎo hóngjūn hūxī wēiruò, lā zhe sūnzi de shǒu duànduàn-xùxù de huíyì qǐ zhànhuǒ fēnfēi de zhēngróng suìyuè. Nàxiē língsǎn pòsuì de zìjù, suī bèi jùliè de késou lǚcì dǎduàn, què yīrán rú zhòngchuí bān zhuàngjī zhe niánqīngrén de xīnlíng, chuándì zhe chuānyuè shíkōng de jiānzhēn xìnyǎng.", "en": "On his sickbed, the frail veteran gripped his grandson's hand, haltingly recalling wartime years. Though interrupted by coughing bouts, his fragmented words struck the young man's heart like hammers, conveying timeless steadfast faith.", "es": "En su lecho, el anciano combatiente rememoraba entrecortadamente los años de guerra. Aunque la tos quebraba sus palabras, aquel relato fragmentario conmovió hondamente a su nieto transmitiéndole una fe inquebrantable."}, {"id": "#2", "hanzi": "未开底的桃筐曾给最初的篮球比赛带来了毁灭性的断断续续。每当双方球员在热烈呐喊中投球入网，裁判就必须强行按停计时表，场上热烈沸腾的气氛也随即冷却下来。正是为了消除这种令人烦躁的断断续续，才促成了锯开筐底的革新。", "pinyin": "Wèi kāidǐ de táokuāng céng gěi zuìchū de lánqiú bǐsài dài lái le huǐmièxìng de duànduàn-xùxù. Měidāng shuāngfāng qiúyuán zài rèliè nàhǎn zhōng tóu qiú rù wǎng, cáipàn jiù bìxū qiángxíng àntíng jìshíbiǎo, chǎngshang rèliè fèiténg de qìfēn yě suíjí lěngquè xiàlái. Zhèng shì wèile xiāochú zhè zhǒng lìngrén fánzào de duànduàn-xùxù, cái cùchéng le jù kāi kuāngdǐ de géxīn.", "en": "Peach baskets without open bottoms brought frustrating intermittence to early basketball. Whenever a ball went in amid cheers, referees had to freeze the clock, dousing the court's fiery momentum. Eliminating this annoying stop-and-start catalyzed sawing off the basket bottoms.", "es": "Las cestas ciegas provocaban una fastidiosa discontinuidad en el baloncesto primigenio. Tras cada enceste en plena ovación, el colegiado paraba el cronómetro enfriando el duelo. Erradicar esas pausas impulsó la genial idea de abrir el fondo."}]}, {"meanings_summary": {"en": "intense; fierce; acute; sharp (competition/debate)", "es": "intenso; feroz; encarnizado; vehemente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Surging whitewater currents (激) meeting blazing fire flames (烈) produce intense ferocity (激烈).", "composite_memory_hook_es": "El ímpetu del torrente de agua (激) sumado a un fuego abrasador (烈) desata una lucha encarnizada (激烈).", "cultural_and_cognitive_roots": "Metaphor combining torrential water surges and roaring flames to describe heated struggles, sports, and debates.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling fourth tone: 'jī liè' (55-51). Sustain 'jī' with energy, then strike sharply down on 'liè'."}, "semantic_boundary_contrasts": {"core_nuance": "激烈 describes dynamic confrontations, contests, motions, or debates that reach extreme fever pitch.", "contrasts": [{"id": "1", "compared_word": "激烈 vs. 强烈", "pinyin": "qiángliè", "analysis": "强烈 describes sensations, emotions, lights, or desires (强烈愿望, 强烈地震), while 激烈 depicts dynamic external actions, combats, and sports."}, {"id": "2", "compared_word": "激烈 vs. 热烈", "pinyin": "rèliè", "analysis": "热烈 conveys joyful enthusiasm and warmth (热烈欢迎, 掌声热烈), whereas 激烈 emphasizes aggressive rivalry and conflict."}, {"id": "3", "compared_word": "激烈 vs. 严厉", "pinyin": "yánlì", "analysis": "严厉 characterizes harsh disciplinary attitudes or punishment (严厉批评), not athletic contests."}]}, "traps_and_cognates": {"look_alikes": [{"character": "激", "pinyin": "jī", "meaning_en": "surge; fierce", "distinction_note": "Water radical 氵 on left with 敫"}, {"character": "澈", "pinyin": "chè", "meaning_en": "crystal clear", "distinction_note": "Has 育 in middle instead of 白/方"}, {"character": "烈", "pinyin": "liè", "meaning_en": "intense; fiery", "distinction_note": "Fire radical 灬 at bottom under 列"}, {"character": "列", "pinyin": "liè", "meaning_en": "row; line; arrange", "distinction_note": "Without the fire dots at bottom"}], "etymological_cognates": [{"character": "猛", "pinyin": "měng", "gloss_en": "fierce; ferocious"}, {"character": "热", "pinyin": "rè", "gloss_en": "hot; ardent"}, {"character": "酷", "pinyin": "kù", "gloss_en": "ruthless; harsh; intense"}, {"character": "厉", "pinyin": "lì", "gloss_en": "stern; severe"}]}, "id": "19", "hanzi": "激烈", "pinyin": "jī liè", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "violent, sharp, or intensely competitive in action, speech, or contest", "definition_es": "vehemente, violento o sumamente reñido en disputas, combates o competiciones", "example_phrase": "激烈的市场竞争 (intense market competition)"}], "example_sentences": [{"id": "#1", "hanzi": "经过四节激烈焦灼的加时鏖战，客场作战的年轻球队终于以一分微弱优势险胜卫冕冠军。", "pinyin": "Jīngguò sì jié jīliè jiāozhuó de jiāshí áozhàn, kèchǎng zuòzhàn de niánqīng qiúduì zhōngyú yǐ yì fēn wēiruò yōushì xiǎnshèng wèimiǎn guànjūn.", "en": "After four quarters of intensely grueling overtime struggle, the young visiting team finally edged out the defending champions by a razor-thin one-point margin.", "es": "Tras cuatro periodos de encarnizada prórroga, el joven conjunto visitante se impuso al vigente campeón por la mínima renta de un punto."}, {"id": "#2", "hanzi": "在今天举行的听证会上，双方律师围绕核心证据的法律效力展开了异常激烈而尖锐的言语交锋。", "pinyin": "Zài jīntiān jǔxíng de tīngzhènghuì shang, shuāngfāng lǜshī wéirào héxīn zhèngjù de fǎlǜ xiàolì zhǎnkāi le yìcháng jīliè ér jiānruì de yányǔ jiāofēng.", "en": "At today's hearing, opposing attorneys engaged in exceptionally fierce and sharp verbal clashes surrounding the admissibility of core evidence.", "es": "En la vista judicial de hoy, los letrados sostuvieron un duelo dialéctico sumamente vehemente en torno a la validez de la prueba pericial."}], "collocations": [{"hanzi": "激烈竞争", "en": "fierce / intense competition"}, {"hanzi": "激烈争论", "en": "heated / fierce debate"}, {"hanzi": "战斗激烈", "en": "fierce fighting in battle"}, {"hanzi": "言辞激烈", "en": "vehement / fierce words"}, {"hanzi": "异常激烈", "en": "unusually intense"}, {"hanzi": "激烈对抗", "en": "intense confrontation"}], "idioms": [{"hanzi": "龙争虎斗", "pinyin": "lóng zhēng hǔ dòu", "meaning_en": "struggle between dragon and tiger; fierce titanic clash"}, {"hanzi": "风起云涌", "pinyin": "fēng qǐ yún yǒng", "meaning_en": "winds gather and clouds surge; dramatic rapid developments"}, {"hanzi": "惊心动魄", "pinyin": "jīng xīn dòng pò", "meaning_en": "thrilling and breathtaking; heart-stirring shock"}, {"hanzi": "如火如荼", "pinyin": "rú huǒ rú tú", "meaning_en": "flourishing like wildfire; surging intensely"}], "character_decomposition": [{"character": "激", "pinyin": "jī", "meaning_en": "surge; arouse; fierce water flow", "meaning_es": "desbordar; excitar; torrente", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (turbulent water) + 敫 (bright white light / strike)", "sound_component": "敫 (jiào / phonetic)", "stroke_count": "16", "composition_type": "左右结构", "etymology_and_mnemonic": "Water radical 氵 beside 敫; crashing water surging over rocks, generating rapid currents and white spray.", "visual_mnemonic_story_en": "Turbulent water currents (氵) violently striking against river boulders, surging in white spray (激).", "visual_mnemonic_story_es": "Aguas bravas (氵) que embisten contra los escollos rocosos alzando espumarajos turbulentos (激).", "tone_mnemonic_anchor": "55", "cangjie": "EHSK", "traditional": "激"}, {"character": "烈", "pinyin": "liè", "meaning_en": "blazing; ardent; fierce; violent", "meaning_es": "ardiente; violento; vehemente", "radical": "灬", "radical_meaning_en": "fire", "meaning_component": "灬 (four dots of raging fire) + 列 (split with knife)", "sound_component": "列 (liè / phonetic)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Raging fire flames 灬 burning fiercely beneath cleaved fuel 列; symbolizes extreme intensity, heat, and vehement force.", "visual_mnemonic_story_en": "Raging flames (灬) consuming split firewood (列) in an inferno of intense heat (烈).", "visual_mnemonic_story_es": "Llamas voraces (灬) devorando leña rajada (列) en una hoguera de calor abrasador (烈).", "tone_mnemonic_anchor": "51", "cangjie": "MNOF", "traditional": "烈"}], "extended_reading_passages": [{"id": "#1", "hanzi": "现代商业社会的竞争异常激烈，任何固步自封、安于现状的企业都会在转瞬之间被汹涌的技术浪潮所淘汰。唯有时刻保持敏锐的危机意识，敢于自我颠覆并不断推陈出新，方能在激烈的市场大潮中立于不败之地。", "pinyin": "Xiàndài shāngyè shèhuì de jìngzhēng yìcháng jīliè, rènhé gùbù-zìfēng, ānyú xiànzhuàng de qǐyè dōu huì zài zhuǎnshùn zhījiān bèi xiōngyǒng de jìshù làngcháo suǒ táotài. Wéi yǒu shíkè bǎochí mǐnruì de wēijī yìshí, gǎnyú zìwǒ diānfù bìng búduàn tuīchén-chūxīn, fāng néng zài jīliè de shìchǎng dàcháo zhōng lìyú-búbàizhīdì.", "en": "Modern commercial rivalry is brutally intense; any company resting on its laurels will be swept away by surging technological tides. Only by maintaining acute crisis awareness and bold self-disruption can one stay invincible amid fierce market headwinds.", "es": "La rivalidad comercial actual es implacable; las empresas acomodadas caen barridas por olas de innovación. Sólo quien mantiene alerta su sentido de supervivencia y se reinventa logra prevalecer invicto en ese agitado mercado."}, {"id": "#2", "hanzi": "奈史密斯发明篮球旨在为冬季青年提供室内运动。随着规则完善，对抗日益激烈。球星们高超的投篮技艺与雷霆万钧的封盖，构成了当今体坛最令人热血沸腾的竞技盛景。", "pinyin": "Nàishǐmīsī fāmíng lánqiú zhǐzài wèi dōngjì qīngnián tígōng shìnèi yùndòng. Suízhe guīzé wánshàn, duìkàng rìyì jīliè. Qiúxīngmen gāocháo de tóulán jìyì yǔ léitíng-wànjūn de fēnggài, gòuchéng le dāngjīn tǐtán zuì lìngrén rèxuè-fèiténg de jìngjì shèngjǐng.", "en": "Naismith invented basketball to provide indoor athletic exercise for youth in winter. As rules matured, matchups grew fiercely competitive. Sublime shooting and thunderous blocks now form one of sports' most electrifying spectacles.", "es": "Naismith concibió el baloncesto para ejercitar a los jóvenes bajo techo en invierno. Con la madurez reglamentaria, el duelo se tornó encarnizado, deslumbrando al mundo con tiros magistrales y tapones colosales."}]}, {"meanings_summary": {"en": "atmosphere; ambience; mood (of a place or gathering)", "es": "atmósfera; ambiente; clima (emocional o social)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Vaporous air (气) spreading across the room (氛) creates the palpable atmosphere (气氛).", "composite_memory_hook_es": "El aliento invisible del aire (气) que impregna el espacio (氛) conforma la atmósfera del lugar (气氛).", "cultural_and_cognitive_roots": "Deeply linked to traditional Chinese concept of 'Qi' (气), the intangible energetic vibe uniting people and environment.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by level high tone: 'qì fēn' (51-55). Strike down on 'qì', then float evenly on high 'fēn'."}, "semantic_boundary_contrasts": {"core_nuance": "气氛 denotes the psychological, emotional, or social ambience prevailing in a shared space.", "contrasts": [{"id": "1", "compared_word": "气氛 vs. 环境", "pinyin": "huánjìng", "analysis": "环境 refers to objective physical conditions, surroundings, or ecology, whereas 气氛 describes intangible emotional ambience."}, {"id": "2", "compared_word": "气氛 vs. 气候", "pinyin": "qìhòu", "analysis": "气候 denotes meteorological weather patterns over decades, while 气氛 is the psychological tone of a gathering."}, {"id": "3", "compared_word": "气氛 vs. 心情", "pinyin": "xīnqíng", "analysis": "心情 is an individual's private emotional state, whereas 气氛 is collective and shared across a group or venue."}]}, "traps_and_cognates": {"look_alikes": [{"character": "氛", "pinyin": "fēn", "meaning_en": "atmosphere", "distinction_note": "Contains 分 inside 气"}, {"character": "氧", "pinyin": "yǎng", "meaning_en": "oxygen", "distinction_note": "Contains 羊 inside 气"}, {"character": "氮", "pinyin": "dàn", "meaning_en": "nitrogen", "distinction_note": "Contains 炎 inside 气"}, {"character": "氢", "pinyin": "qīng", "meaning_en": "hydrogen", "distinction_note": "Contains 𢀖 inside 气"}], "etymological_cognates": [{"character": "境", "pinyin": "jìng", "gloss_en": "environment; realm"}, {"character": "情", "pinyin": "qíng", "gloss_en": "emotion; sentiment"}, {"character": "象", "pinyin": "xiàng", "gloss_en": "phenomenon; aura"}, {"character": "象", "pinyin": "xiàng", "gloss_en": "image; manifestation"}]}, "id": "20", "hanzi": "气氛", "pinyin": "qì fēn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the pervading tone, mood, or emotional climate of a place, meeting, or event", "definition_es": "estado o tono emocional que se respira en un lugar, reunión o espectáculo", "example_phrase": "热烈活跃的节日气氛 (a lively and warm festive atmosphere)"}], "example_sentences": [{"id": "#1", "hanzi": "除夕之夜全家人围坐在热气腾腾的火锅旁守岁，客厅里处处洋溢着团圆祥和的温馨气氛。", "pinyin": "Chúxī zhī yè quánjiā rén wéizuò zài rèqì-téngténg de huǒguō páng shǒusuì, kètīng lǐ chùchù yángyì zhe tuányuán xiánghé de wēnxīn qìfēn.", "en": "On New Year's Eve, the whole family gathered around the steaming hotpot to welcome the new year, the parlor brimming with a cozy atmosphere of reunion and peace.", "es": "En Nochevieja, la familia se congregó en torno al humeante caldero mongol, respirándose en la sala una atmósfera entrañable de armonía y reencuentro."}, {"id": "#2", "hanzi": "谈判刚开始时双方各不相让，但随着主谈代表幽默机智的开场发言，紧张压抑的会谈气氛逐渐缓和了下来。", "pinyin": "Tánpàn gāng kāishǐ shí shuāngfāng gèbùxiāngràng, dàn suízhe zhǔtán dàibiǎo yōumò jīzhì de kāichǎng fāyán, jǐnzhāng yāyì de huìtán qìfēn zhújiàn huǎnhé le xiàlái.", "en": "The talks began with neither side yielding an inch, but with the chief negotiator's witty remarks, the tense and oppressive atmosphere gradually thawed.", "es": "La negociación arrancó con total rigidez, pero el ingenioso discurso inaugural del mediador destensó gradualmente el agobiante clima de la sala."}], "collocations": [{"hanzi": "节日气氛", "en": "festive atmosphere"}, {"hanzi": "紧张气氛", "en": "tense atmosphere"}, {"hanzi": "热烈气氛", "en": "warm / spirited ambience"}, {"hanzi": "活跃气氛", "en": "liven up the mood / atmosphere"}, {"hanzi": "营造气氛", "en": "create an atmosphere"}, {"hanzi": "气氛融洽", "en": "harmonious / congenial atmosphere"}], "idioms": [{"hanzi": "欢天喜地", "pinyin": "huān tiān xǐ dì", "meaning_en": "overjoyed; filled with exuberant rejoicing"}, {"hanzi": "喜气洋洋", "pinyin": "xǐ qì yáng yáng", "meaning_en": "beaming with joy; cheerful holiday spirit"}, {"hanzi": "剑拔弩张", "pinyin": "jiàn bá nǔ zhāng", "meaning_en": "swords drawn and bows bent; touch-and-go explosive tension"}, {"hanzi": "和风细雨", "pinyin": "hé fēng xì yǔ", "meaning_en": "gentle breeze and mild rain; patient kindly persuasion"}], "character_decomposition": [{"character": "气", "pinyin": "qì", "meaning_en": "air; gas; energy; mood; spirit", "meaning_es": "aire; gas; aliento; espíritu", "radical": "气", "radical_meaning_en": "steam / breath", "meaning_component": "pictograph of rising clouds and curling steam", "sound_component": "气 (qì)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph of layers of vapor and steam curling upward into the sky; vital life force and atmospheric air.", "visual_mnemonic_story_en": "Wisps of vapor and warm air (气) rising gently into the atmosphere.", "visual_mnemonic_story_es": "Volutas de vapor y aliento cálido (气) elevándose suavemente en el aire.", "tone_mnemonic_anchor": "51", "cangjie": "ON", "traditional": "氣"}, {"character": "氛", "pinyin": "fēn", "meaning_en": "atmosphere; vapor; misty haze", "meaning_es": "vaho; atmósfera; halo", "radical": "气", "radical_meaning_en": "steam / breath", "meaning_component": "气 (atmospheric vapor) + 分 (divide / share)", "sound_component": "分 (fēn / phonetic)", "stroke_count": "8", "composition_type": "半包围结构", "etymology_and_mnemonic": "Air radical 气 enclosing 分; ambient vapor and mist dividing and drifting across the environment, setting its mood.", "visual_mnemonic_story_en": "Vapors (气) drifting and dispersing (分) to envelope an entire room in a distinct mood (氛).", "visual_mnemonic_story_es": "Vahos etéreos (气) que se dispersan (分) impregnando el ambiente de un matiz singular (氛).", "tone_mnemonic_anchor": "55", "cangjie": "ONCSH", "traditional": "氛"}], "extended_reading_passages": [{"id": "#1", "hanzi": "春节期间的大街小巷张灯结彩，到处弥漫着浓郁喜庆的年节气氛。爆竹声声伴随着清脆的欢笑，邻里之间互致吉祥问候，那一份份淳朴热烈的情感，在冬日暖阳的照耀下汇聚成最动人的社会温情画卷。", "pinyin": "Chūnjié qījiān de dàjiē-xiǎoxiàng zhāngdēng-jiécǎi, dàochù mímàn zhe nóngyù xǐqìng de niánjié qìfēn. Bàozhú shēngshēng bànsuí zhe qīngcuì de huānxiào, línlǐ zhījiān hùzhì jíxiáng wènhòu, nà yífènfèn chúnpǔ rèliè de qínggǎn, zài dōngrì nuǎnyáng de zhàoyào xià huìjù chéng zuì dòngrén de shèhuì wēnqíng huàjuàn.", "en": "During Spring Festival, streets were adorned with lanterns and festive streamers, suffused with celebratory holiday cheer. Firecrackers popped alongside laughter as neighbors exchanged blessings, weaving a moving tapestry of community warmth.", "es": "En Año Nuevo chino, las calles lucían farolillos entre una atmósfera festiva y entrañable. Petardos y risas se fundían con parabienes vecinales, conformando bajo el sol invernal un cálido tapiz de afecto social."}, {"id": "#2", "hanzi": "篮球场上火热的竞技气氛，最忌讳被频繁机械的停顿所扑灭。早年因为桃筐未掏空底部，每次投篮进球后观众都必须百无聊赖地看着工人们踩梯取球，原本紧张刺激的比赛气氛瞬间变得索然无味。锯掉筐底的巧思，真正挽救了这项运动的灵魂活力。", "pinyin": "Lánqiúchǎng shang huǒrè de jìngjì qìfēn, zuì jìhuì bèi pínfán jīxiè de tíngdùn suǒ pūmiè. Zǎonián yīnwèi táokuāng wèi tāokōng dǐbù, měicì tóulán jìnqiú hòu guānzhòng dōu bìxū bǎiwú-liáolài de kàn zhe gōngrénmen cǎi tī qǔ qiú, yuánběn jǐnzhāng cìjī de bǐsài qìfēn shùnjiān biàn de suǒrán-wúwèi. Jù diào kuāngdǐ de qiǎosī, zhēnzhèng wǎnjiù le zhè xiàng yùndòng de línghún huólì.", "en": "The fiery atmosphere of the basketball court suffers most from mechanical interruptions. In early years, because peach baskets lacked open bottoms, fans boredly watched workers climb ladders after each score, deflating the thrilling mood. Sawing open the bottom truly salvaged the sport's electric soul.", "es": "El fervor de la pista de baloncesto se marchita con parones mecánicos. Al inicio, las canastas ciegas forzaban al público a contemplar cómo se bajaba el balón con escaleras, apagando la pasión. Abrir el fondo rescató el alma vibrante del juego."}]}, {"meanings_summary": {"en": "let alone; much less; not to mention", "es": "mucho menos; con mayor razón; cuánto más"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Asking why (何) about an already obvious condition (况) introduces a further reason: let alone (何况).", "composite_memory_hook_es": "Preguntar el porqué (何) sobre una evidencia obvia (况) sirve para recalcar con mayor motivo (何况).", "cultural_and_cognitive_roots": "A cornerstone logical conjunction in classical Chinese argumentation (况且/何况) used to reinforce a conclusion a fortiori.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'hé kuàng' (35-51). Smooth upward glide on 'hé' followed by crisp fall on 'kuàng'."}, "semantic_boundary_contrasts": {"core_nuance": "何况 introduces an a fortiori argument highlighting an even stronger, more obvious factor.", "contrasts": [{"id": "1", "compared_word": "何况 vs. 况且", "pinyin": "kuàngqiě", "analysis": "况且 adds a supplementary parallel reason (今天很冷，况且下雨), while 何况 is primarily used in rhetorical '尚且……何况……' contrastive logic."}, {"id": "2", "compared_word": "何况 vs. 甚至", "pinyin": "shènzhì", "analysis": "甚至 emphasizes an extreme surprising example (连老人甚至婴儿), whereas 何况 introduces an obvious deduced truth."}, {"id": "3", "compared_word": "何况 vs. 反而", "pinyin": "fǎn'ér", "analysis": "反而 indicates an outcome contrary to expectations, whereas 何况 deepens the expected gradient."}]}, "traps_and_cognates": {"look_alikes": [{"character": "何", "pinyin": "hé", "meaning_en": "what; how", "distinction_note": "Person radical 亻 on left with 可"}, {"character": "河", "pinyin": "hé", "meaning_en": "river", "distinction_note": "Water radical 氵 on left"}, {"character": "况", "pinyin": "kuàng", "meaning_en": "situation; moreover", "distinction_note": "Ice radical 冫 on left with 兄"}, {"character": "祝", "pinyin": "zhù", "meaning_en": "wish; pray", "distinction_note": "Altard radical 礻 on left with 兄"}], "etymological_cognates": [{"character": "且", "pinyin": "qiě", "gloss_en": "furthermore; moreover"}, {"character": "兼", "pinyin": "jiān", "gloss_en": "simultaneously; combine"}, {"character": "更", "pinyin": "gèng", "gloss_en": "even more; further"}, {"character": "况", "pinyin": "kuàng", "gloss_en": "circumstance; moreover"}]}, "id": "21", "hanzi": "何况", "pinyin": "hé kuàng", "level": "HSK 5", "part_of_speech": "Conjunction", "senses": [{"sense_number": "1", "part_of_speech": "Conjunction", "register": "Standard", "definition_en": "used to introduce a further more obvious point or reason, often equivalent to 'much less' or 'all the more so'", "definition_es": "introduce una razón o consideración adicional aún más evidente; mucho más, con más motivo", "example_phrase": "大人尚且吃不消，何况小孩呢 (adults can hardly endure it, let alone a child)"}], "example_sentences": [{"id": "#1", "hanzi": "连经验丰富的老船长在如此恶劣的风暴中都感到吃力，何况是初次出海的新水手呢。", "pinyin": "Lián jīngyàn fēngfù de lǎo chuánzhǎng zài rúcǐ èliè de fēngbào zhōng dōu gǎndào chīlì, hékuàng shì chūcì chūhǎi de xīn shuǐshǒu ne.", "en": "Even seasoned captains find it arduous in such severe storms, let alone novice sailors putting to sea for the first time.", "es": "Incluso un viejo capitán curtido se las ve difíciles en semejante temporal, cuánto más los marineros novatos en su primera travesía."}, {"id": "#2", "hanzi": "目前公司核心产品的销量在本土市场尚且停滞不前，何况盲目进军竞争惨烈的海外新兴市场。", "pinyin": "Mùqián gōngsī héxīn chǎnpǐn de xiàoliàng zài běntǔ shìchǎng shàngqiě tíngzhì-bùqián, hékuàng mángmù jìnjūn jìngzhēng cǎnliè de hǎiwài xīnxīng shìchǎng.", "en": "Presently, core product sales remain stagnant even domestically, let alone blindly charging into cutthroat emerging overseas markets.", "es": "Las ventas de la empresa están estancadas en el mercado nacional, cuánto más si se aventura a ciegas en el feroz mercado exterior."}], "collocations": [{"hanzi": "更何况", "en": "even more so; not to mention"}, {"hanzi": "尚且……何况……", "en": "even... let alone..."}, {"hanzi": "何况是", "en": "much less; let alone being"}, {"hanzi": "又何况", "en": "and what is more; let alone"}, {"hanzi": "何况还要", "en": "not to mention having to"}, {"hanzi": "何况如今", "en": "let alone nowadays"}], "idioms": [{"hanzi": "顾此失彼", "pinyin": "gù cǐ shī bǐ", "meaning_en": "attend to one and lose the other; unable to juggle both"}, {"hanzi": "雪上加霜", "pinyin": "xuě shàng jiā shuāng", "meaning_en": "add frost to snow; one disaster after another"}, {"hanzi": "举步维艰", "pinyin": "jǔ bù wéi jiān", "meaning_en": "hard to take a single step; struggling with difficulty"}, {"hanzi": "力不从心", "pinyin": "lì bù cóng xīn", "meaning_en": "ability falls short of one's desires; powerless to help"}], "character_decomposition": [{"character": "何", "pinyin": "hé", "meaning_en": "what; how; why", "meaning_es": "qué; cómo; por qué", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person carrying burden) + 可 (exclamation)", "sound_component": "可 (kě / phonetic link)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 carrying a shoulder pole 可; originally bearing a load, borrowed as an interrogative pronoun (what/why).", "visual_mnemonic_story_en": "A standing person (亻) carrying a heavy shoulder pole asking what burden lies ahead (何).", "visual_mnemonic_story_es": "Una persona (亻) cargando una pértiga al hombro preguntando qué peso le aguarda (何).", "tone_mnemonic_anchor": "35", "cangjie": "ONR", "traditional": "何"}, {"character": "况", "pinyin": "kuàng", "meaning_en": "condition; situation; furthermore", "meaning_es": "situación; además; estado", "radical": "冫", "radical_meaning_en": "ice", "meaning_component": "冫 (ice cold water) + 兄 (elder brother speaking)", "sound_component": "兄 (xiōng / phonetic connection)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Water/ice radical 冫 beside elder brother 兄; originally cold river conditions, extended to state of affairs and rhetorical comparison.", "visual_mnemonic_story_en": "An elder brother (兄) assessing freezing ice conditions (冫) to explain a further situation (况).", "visual_mnemonic_story_es": "El hermano mayor (兄) comprobando la escarcha helada (冫) para valorar la situación (况).", "tone_mnemonic_anchor": "51", "cangjie": "EMRU", "traditional": "況"}], "extended_reading_passages": [{"id": "#1", "hanzi": "古人讲‘穷则独善其身，达则兼济天下’。普通百姓在困窘之时尚且恪守廉洁良知，不为非分之财所动，何况身为执掌公共权柄的官员，更当常思民生疾苦，以如履薄冰之心坚守清正廉明的政德底线。", "pinyin": "Gǔrén jiǎng 'qióng zé dú shàn qí shēn, dá zé jiān jì tiānxià'. Pǔtōng bǎixìng zài kùnjiǒng zhī shí shàngqiě kèshǒu liánjié liángzhī, bù wéi fēifèn zhī cái suǒ dòng, hékuàng shēnwéi zhízhǎng gōnggòng quánbǐng de guānyuán, gèng dāng cháng sī mínshēng jíkǔ, yǐ rúlǚ-bóbīng zhī xīn jiānshǒu qīngzhèng-liánmíng de zhèngdé dǐxiàn.", "en": "The ancients noted that when poor, one should perfect oneself; when prosperous, help all under heaven. If ordinary folks preserve integrity in hardship, all the more should officials holding public power guard incorruptibility.", "es": "Decían los antiguos: en la estrechez, cultiva la virtud; en la holgura, ampara al mundo. Si el pueblo humilde guarda su honradez, cuánto más los gobernantes deben velar con probidad por el bienestar común."}, {"id": "#2", "hanzi": "在早期篮球比赛中，让两队队员干等着取球已经令人难以忍受，何况看台上还坐着满怀期待的热情球迷。这种漫长的停顿不仅打断了比赛的顺畅节奏，更让场馆里原本激烈的对抗气氛彻底降至冰点。正是这种多方共有的困扰，推动了规则的大胆革新。", "pinyin": "Zài zǎoqī lánqiú bǐsài zhōng, ràng liǎng duì duìyuán gān děng zhe qǔ qiú yǐjīng lìngrén nányǐ rěnshòu, hékuàng kàntái shang hái zuò zhe mǎnhuái qīdài de rèqíng qiúmí. Zhè zhǒng màncháng de tíngdùn bùjǐn dǎduàn le bǐsài de shùnchàng jiézòu, gèng ràng chǎngguǎn lǐ yuánběn jīliè de duìkàng qìfēn chèdǐ jiàng zhì bīngdiǎn. Zhèng shì zhè zhǒng duōfāng gòngyǒu de kùnrǎo, tuīdòng le guīzé de dàdǎn géxīn.", "en": "In early basketball, forcing both teams to stand waiting for the ball was already unbearable, let alone having passionate fans sitting in the stands. The long delay broke game rhythm and froze court excitement, impelling a bold rule revolution.", "es": "Hacer esperar a los jugadores tras cada canasta era insufrible, cuánto más con la grada llena de entusiastas aficionados. Esa demora rompía la fluidez congelando el fervor, propiciando una audaz reforma reglamentaria."}]}, {"meanings_summary": {"en": "ball game fan; soccer/basketball enthusiast", "es": "aficionado al fútbol/baloncesto; fanático de la pelota"}, "mnemonics_and_roots": {"composite_memory_hook_en": "One who is utterly fascinated (迷) by the bouncing ball (球) is a true sports fan (球迷).", "composite_memory_hook_es": "Quien se siente cautivado (迷) por el movimiento del balón (球) es un verdadero aficionado (球迷).", "cultural_and_cognitive_roots": "The suffix '迷' denotes avid passion or enthusiasts (歌迷 fan of singing, 影迷 movie buff, 球迷 sports fan).", "tone_sandhi_and_pitch_modulation": "Two rising second tones: 'qiú mí' (35-35). Both rise in pitch with smooth vocal energy."}, "semantic_boundary_contrasts": {"core_nuance": "球迷 specifically designates dedicated fans or followers of ball-related athletic sports.", "contrasts": [{"id": "1", "compared_word": "球迷 vs. 观众", "pinyin": "guānzhòng", "analysis": "观众 refers broadly to any passive audience member watching a show, whereas 球迷 implies emotional attachment to a ball club."}, {"id": "2", "compared_word": "球迷 vs. 粉丝", "pinyin": "fěnsī", "analysis": "粉丝 is a generic modern umbrella term for celebrity/pop fans, while 球迷 is specialized for sporting ball events."}, {"id": "3", "compared_word": "球迷 vs. 队员", "pinyin": "duìyuán", "analysis": "队员 is an active roster athlete playing on the court, while 球迷 supports from the bleachers."}]}, "traps_and_cognates": {"look_alikes": [{"character": "球", "pinyin": "qiú", "meaning_en": "ball; globe", "distinction_note": "Jade radical 王 on left with 求"}, {"character": "救", "pinyin": "jiù", "meaning_en": "rescue; save", "distinction_note": "Has 求 on left with 攵 (tap) on right"}, {"character": "迷", "pinyin": "mí", "meaning_en": "fan; lost", "distinction_note": "Movement radical 辶 at bottom of 米"}, {"character": "谜", "pinyin": "mí", "meaning_en": "riddle; puzzle", "distinction_note": "Speech radical 讠 on left of 迷"}], "etymological_cognates": [{"character": "粉", "pinyin": "fěn", "gloss_en": "powder; fan (slang)"}, {"character": "友", "pinyin": "yǒu", "gloss_en": "friend; companion"}, {"character": "众", "pinyin": "zhòng", "gloss_en": "crowd; spectators"}, {"character": "徒", "pinyin": "tú", "gloss_en": "disciple; follower"}]}, "id": "22", "hanzi": "球迷", "pinyin": "qiú mí", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a passionate enthusiast and supporter of ball sports such as football, basketball, or tennis", "definition_es": "persona apasionada seguidora de deportes de pelota como fútbol o baloncesto", "example_phrase": "狂热的足球迷 (a fanatical soccer fan)"}], "example_sentences": [{"id": "#1", "hanzi": "当主队在补时阶段攻入绝杀进球时，看台上数万名狂热的球迷激动得热泪盈眶并高声欢呼。", "pinyin": "Dāng zhǔduì zài bǔshí jiēduàn gōngrù juéshā jìnqiú shí, kàntái shang shùwàn míng kuángrè de qiúmí jīdòng de rèlèi-yíngkuàng bìng gāoshēng huānhū.", "en": "When the home team netted the buzzer-beating winning goal in stoppage time, tens of thousands of fervent fans on the stands cheered with tears in their eyes.", "es": "Al anotar el equipo local el gol del triunfo en el descuento, decenas de miles de hinchas en las gradas rompieron a llorar de emoción y a vitorear."}, {"id": "#2", "hanzi": "虽然今晚下着滂沱大雨，但依然有许多忠实球迷早早守候在体育馆外等待与球星签名合影。", "pinyin": "Suīrán jīnwǎn xià zhe pángtuó dàyǔ, dàn yīrán yǒu xǔduō zhōngshí qiúmí zǎozǎo shǒuhòu zài tǐyùguǎn wài děngdài yǔ qiúxīng qiānmíng héyǐng.", "en": "Despite pouring rain tonight, many devoted fans waited outside the arena early for autographs and photos with sports stars.", "es": "Pese al diluvio de esta noche, numerosos aficionados leales aguardaron ante el pabellón para conseguir autógrafos de sus ídolos."}], "collocations": [{"hanzi": "忠实球迷", "en": "loyal ball fan"}, {"hanzi": "狂热球迷", "en": "fanatical enthusiast"}, {"hanzi": "资深球迷", "en": "veteran sports fan"}, {"hanzi": "篮球迷", "en": "basketball fan"}, {"hanzi": "足球迷", "en": "soccer fan"}, {"hanzi": "球迷见面会", "en": "fan meet-and-greet event"}], "idioms": [{"hanzi": "如醉如痴", "pinyin": "rú zuì rú chī", "meaning_en": "entranced and infatuated; utterly spellbound"}, {"hanzi": "万人空巷", "pinyin": "wàn rén kōng xiàng", "meaning_en": "the whole town empties out to celebrate an event"}, {"hanzi": "助威呐喊", "pinyin": "zhù wēi nà hǎn", "meaning_en": "shout encouragement and cheer loudly"}, {"hanzi": "热火朝天", "pinyin": "rè huǒ cháo tiān", "meaning_en": "seething with fiery enthusiasm; buzzing activity"}], "character_decomposition": [{"character": "球", "pinyin": "qiú", "meaning_en": "ball; sphere; globe; orb", "meaning_es": "pelota; balón; esfera; globo", "radical": "王", "radical_meaning_en": "jade / king", "meaning_component": "王 (jade stone / precious gem) + 求 (fur coat / curling)", "sound_component": "求 (qiú / phonetic)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Jade radical 王 beside 求; originally a fine round jade sphere, extended to modern sports spheres and balls.", "visual_mnemonic_story_en": "A precious polished jade sphere (王) bouncing smoothly like a ball (球).", "visual_mnemonic_story_es": "Una preciosa piedra de jade pulida en esfera redonda (王) que bota como una pelota (球).", "tone_mnemonic_anchor": "35", "cangjie": "MGIJE", "traditional": "球"}, {"character": "迷", "pinyin": "mí", "meaning_en": "fan; enthusiast; enchant; lost", "meaning_es": "aficionado; cautivado; perderse", "radical": "辶", "radical_meaning_en": "movement", "meaning_component": "辶 (wandering movement) + 米 (dispersed grains)", "sound_component": "米 (mǐ / phonetic association)", "stroke_count": "9", "composition_type": "半包围结构", "etymology_and_mnemonic": "Movement radical 辶 with scattered grain 米; wandering captivated in confusing paths, extended to passionate obsession.", "visual_mnemonic_story_en": "Following scattered trails of rice grains (米) along winding paths (辶) in passionate fascination (迷).", "visual_mnemonic_story_es": "Seguir senderos de granos de arroz (米) absorto en el camino (辶) entregado a la pasión (迷).", "tone_mnemonic_anchor": "35", "cangjie": "YFD", "traditional": "迷"}], "extended_reading_passages": [{"id": "#1", "hanzi": "看台上的球迷是球场上无可争议的第十二人。无论是在球队遭遇连败的至暗低谷，还是在问鼎冠军的荣耀时刻，那面迎风飘扬的俱乐部巨幅旗帜下，始终汇聚着最执着真诚的掌声与最滚烫炽热的呐喊。", "pinyin": "Kàntái shang de qiúmí shì qiúchǎng shang wúkě-zhēngyì de dì-shí'èr rén. Wúlùn shì zài qiúduì zāoyù liánbài de zhì'àn dīgǔ, háishì zài wèndǐng guànjūn de róngyào shíkè, nà miàn yíngfēng piāoyáng de jùlébù jùfú qízhì xià, shǐzhōng huìjù zhe zuì zhízhuó zhēnchéng de zhǎngshēng yǔ zuì gǔntàng chìrè de nàhǎn.", "en": "Fans in the stands are indisputably the team's twelfth player. Whether during dark losing streaks or crowning championship glory, under the massive fluttering club banner gathers the most devoted applause and fiery roar.", "es": "La hinchada en la grada es el jugador número doce. Tanto en las derrotas más dolorosas como al alzar el trofeo, bajo la ondeante pancarta del club resuenan siempre los aplausos más leales y los cánticos más fervorosos."}, {"id": "#2", "hanzi": "早年在春田学院，看台上坐满了年轻球迷。每当有人投篮入筐，大家刚想喝彩，比赛却因慢吞吞搬梯取球而叫停。为了不辜负球迷的观赛热情，工匠毅然用锯子开掉筐底，赋予了篮球运动极其流畅的竞技节奏。", "pinyin": "Zǎonián zài Chūntián xuéyuàn, kàntái shang zuòmǎn le niánqīng qiúmí. Měidāng yǒurén tóulán rù kuāng, dàjiā gāng xiǎng hècǎi, bǐsài què yīn màntūntūn bān tī qǔ qiú ér jiàotíng. Wèile bù gūfù qiúmí de guānsài rèqíng, gōngjiàng yìrán yòng jùzi kāi diào kuāngdǐ, fùyǔ le lánqiú yùndòng jíqí liúchàng de jìngjì jiézòu.", "en": "At Springfield College, stands were filled with young fans. Whenever a basket was scored, play was halted while ladders were dragged out. To satisfy fan passion, craftsmen sawed off the bottoms, gifting basketball a delightfully fluid rhythm.", "es": "En Springfield, las gradas rebosaban de jóvenes hinchas. Al encestar, el juego paraba para traer la escalera. Para no defraudar a la afición, los conserjes serraron el fondo, dotando al baloncesto de un ritmo trepidante."}]}, {"meanings_summary": {"en": "engineer (professional technical designer)", "es": "ingeniero; técnica/o superior"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A master (师) who applies technical standards (程) to construction works (工) is a qualified engineer (工程师).", "composite_memory_hook_es": "Un perito acreditado (师) que aplica procesos metódicos (程) a las obras (工) es un ingeniero (工程师).", "cultural_and_cognitive_roots": "Title combining modern technical methodology with historical reverence for masters of craft (师徒制).", "tone_sandhi_and_pitch_modulation": "Three syllables: 'gōng chéng shī' (55-35-55). High level tone on 'gōng', rising on 'chéng', and sustaining high on 'shī'."}, "semantic_boundary_contrasts": {"core_nuance": "工程师 denotes an educated professional applying science and mathematics to practical design and systems.", "contrasts": [{"id": "1", "compared_word": "工程师 vs. 工人", "pinyin": "gōngrén", "analysis": "工人 denotes manual labor execution on the production line, while 工程师 formulates blueprints, software architectures, and mathematical designs."}, {"id": "2", "compared_word": "工程师 vs. 科学家", "pinyin": "kēxuéjiā", "analysis": "科学家 pursues pure theoretical truth and discovery, whereas 工程师 translates those scientific discoveries into functional commercial products."}, {"id": "3", "compared_word": "工程师 vs. 技师", "pinyin": "jìshī", "analysis": "技师 focuses on practical operational maintenance and machine adjustment, while 工程师 oversees systemic system design."}]}, "traps_and_cognates": {"look_alikes": [{"character": "程", "pinyin": "chéng", "meaning_en": "order; journey", "distinction_note": "Grain radical 禾 on left with 呈"}, {"character": "呈", "pinyin": "chéng", "meaning_en": "present; display", "distinction_note": "Without the grain radical on left"}, {"character": "师", "pinyin": "shī", "meaning_en": "master; teacher", "distinction_note": "Has 刂-like vertical and 巾"}, {"character": "帅", "pinyin": "shuài", "meaning_en": "commander; handsome", "distinction_note": "Has a top stroke  丿 on left"}], "etymological_cognates": [{"character": "工", "pinyin": "gōng", "gloss_en": "worker; artisan"}, {"character": "匠", "pinyin": "jiàng", "gloss_en": "craftsman; artisan"}, {"character": "家", "pinyin": "jiā", "gloss_en": "specialist; expert"}, {"character": "员", "pinyin": "yuán", "gloss_en": "member; personnel"}]}, "id": "23", "hanzi": "工程师", "pinyin": "gōng chéng shī", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person trained in the design, construction, and use of engines, machines, software, or structures", "definition_es": "profesional cualificado que aplica principios científicos para diseñar, construir y operar obras, máquinas o programas", "example_phrase": "资深软件架构工程师 (senior software architect engineer)"}], "example_sentences": [{"id": "#1", "hanzi": "桥梁工程师和施工人员在悬崖深谷间连续奋战了数月，终于成功合龙了这座特大悬索桥。", "pinyin": "Qiáoliáng gōngchéngshī hé shīgōng rényuán zài xuányá shēngǔ jiān liánxù fènzhàn le shù yuè, zhōngyú chénggōng hélóng le zhè zuò tìdà xuánsuǒqiáo.", "en": "Bridge engineers and construction workers fought for months across the deep cliffside chasm, finally joining the spans of this mega suspension bridge.", "es": "Los ingenieros de puentes y operarios bregaron durante meses en el desfiladero hasta completar el ensamblaje final del monumental puente colgante."}, {"id": "#2", "hanzi": "优秀的航空工程师在设计客机外壳时，对每一个部件的气动阻力都进行了极为精密严苛的模拟风洞计算。", "pinyin": "Yōuxiù de hángkōng gōngchéngshī zài shèjì kèjī wàiké shí, duì měi yí ge bùjiàn de qìdòng zǔlì dōu jìnxíng le jíwéi jīngmì yánkē de mónǐ fēngdòng jìsuàn.", "en": "Distinguished aeronautical engineers perform rigorous wind-tunnel simulations on the aerodynamic drag of every component when designing passenger planes.", "es": "Los ingenieros aeronáuticos realizan rigurosos cálculos aerodinámicos en túneles de viento para optimizar cada pieza del fuselaje."}], "collocations": [{"hanzi": "总工程师", "en": "chief engineer"}, {"hanzi": "软件工程师", "en": "software engineer"}, {"hanzi": "建筑工程师", "en": "civil / structural engineer"}, {"hanzi": "机械工程师", "en": "mechanical engineer"}, {"hanzi": "助理工程师", "en": "assistant engineer"}, {"hanzi": "高级工程师", "en": "senior engineer"}], "idioms": [{"hanzi": "匠心独运", "pinyin": "jiàng xīn dú yùn", "meaning_en": "displaying wonderful ingenuity; singular craftsmanship"}, {"hanzi": "精雕细刻", "pinyin": "jīng diāo xì kè", "meaning_en": "carve with fine precision; meticulous craftsmanship"}, {"hanzi": "开山架桥", "pinyin": "kāi shān jià qiáo", "meaning_en": "level mountains and build bridges; clear obstacles boldly"}, {"hanzi": "革故鼎新", "pinyin": "gé gù dǐng xīn", "meaning_en": "overthrow the old and usher in the new; innovate boldly"}], "character_decomposition": [{"character": "工", "pinyin": "gōng", "meaning_en": "work; craft; engineering", "meaning_es": "obra; técnica; ingeniería", "radical": "工", "radical_meaning_en": "work / craft", "meaning_component": "carpenter's plumb square", "sound_component": "工 (gōng)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "A carpenter's square tool; represents engineering, craftsmanship, and structured construction.", "visual_mnemonic_story_en": "A carpenter's level square (工) measuring structural angles for precision craft.", "visual_mnemonic_story_es": "Una escuadra de carpintero (工) guiando trazos precisos en la construcción.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": "工"}, {"character": "程", "pinyin": "chéng", "meaning_en": "order; rule; measure; journey", "meaning_es": "proceso; medida; trayecto", "radical": "禾", "radical_meaning_en": "grain", "meaning_component": "禾 (grain measurement) + 呈 (display / present)", "sound_component": "呈 (chéng / phonetic)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Grain radical 禾 beside 呈; weighing grain standards to establish official measurement rules and systematic workflows.", "visual_mnemonic_story_en": "Weighing stalks of golden grain (禾) on an official presentation tray (呈) to establish orderly standards (程).", "visual_mnemonic_story_es": "Pesar espigas de cereal (禾) en una balanza oficial (呈) fijando normas metódicas (程).", "tone_mnemonic_anchor": "35", "cangjie": "HDRHG", "traditional": "程"}, {"character": "师", "pinyin": "shī", "meaning_en": "master; teacher; expert; army", "meaning_es": "maestro; perito; experto", "radical": "巾", "radical_meaning_en": "cloth / towel", "meaning_component": "帀 (circling troops banner) + 巾 (standard cloth)", "sound_component": "师 (shī)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A commander holding military banners before troops; evolved into revered masters, mentors, and certified professionals.", "visual_mnemonic_story_en": "A revered master raising the banner of knowledge (巾) to instruct apprentices (师).", "visual_mnemonic_story_es": "Un maestro que alza el estandarte de la pericia (巾) guiando a sus discípulos (师).", "tone_mnemonic_anchor": "55", "cangjie": "HLMLB", "traditional": "師"}], "extended_reading_passages": [{"id": "#1", "hanzi": "航天工程师团队在深空探测领域攻坚克难。他们凭借务实的科学作风与精益求精的工匠情怀，将探测器精准送达预定轨道，让飞天梦想在浩瀚星空中璀璨绽放。", "pinyin": "Hángtiān gōngchéngshī tuánduì zài shēnkōng tàncè lǐngyù gōngjiān-kènán. Tāmen píngjiè wùshí de kēxué zuòfēng yǔ jīngyìqiújīng de gōngjiàng qínghuái, jiāng tàncèqì jīngzhǔn sòngdá yùdìng guǐdào, ràng fēitiān mèngxiǎng zài hàohàn xīngkōng zhōng cuǐcàn zhànfàng.", "en": "Aerospace engineers have overcome challenges in deep space exploration. With scientific pragmatism and meticulous craftsmanship, they delivered orbiters onto precision paths, realizing ancient dreams.", "es": "Los ingenieros aeroespaciales superaron grandes hitos espaciales. Con rigor pragmático y esmero artesanal, situaron las sondas en órbita con precisión, materializando el sueño de surcar el cosmos."}, {"id": "#2", "hanzi": "面对取球难题，工程师起初设计了复杂的滑轮装置试图倾倒皮球。然而实践证明，精密图纸反倒不如一把普通锯子直截了当。顶尖的工程智慧，恰恰体现在大道至简之中。", "pinyin": "Miànduì qǔ qiú nántí, gōngchéngshī qǐchū shèjì le fùzá de huálún zhuāngzhì shìtú qīngdào píqiú. Rán'ér shíjiàn zhèngmíng, jīngmì túzhǐ fǎndào bùrú yì bǎ pǔtōng jùzi zhíjié-liǎodàng. Dǐngjiān de gōngchéng zhìhuì, qiàqià tǐxiàn zài dàdào-zhìjiǎn zhīzhōng.", "en": "Faced with extracting balls, engineers initially devised complex pulleys to tilt baskets. Yet practice proved intricate designs inferior to an ordinary saw. Supreme engineering brilliance lies in radical simplicity.", "es": "Para vaciar las canastas, los ingenieros idearon poleas complejas. Mas la práctica demostró que una modesta sierra superaba a planos sofisticados. La verdadera maestría técnica reside en la sencillez."}]}, {"meanings_summary": {"en": "machine; apparatus; mechanical device", "es": "máquina; aparato; ingenio mecánico"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Mechanical moving mechanisms (机) combined with manufactured instruments (器) constitute a machine (机器).", "composite_memory_hook_es": "Los mecanismos móviles (机) ensamblados en un aparato funcional (器) componen una máquina (机器).", "cultural_and_cognitive_roots": "Crossbow triggers (弩机) and silk weaving looms (织机) served as ancient China's prototypical automated machines.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling fourth tone: 'jī qì' (55-51). Hold 'jī' at a clear high register, then drop sharply on 'qì'."}, "semantic_boundary_contrasts": {"core_nuance": "机器 denotes power-driven mechanisms with coordinated moving parts executing work.", "contrasts": [{"id": "1", "compared_word": "机器 vs. 工具", "pinyin": "gōngjù", "analysis": "工具 denotes simple handheld manual implements (hammer, saw), while 机器 involves powered kinetic mechanisms."}, {"id": "2", "compared_word": "机器 vs. 设备", "pinyin": "shèbèi", "analysis": "设备 encompasses installations, factory plant rooms, and complete setups, whereas 机器 is a specific motorized apparatus."}, {"id": "3", "compared_word": "机器 vs. 仪器", "pinyin": "yíqì", "analysis": "仪器 is calibrated for analytical scientific testing and measurement, while 机器 performs mechanical power work."}]}, "traps_and_cognates": {"look_alikes": [{"character": "机", "pinyin": "jī", "meaning_en": "machine; engine", "distinction_note": "Wood radical 木 on left with 几"}, {"character": "几", "pinyin": "jǐ/jī", "meaning_en": "how many; small table", "distinction_note": "Without the wood radical"}, {"character": "器", "pinyin": "qì", "meaning_en": "utensil; machine", "distinction_note": "Has four 口 around 犬 in center"}, {"character": "哭", "pinyin": "kū", "meaning_en": "weep; cry", "distinction_note": "Has only two 口 on top over 犬"}], "etymological_cognates": [{"character": "械", "pinyin": "xiè", "gloss_en": "machinery; implement"}, {"character": "具", "pinyin": "jù", "gloss_en": "tool; equipment"}, {"character": "设", "pinyin": "shè", "gloss_en": "install; devise"}, {"character": "备", "pinyin": "bèi", "gloss_en": "prepare; equipment"}]}, "id": "24", "hanzi": "机器", "pinyin": "jī qì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an apparatus using mechanical power and having several parts, each with a definite function and together performing a particular task", "definition_es": "conjunto de piezas acopladas que transforma energía para realizar un trabajo mecánico o productivo", "example_phrase": "运转正常的生产机器 (smoothly operating production machines)"}], "example_sentences": [{"id": "#1", "hanzi": "全自动数控车间里的数十台精密机器高速运转，有条不紊地加工着微型芯片组件。", "pinyin": "Quán zìdòng shùkòng chējiān lǐ de shùshí tái jīngmì jīqì gāosù yùnzhuǎn, yǒutiáo-bùwěn de jiāgōng zhe wēixíng xīnpìan zǔjiàn.", "en": "Dozens of high-precision machines in the automated CNC workshop ran at high speed, processing miniature microchip components with meticulous order.", "es": "En la nave de mecanizado automatizado, decenas de máquinas de precisión giraban a gran velocidad procesando microcomponentes con orden perfecto."}, {"id": "#2", "hanzi": "人类发明机器的初衷是为了把双手从繁重危险的体力劳动中解放出来，从而追求更有创造力的精神生活。", "pinyin": "Rénlèi fāmíng jīqì de chūzhōng shì wèile bǎ shuāngshǒu cóng fánzhòng wēixiǎn de tǐlì láodòng zhōng jiěfàng chūlái, cóng'ér zhuīqiú gèng yǒu chuàngzàolì de jīngshén shēnghuó.", "en": "Humanity's initial purpose in inventing machines was to liberate hands from grueling, hazardous physical toil, thus enabling more creative pursuits.", "es": "La humanidad inventó las máquinas para liberar sus manos del trabajo físico penoso y peligroso, abriendo cauce a una vida intelectual más fecunda."}], "collocations": [{"hanzi": "运转机器", "en": "operate / run a machine"}, {"hanzi": "机器故障", "en": "machine breakdown / malfunction"}, {"hanzi": "维修机器", "en": "repair machinery"}, {"hanzi": "精密机器", "en": "precision machine"}, {"hanzi": "机器人", "en": "robot"}, {"hanzi": "机器制造", "en": "machine manufacturing"}], "idioms": [{"hanzi": "神工鬼斧", "pinyin": "shén gōng guǐ fǔ", "meaning_en": "superhuman craft and divine axes; miraculous craftsmanship"}, {"hanzi": "脱胎换骨", "pinyin": "tuō tāi huàn gǔ", "meaning_en": "shed old body and bone; thorough transformation"}, {"hanzi": "一日千里", "pinyin": "yī rì qiān lǐ", "meaning_en": "advance a thousand miles a day; meteoric progress"}, {"hanzi": "生机勃勃", "pinyin": "shēng jī bó bó", "meaning_en": "full of vibrant vigor and surging vitality"}], "character_decomposition": [{"character": "机", "pinyin": "jī", "meaning_en": "machine; mechanism; opportunity", "meaning_es": "máquina; mecanismo; ocasión", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (wooden loom / frame) + 几 (small stool; phonetic)", "sound_component": "几 (jī / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Tree radical 木 beside 几; originally the wooden trigger mechanism of a crossbow or a weaving loom.", "visual_mnemonic_story_en": "A wooden loom frame (木) resting by a small stool (几), forming a weaving mechanism (机).", "visual_mnemonic_story_es": "El bastidor de madera de un telar (木) junto a un banquito (几), formando un mecanismo tejedor (机).", "tone_mnemonic_anchor": "55", "cangjie": "DHN", "traditional": "機"}, {"character": "器", "pinyin": "qì", "meaning_en": "vessel; utensil; organ; instrument", "meaning_es": "recipiente; utensilio; aparato", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "four 口 (four vessels/dishes) surrounding 犬 (watchdog)", "sound_component": "器 (qì)", "stroke_count": "16", "composition_type": "上中下结构", "etymology_and_mnemonic": "Four mouth radicals 口 representing diverse vessels guarded by a dog 犬; broad category of utensils, gear, and manufactured devices.", "visual_mnemonic_story_en": "Four valuable bronze vessels (口) guarded vigilantly by a faithful dog (犬) in the treasure hall (器).", "visual_mnemonic_story_es": "Cuatro valiosas vasijas ceremoniales (口) guardadas con celo por un perro (犬) en la sala (器).", "tone_mnemonic_anchor": "51", "cangjie": "RROIK", "traditional": "器"}], "extended_reading_passages": [{"id": "#1", "hanzi": "工业革命以蒸汽机器的应用为标志，重塑了社会生产形态。手工纺织被现代化工厂取代，轰鸣的机器不仅释放了生产力，更开启了波澜壮阔的城市化历史进程。", "pinyin": "Gōngyè gémìng yǐ zhēngqì jīqì de yìngyòng wéi biāozhì, chóngsù le shèhuì shēngchǎn xíngtài. Shǒugōng fǎngzhī bèi xiàndàihuà gōngchǎng qǔdài, hōngmíng de jīqì bùjǐn shìfàng le shēngchǎnlì, gèng kāiqǐ le bōlán-zhuàngkuò de chéngshìhuà lìshǐ jìnchéng.", "en": "The Industrial Revolution, marked by steam machines, reshaped production. Modern factories replaced manual mills; roaring machinery unchained productivity and launched rapid urbanization.", "es": "La Revolución Industrial, impulsada por la máquina de vapor, transformó la producción. Fábricas mecanizadas relevaron a telares; las máquinas desataron la productividad e impulsaron la urbanización."}, {"id": "#2", "hanzi": "当年发明篮球时，学校没有任何现代化制造机器。面对每次投球后的繁琐取球障碍，人们没有耗费巨资研制复杂的取球机器，而是用一把普通锯子就轻而易举化解了难题。", "pinyin": "Dāngnián fāmíng lánqiú shí, xuéxiào méiyǒu rènhé xiàndàihuà zhìzào jīqì. Miànduì měicì tóu qiú hòu de fánsuǒ qǔ qiú zhàng'ài, rénmen méiyǒu hàofèi jùzī yánzhì fùzá de qǔ qiú jīqì, érshì yòng yì bǎ pǔtōng jùzi jiù qīng'éryǐjǔ huàjiě le nántí.", "en": "When basketball was invented, the school had no modern machinery. Faced with tedious ball extraction, rather than building complex automated machines, they solved it effortlessly with an ordinary saw.", "es": "Al crearse el baloncesto, la escuela no poseía maquinaria avanzada. Ante el tedio de recuperar balones, en vez de costosas máquinas automáticas, bastó una sencilla sierra para solventar el dilema."}]}, {"meanings_summary": {"en": "smooth; unhindered; fluent; unimpeded", "es": "fluido; despejado; expedito; sin trabas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Following smooth river currents (顺) to unhindered outward expansion (畅) describes an unblocked flow (顺畅).", "composite_memory_hook_es": "Navegar con la corriente favorable (顺) hacia una expansión libre de trabas (畅) es discurrir con fluidez (顺畅).", "cultural_and_cognitive_roots": "Derived from Daoist natural river metaphors where non-resistance (顺水推舟) yields maximum unobstructed grace.", "tone_sandhi_and_pitch_modulation": "Two falling fourth tones: 'shùn chàng' (51-51). Deliver both syllables with clear downward momentum and confidence."}, "semantic_boundary_contrasts": {"core_nuance": "顺畅 emphasizes the unimpeded, friction-free movement of fluids, traffic, air, or processes.", "contrasts": [{"id": "1", "compared_word": "顺畅 vs. 流畅", "pinyin": "liúchàng", "analysis": "流畅 focuses on graceful stylistic elegance in speech, prose, or dance (文笔流畅), while 顺畅 focuses on lack of physical blockages (交通顺畅, 呼吸顺畅)."}, {"id": "2", "compared_word": "顺畅 vs. 顺利", "pinyin": "shùnlì", "analysis": "顺利 denotes the favorable outcome of undertakings without mishap (工作顺利), whereas 顺畅 depicts kinetic passage."}, {"id": "3", "compared_word": "顺畅 vs. 舒畅", "pinyin": "shūchàng", "analysis": "舒畅 exclusively describes internal subjective emotional ease and relief (心情舒畅), not physical traffic."}]}, "traps_and_cognates": {"look_alikes": [{"character": "顺", "pinyin": "shùn", "meaning_en": "smooth; along", "distinction_note": "River 川 on left with 页 on right"}, {"character": "须", "pinyin": "xū", "meaning_en": "must; beard", "distinction_note": "Has 彡 (three strokes) on left with 页"}, {"character": "畅", "pinyin": "chàng", "meaning_en": "fluent; unimpeded", "distinction_note": "Has 申 on left with 𠮛 on right"}, {"character": "扬", "pinyin": "yáng", "meaning_en": "raise; scatter", "distinction_note": "Hand radical 扌 on left of 𠮛"}], "etymological_cognates": [{"character": "通", "pinyin": "tōng", "gloss_en": "pass through; clear"}, {"character": "流", "pinyin": "liú", "gloss_en": "flow; drift"}, {"character": "利", "pinyin": "lì", "gloss_en": "sharp; advantageous"}, {"character": "滑", "pinyin": "huá", "gloss_en": "slippery; smooth"}]}, "id": "25", "hanzi": "顺畅", "pinyin": "shùn chàng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "flowing smoothly and continuously without obstruction or friction", "definition_es": "que fluye con facilidad y continuidad sin tropiezos, trabas ni interrupciones", "example_phrase": "道路交通十分顺畅 (road traffic is completely unimpeded and smooth)"}], "example_sentences": [{"id": "#1", "hanzi": "经过城市交管部门对早高峰路段的科学分流与信号灯智能优化，主干道交通变得非常顺畅。", "pinyin": "Jīngguò chéngshì jiāoguǎn bùmén duì zǎogāofēng lùduàn de kēxué fēnliú yǔ xìnhàodēng zhìnéng yōuhuà, zhǔgàndào jiāotōng biàn de fēicháng shùnchàng.", "en": "Through traffic authorities' diversion planning and intelligent light tuning during the morning rush hour, main thoroughfare traffic became exceedingly smooth.", "es": "Tras el desvío coordinado del tráfico y la sincronización semafórica en la hora punta, la circulación en la avenida principal discurrió con total fluidez."}, {"id": "#2", "hanzi": "只有建立高效顺畅的跨部门沟通机制，企业才能在瞬息万变的市场竞争中快速响应客户需求。", "pinyin": "Zhǐyǒu jiànlì gāoxiào shùnchàng de kuà-bùmén gōutōng jīzhì, qǐyè cái néng zài shùnxī-wànbiàn de shìchǎng jìngzhēng zhōng kuàisù xiǎngyìng kèhù xūqiú.", "en": "Only by establishing an efficient and unhindered cross-departmental communication channel can an enterprise rapidly respond to clients amid volatile market competition.", "es": "Sólo forjando una comunicación interdepartamental ágil y fluida podrá la corporación responder con celeridad a las demandas del cambiante mercado."}], "collocations": [{"hanzi": "交通顺畅", "en": "smooth, unhindered traffic"}, {"hanzi": "呼吸顺畅", "en": "unobstructed, smooth breathing"}, {"hanzi": "沟通顺畅", "en": "unimpeded communication"}, {"hanzi": "流程顺畅", "en": "smooth workflow"}, {"hanzi": "表达顺畅", "en": "fluent, smooth expression"}, {"hanzi": "心情顺畅", "en": "cheerful, buoyant mood"}], "idioms": [{"hanzi": "畅通无阻", "pinyin": "chàng tōng wú zǔ", "meaning_en": "unimpeded and clear; completely unblocked"}, {"hanzi": "一帆风顺", "pinyin": "yī fān fēng shùn", "meaning_en": "smooth sailing all the way; plain sailing"}, {"hanzi": "通达明辨", "pinyin": "tōng dá míng biàn", "meaning_en": "perceptive and articulate; clear-minded"}, {"hanzi": "水到渠成", "pinyin": "shuǐ dào qú chéng", "meaning_en": "when water arrives the canal forms; natural spontaneous success"}], "character_decomposition": [{"character": "顺", "pinyin": "shùn", "meaning_en": "along with; obedient; smooth", "meaning_es": "seguir; propicio; favorable", "radical": "川", "radical_meaning_en": "river", "meaning_component": "川 (smooth flowing river current) + 页 (head/face)", "sound_component": "川 (chuān / phonetic association)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Flowing river streams 川 beside head 页; tilting the head to align with natural river currents, symbolizing going with the flow.", "visual_mnemonic_story_en": "Turning one's head (页) to drift along the smooth river current (川) without fighting upstream (顺).", "visual_mnemonic_story_es": "Alinear la mirada (页) a favor de la corriente del río (川) dejándose llevar con fluidez (顺).", "tone_mnemonic_anchor": "51", "cangjie": "LLMBO", "traditional": "順"}, {"character": "畅", "pinyin": "chàng", "meaning_en": "smooth; unimpeded; free; joyful", "meaning_es": "expedito; desahogado; contento", "radical": "申", "radical_meaning_en": "extend", "meaning_component": "申 (stretch / extend freely) + 𠮛 (sunshine / vital energy)", "sound_component": "𠮛 (yáng / bright expansion)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Expanding 申 under open sky; an unhindered opening through which life energy, fluids, or thoughts flow completely free.", "visual_mnemonic_story_en": "Life energy extending outward (申) under the sun without meeting any roadblocks (畅).", "visual_mnemonic_story_es": "La energía vital expandiéndose (申) libremente a cielo abierto sin ningún obstáculo (畅).", "tone_mnemonic_anchor": "51", "cangjie": "LNSH", "traditional": "暢"}], "extended_reading_passages": [{"id": "#1", "hanzi": "晨雾散去后的滨海大道上，微咸的海风拂面而来。极目远眺，宽阔整洁的八车道路面上车流平稳有序、行进顺畅，两侧葱茏挺拔的椰子树在阳光下舒展枝叶，勾勒出一幅舒缓惬意的现代海滨都市生态画卷。", "pinyin": "Chénwù sànqù hòu de bīnhǎi dàdào shang, wēixián de hǎifēng fúmiàn ér lái. Jímù yuǎntiào, kuānkuò zhěngjié de bā chēdào lùmiàn shang chēliú píngwěn yǒuxù, xíngjìn shùnchàng, liǎngcè cōnglóng tǐngbá de yēzǐshù zài yángguāng xià shūzhǎn zhīyè, gōulè chū yì fú shūhuǎn qièyì de xiàndài hǎibīn dūshì shēngtài huàjuàn.", "en": "On the coastal boulevard after morning mists lifted, salty sea breezes caressed travelers. Eight lanes of traffic moved with smooth order while verdant coconut palms stretched in the sun, forming a restful coastal city panorama.", "es": "Disipada la niebla matinal en el paseo marítimo, la brisa marina rozaba el rostro. En la ancha calzada de ocho carriles, el tráfico fluía con suave compás mientras los cocoteros mecían sus palmas bajo el sol."}, {"id": "#2", "hanzi": "当年篮球比赛之所以常常被球迷抱怨节奏拖沓，根源就在于缺乏顺畅的进球反馈机制。每次投篮得分都意味着一次人为的强制暂停，直到有人把竹筐底锯掉后，篮球才能在穿筐而过的刹那直接坠落回地面，比赛流程自此变得无比顺畅欢快。", "pinyin": "Dāngnián lánqiú bǐsài zhī suǒyǐ chángcháng bèi qiúmí bàoyuàn jiézòu tuōtà, gēnyuán jiù zàiyú quēfá shùnchàng de jìnqiú fǎnhuì jīzhì. Měicì tóulán défēn dōu yìwèizhe yí cì rénwéi de qiángzhì zàntíng, zhídào yǒurén bǎ zhúkuāng dǐ jù diào hòu, lánqiú cái néng zài chuān kuāng ér guò de chànà zhíjiē zhuìluò huí dìmbiàn, bǐsài liúchéng zìcǐ biàn de wúbǐ shùnchàng huānkuài.", "en": "Fans complained early basketball was sluggish because it lacked an unimpeded scoring cycle. Every basket forced a manual pause. Only when someone sawed open the bottom could the ball plunge directly to the court, transforming the entire game into an exhilarating, flowing delight.", "es": "Los hinchas criticaban la lentitud del baloncesto pionero por carecer de un ciclo fluido tras el enceste. Cada punto obligaba a parar el juego. Al serrar el fondo de la cesta, el balón cayó libremente al suelo, tornando el deporte en una fiesta ágil y continua."}]}, {"meanings_summary": {"en": "kindergarten; preschool; nursery school", "es": "jardín de infancia; guardería; parvulario"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A protective garden enclosure (园) nurturing tender young (幼) children (儿) is a kindergarten (幼儿园).", "composite_memory_hook_es": "Un jardín acogedor (园) que cobija y educa a niños (儿) de tierna edad (幼) es un parvulario (幼儿园).", "cultural_and_cognitive_roots": "Direct conceptual loan from Froebel's German 'Kindergarten' (children's garden), entered Chinese via late Qing reforms.", "tone_sandhi_and_pitch_modulation": "Three syllables: 'yòu 'ér yuán' (51-35-35). Falling fourth tone on 'yòu', followed by two rising second tones on ''ér' and 'yuán'."}, "semantic_boundary_contrasts": {"core_nuance": "幼儿园 specifically denotes the pre-primary educational institution for children ages 3 to 6.", "contrasts": [{"id": "1", "compared_word": "幼儿园 vs. 托儿所", "pinyin": "tuō'érsuǒ", "analysis": "托儿所 (daycare / creche) accommodates infants and toddlers from birth to 3 years old primarily for care, while 幼儿园 provides structured pre-K education."}, {"id": "2", "compared_word": "幼儿园 vs. 小学", "pinyin": "xiǎoxué", "analysis": "小学 (elementary school) enters compulsory grade curricula for ages 6 to 12, unlike playtime-based 幼儿园."}, {"id": "3", "compared_word": "幼儿园 vs. 早教中心", "pinyin": "zǎojiào zhōngxīn", "analysis": "早教中心 provides specialized hourly parent-child developmental sessions, whereas 幼儿园 offers full-day pre-schooling."}]}, "traps_and_cognates": {"look_alikes": [{"character": "幼", "pinyin": "yòu", "meaning_en": "young; tender", "distinction_note": "Has 幺 on left and 力 on right"}, {"character": "幻", "pinyin": "huàn", "meaning_en": "fantasy; illusion", "distinction_note": "Has 幺 on left and 弓-like stroke on right"}, {"character": "园", "pinyin": "yuán", "meaning_en": "garden", "distinction_note": "Enclosed 囗 with 元 inside"}, {"character": "圆", "pinyin": "yuán", "meaning_en": "round; circle", "distinction_note": "Enclosed 囗 with 员 inside"}], "etymological_cognates": [{"character": "托", "pinyin": "tuō", "gloss_en": "nursery; trust; support"}, {"character": "童", "pinyin": "tóng", "gloss_en": "child; youthful"}, {"character": "雏", "pinyin": "chú", "gloss_en": "chick; fledgling"}, {"character": "苑", "pinyin": "yuàn", "gloss_en": "park; academic enclave"}]}, "id": "26", "hanzi": "幼儿园", "pinyin": "yòu 'ér yuán", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an educational establishment or day-care facility for children below the age of compulsory schooling (typically ages 3 to 6)", "definition_es": "institución educativa para niños de tres a seis años previa a la enseñanza primaria", "example_phrase": "把孩子送到附近的公立幼儿园 (send the child to a nearby public kindergarten)"}], "example_sentences": [{"id": "#1", "hanzi": "每天清晨，这所国际双语幼儿园的塑胶操场上都会响起欢快活泼的儿歌和孩子们银铃般的笑声。", "pinyin": "Měitiān qīngchén, zhè suǒ guójì shuāngyǔ yòu'éryuán de sùjiāo cāochǎng shang dōu huì xiǎngqǐ huānkuài huópō de érgē hé háizimen yínlíng bān de xiàoshēng.", "en": "Every dawn, cheerful nursery rhymes and silvery children's laughter resonate across the synthetic playground of this international bilingual kindergarten.", "es": "Cada mañana, alegres rondas infantiles y risas cantadinas resuenan en el patio de juegos acolchado del jardín de infancia bilingüe."}, {"id": "#2", "hanzi": "学前教育专家强调，幼儿园课程应当以启发好奇心和培养基本生活习惯为主，切不可过早超纲灌输应试知识。", "pinyin": "Xuéqián jiàoyù zhuānjiā qiángdiào, yòu'éryuán kèchéng yīngdāng yǐ qǐfā hàoqíxīn hé péiyǎng jīběn shēnghuó xíguàn wéi zhǔ, qiè bùkě guòzǎo chāogāng guànshū yìngshì zhīshi.", "en": "Early childhood education experts emphasize that kindergarten curricula should focus on inspiring curiosity and nurturing life habits, avoiding cramming academic tests.", "es": "Expertos en educación preescolar subrayan que el parvulario debe priorizar la curiosidad e higiene personal, evitando sobrecargar al niño con lecciones académicas."}], "collocations": [{"hanzi": "上幼儿园", "en": "attend kindergarten"}, {"hanzi": "公立幼儿园", "en": "public kindergarten"}, {"hanzi": "私立幼儿园", "en": "private preschool / kindergarten"}, {"hanzi": "幼儿园老师", "en": "kindergarten teacher"}, {"hanzi": "幼儿园小朋友", "en": "kindergarten pupils"}, {"hanzi": "双语幼儿园", "en": "bilingual nursery school"}], "idioms": [{"hanzi": "欢声笑语", "pinyin": "huān shēng xiào yǔ", "meaning_en": "cheers and laughter; joyful atmosphere"}, {"hanzi": "天真烂漫", "pinyin": "tiān zhēn làn màn", "meaning_en": "innocent, artless, and delightful like children"}, {"hanzi": "童心未泯", "pinyin": "tóng xīn wèi mǐn", "meaning_en": "retaining child-like innocence into adulthood"}, {"hanzi": "循循善诱", "pinyin": "xún xún shàn yòu", "meaning_en": "guide systematically and patiently with gentle teaching"}], "character_decomposition": [{"character": "幼", "pinyin": "yòu", "meaning_en": "young; tender; infant", "meaning_es": "joven; tierno; párvulo", "radical": "幺", "radical_meaning_en": "tiny / small", "meaning_component": "幺 (tiny filament) + 力 (infant physical strength)", "sound_component": "幼 (yòu)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Tiny 幺 beside strength 力; having only minute infant physical power, denoting tender young age.", "visual_mnemonic_story_en": "A tiny infant (幺) attempting to exert its little arm strength (力) as it learns to walk (幼).", "visual_mnemonic_story_es": "Un tierno bebé (幺) tratando de usar su escasa fuerza (力) al dar sus primeros pasos (幼).", "tone_mnemonic_anchor": "51", "cangjie": "VIKS", "traditional": "幼"}, {"character": "儿", "pinyin": "ér", "meaning_en": "child; son; young person", "meaning_es": "niño; hijo; joven", "radical": "儿", "radical_meaning_en": "legs / person", "meaning_component": "pictograph of an infant with soft unclosed skull fontanelle and little legs", "sound_component": "儿 (ér)", "stroke_count": "2", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph of an infant walking on two little legs, head fontanelle still soft.", "visual_mnemonic_story_en": "Two small legs (儿) toddling happily forward, the sweet sign of a growing child.", "visual_mnemonic_story_es": "Dos piernecitas (儿) correteando contentas, la viva imagen de un párvulo.", "tone_mnemonic_anchor": "35", "cangjie": "HU", "traditional": "兒"}, {"character": "园", "pinyin": "yuán", "meaning_en": "garden; park; enclosed ground", "meaning_es": "jardín; huerto; parque", "radical": "囗", "radical_meaning_en": "enclosure", "meaning_component": "囗 (surrounding walled perimeter) + 元 (spacious first origin)", "sound_component": "元 (yuán / phonetic)", "stroke_count": "7", "composition_type": "全包围结构", "etymology_and_mnemonic": "Enclosure 囗 surrounding 元; an enclosed garden plot for cultivating flowers, crops, or nurturing youngsters.", "visual_mnemonic_story_en": "A fenced protective courtyard (囗) where fruitful seeds take root and grow (元): a peaceful garden (园).", "visual_mnemonic_story_es": "Un recinto cerrado protector (囗) donde florecen brotes jóvenes (元): un bello jardín (园).", "tone_mnemonic_anchor": "35", "cangjie": "WMMU", "traditional": "園"}], "extended_reading_passages": [{"id": "#1", "hanzi": "温暖的午后阳光透过树梢洒落在幼儿园的花园草坪上。老师正带着一群扎着羊角辫的孩子们围坐成圆圈做趣味游戏。孩子们清脆纯真的笑声在微风中飘荡，那一双双澄澈无暇的大眼睛里，闪烁着对整个世界最初的奇妙向往。", "pinyin": "Wēnnuǎn de wǔhòu yángguāng tòuguò shùshāo sǎluò zài yòu'éryuán de huāyuán cǎopíng shang. Lǎoshī zhèng dài zhe yì qún zā zhe yángjiǎobiàn de háizimen wéizuò chéng yuánquān zuò qùwèi yóuxì. Háizimen qīngcuì chúnzhēn de xiàoshēng zài wēifēng zhōng piāodàng, nà yì shuāngshuāng chéngchè-wúxiá de dà yǎnjing lǐ, shǎnshuò zhe duì zhěnggè shìjiè zuìchū de qímiào xiàngwǎng.", "en": "Warm afternoon sunlight filtered through leaves onto the kindergarten lawn. The teacher gathered children in a circle for playful games. Pure laughter floated on the breeze; within their clear innocent eyes sparkled their very first wonders about the world.", "es": "El sol de la tarde bañaba el césped del jardín de infancia. La maestra jugaba en corro con los pequeños, cuyas risas cristalinas mecía la brisa. En sus ojos límpidos resplandecía el asombro inaugural ante la belleza del mundo."}, {"id": "#2", "hanzi": "面对大人被繁琐规则困扰却束手无策的僵局，有时候恰恰是幼儿园里天真无邪的孩子，能以最直白的童眼看穿问题的本质。当年启发大家剪开竹筐底部的，正是一个路过球场的小朋友。孩子未经世俗教条规训的心智，往往蕴含着化繁为简的非凡创造力。", "pinyin": "Miànduì dàren bèi fánsuǒ guīzé kùnrǎo què shùshǒu-wúcè de jiāngjú, yǒushíhou qiàqià shì yòu'éryuán lǐ tiānzhēn-wúxié de háizi, néng yǐ zuì zhíbái de tóngyǎn kànchuān wèntí de běnzhì. Dāngnián qǐfā dàjiā jiǎn kāi zhúkuāng dǐbù de, zhèng shì yí ge lùguò qiúchǎng de xiǎopéngyou. Háizi wèijīng shìsú jiàotiáo guīxùn de xīnjiào, wǎngwǎng yùnhán zhe huà fán wéi jiǎn de fēifán chuàngzàolì.", "en": "When adults are bogged down by rules and paralyzed by overthinking, it is often an innocent kindergarten child who cuts straight to the core. The person who prompted everyone to cut open the basket bottoms was a passing kid. Unfettered minds harbor sublime creative breakthroughs.", "es": "Cuando los adultos se enredan en trabas burocráticas, a menudo es un parvulito inocente quien vislumbra la solución de raíz. Quien inspiró recortar el fondo de la canasta fue un niño que pasaba. La mente infantil sin prejuicios atesora una sublime creatividad."}]}, {"meanings_summary": {"en": "curious; inquisitive; inquisitive interest", "es": "curioso; inquisitivo; afán de saber"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Being intensely fond of (好) exploring the strange and wonderful (奇) makes you curious (好奇).", "composite_memory_hook_es": "Ser aficionado a (好) descubrir lo insólito y asombroso (奇) define a una persona curiosa (好奇).", "cultural_and_cognitive_roots": "Considered the prime catalyst of philosophical inquiry and scientific invention across Chinese intellectual traditions.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by rising second tone: 'hào qí' (51-35). Note fourth tone 'hào' (not third tone 'hǎo'), soaring upward on 'qí'."}, "semantic_boundary_contrasts": {"core_nuance": "好奇 denotes the psychological craving to investigate or understand novel and unfamiliar phenomena.", "contrasts": [{"id": "1", "compared_word": "好奇 vs. 奇怪", "pinyin": "qíguài", "analysis": "奇怪 is an objective descriptor meaning strange or bizarre (这件事很奇怪), while 好奇 describes a subjective mental state of inquiring eagerness (好奇心)."}, {"id": "2", "compared_word": "好奇 vs. 关注", "pinyin": "guānzhù", "analysis": "关注 means paying close, serious ongoing attention to developments, whereas 好奇 can be whimsical and triggered by novelty."}, {"id": "3", "compared_word": "好奇 vs. 猎奇", "pinyin": "lièqí", "analysis": "猎奇 carries derogatory connotations of sensationalist novelty-seeking, while 好奇 is healthy intellectual inquisitiveness."}]}, "traps_and_cognates": {"look_alikes": [{"character": "奇", "pinyin": "qí", "meaning_en": "strange; wonderful", "distinction_note": "Big 大 on top over 可"}, {"character": "夺", "pinyin": "duó", "meaning_en": "seize; snatch", "distinction_note": "Big 大 over 寸"}, {"character": "寄", "pinyin": "jì", "meaning_en": "send; mail; lodge", "distinction_note": "Roof radical 宀 on top of 奇"}, {"character": "椅", "pinyin": "yǐ", "meaning_en": "chair", "distinction_note": "Tree radical 木 on left of 奇"}], "etymological_cognates": [{"character": "探", "pinyin": "tàn", "gloss_en": "explore; probe; spy"}, {"character": "疑", "pinyin": "yí", "gloss_en": "doubt; suspect"}, {"character": "问", "pinyin": "wèn", "gloss_en": "ask; inquire"}, {"character": "异", "pinyin": "yì", "gloss_en": "different; extraordinary"}]}, "id": "27", "hanzi": "好奇", "pinyin": "hào qí", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "eager to know or learn something new, unusual, or unexplained", "definition_es": "inclinado a conocer o averiguar cosas nuevas, raras o misteriosas", "example_phrase": "对大自然抱有强烈的好奇心 (possess intense curiosity about nature)"}], "example_sentences": [{"id": "#1", "hanzi": "那个年幼的孩子趴在草地旁，好奇地观察着成群结队的黑蚂蚁如何分工搬运沉重的面包屑。", "pinyin": "Nà ge niányòu de háizi pā zài cǎodì páng, hàoqí de guānchá zhe chéngqún-jiéduì de hēi mǎyǐ rúhé fēngōng bānyùn chénzhòng de miànbāoxiè.", "en": "Lying upon the grass, the young child curiously observed how marching black ants divided labor to transport heavy breadcrumbs.", "es": "Tumbado en la hierba, el niño observaba con viva curiosidad cómo las laboriosas hormigas se repartían el acarreo de las migajas de pan."}, {"id": "#2", "hanzi": "保持对未知世界永不衰退的好奇与敬畏，是每一个真正科学家在漫长探索征途上最宝贵的动力源泉。", "pinyin": "Bǎochí duì wèizhī shìjiè yǒng bù shuāituì de hàoqí yǔ jìngwèi, shì měi yí ge zhēnzhèng kēxuéjiā zài màncháng tànsuǒ zhēngtú shang zuì bǎoguì de dònglì yuánquán.", "en": "Maintaining unfading curiosity and reverence toward the unknown is the most precious wellspring of motivation for any true scientist on the quest of discovery.", "es": "Preservar una curiosidad infatigable y reverencia ante lo ignoto constituye el motor más valioso de cualquier científico en su afán de saber."}], "collocations": [{"hanzi": "好奇心", "en": "curiosity; inquisitive mind"}, {"hanzi": "充满好奇", "en": "filled with curiosity"}, {"hanzi": "感到好奇", "en": "feel curious about"}, {"hanzi": "强烈的好奇", "en": "intense curiosity"}, {"hanzi": "满足好奇心", "en": "satisfy one's curiosity"}, {"hanzi": "好奇地打量", "en": "scrutinize curiously"}], "idioms": [{"hanzi": "求知若渴", "pinyin": "qiú zhī ruò kě", "meaning_en": "thirsting for knowledge; eager intellectual yearning"}, {"hanzi": "探幽索微", "pinyin": "tàn yōu suǒ wēi", "meaning_en": "probe deep mysteries and investigate subtleties"}, {"hanzi": "别开生面", "pinyin": "bié kāi shēng miàn", "meaning_en": "break new ground; open up refreshing perspectives"}, {"hanzi": "追本溯源", "pinyin": "zhuī běn sù yuán", "meaning_en": "trace back to the fountainhead; seek underlying origins"}], "character_decomposition": [{"character": "好", "pinyin": "hào", "meaning_en": "fond of; like; love; eager for", "meaning_es": "aficionado a; amar; gustar", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (mother) + 子 (child embracing)", "sound_component": "好 (hào/hǎo)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Mother 女 holding her child 子 with deep affection; fourth-tone reading (hào) denotes being fond of or inclined toward.", "visual_mnemonic_story_en": "A loving mother (女) embracing her beloved child (子), fond of nurturing all that is good (好).", "visual_mnemonic_story_es": "Una madre abnegada (女) abrazando a su tierno hijo (子), inclinada a amar y aprender (好).", "tone_mnemonic_anchor": "51", "cangjie": "VND", "traditional": "好"}, {"character": "奇", "pinyin": "qí", "meaning_en": "strange; rare; wonderful; novel", "meaning_es": "raro; asombroso; singular", "radical": "大", "radical_meaning_en": "big", "meaning_component": "大 (big / remarkable) + 可 (exclamation of approval)", "sound_component": "奇 (qí)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Remarkable person 大 above approved speech 可; something extraordinarily striking, rare, and novel.", "visual_mnemonic_story_en": "A person standing tall (大) exclaiming in astonishment (可) at a wondrous spectacle (奇).", "visual_mnemonic_story_es": "Un hombre con brazos abiertos (大) exclamando con asombro (可) ante un prodigio singular (奇).", "tone_mnemonic_anchor": "35", "cangjie": "KMNR", "traditional": "奇"}], "extended_reading_passages": [{"id": "#1", "hanzi": "爱因斯坦曾谦逊地写道：‘我并没有什么特殊的才能，我只是保持了无比强烈的好奇心。’正是对光线传播与时空奥秘那份孩童般纯粹的好奇，指引他在常人习以为常的自然规律深处，开创出颠覆近代物理学常识的相对论宏伟体系。", "pinyin": "Àiyīnsītǎn céng qiānxùn de xiědào: 'Wǒ bìng méiyǒu shénme tèshū de cáinéng, wǒ zhǐshì bǎochí le wúbǐ qiángliè de hàoqíxīn.' Zhèng shì duì guāngxiàn chuánbō yǔ shíkōng àomì nà fèn háitóng bān chúncuì de hàoqí, zhǐyǐn tā zài chángrén xíyǐwéicháng de zìrán guīlǜ shēnchù, kāichuàng chū diānfù jìndài wùlǐxué chángshí de xiāngduìlùn hóngwěi tǐxì.", "en": "Einstein humbly wrote: 'I have no special talent; I am only passionately curious.' It was pure curiosity about light and spacetime that guided him to unearth the revolutionary theory of relativity from ordinary natural laws.", "es": "Einstein admitió con humildad: 'No tengo talentos especiales, sólo una apasionada curiosidad'. Ese asombro infantil ante la luz y el cosmos le guió a formular la teoría de la relatividad revolucionando la física moderna."}, {"id": "#2", "hanzi": "当年在篮球场边看比赛的孩子，之所以能打破工人们苦思冥想的僵局，恰恰在于他怀揣着一颗未受条框束缚的好奇心。他好奇人们为什么每次都要多此一举地搬梯子取球，正是这份敢于质疑常规的好奇与质朴发问，推开了现代体育创新的一扇大门。", "pinyin": "Dāngnián zài lánqiú chǎngbiān kàn bǐsài de háizi, zhī suǒyǐ néng dǎpò gōngrénmen kǔsī-míngxiǎng de jiāngjú, qiàqià zàiyú tā huáichuāi zhe yì kē wèishòu tiáokuāng shùfù de hàoqíxīn. Tā hàoqí rénmen wèishénme měicì dōu yào duōcǐyìjǔ de bān tīzi qǔ qiú, zhèng shì zhè fèn gǎnyú zhìyí chángguī de hàoqí yǔ zhípǔ fāwèn, tuīkāi le xiàndài tǐyù chuàngxīn de yí shàn dàmén.", "en": "The child by the court broke the adults' deadlock because he held uninhibited curiosity. He wondered why adults needlessly lugged ladders after every score. That candid curiosity questioning routine swung wide the doors to modern sports innovation.", "es": "El niño de la grada desbloqueó el dilema de los adultos gracias a su curiosidad sin ataduras. Le intrigaba por qué acarreaban escaleras en vano tras cada canasta; esa ingenua pregunta abrió las puertas a la innovación deportiva."}]}, {"meanings_summary": {"en": "why should; there is no need; what is the point of", "es": "¿para qué?; ¿qué necesidad hay de...?; no es menester"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Asking why (何) something should be an absolute necessity (必) rhetorical declares: there is no need (何必).", "composite_memory_hook_es": "Cuestionar el porqué (何) de una pretendida necesidad forzosa (必) afirma que no es menester (何必).", "cultural_and_cognitive_roots": "A classic rhetorical rhetorical adverb (反问副词) common in philosophical persuasion and Daoist simplicity.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'hé bì' (35-51). Lift upwards on 'hé' and drop emphatically on 'bì'."}, "semantic_boundary_contrasts": {"core_nuance": "何必 explicitly poses a rhetorical question rejecting the necessity of an action or worry.", "contrasts": [{"id": "1", "compared_word": "何必 vs. 不必", "pinyin": "búbì", "analysis": "不必 is a direct declarative statement stating lack of need (你明天不必来), while 何必 is an emotive rhetorical counter-question (你何必亲自去呢)."}, {"id": "2", "compared_word": "何必 vs. 何苦", "pinyin": "hékǔ", "analysis": "何苦 emphasizes that the action brings unnecessary suffering or pain (何苦自讨苦吃), while 何必 merely focuses on superfluity."}, {"id": "3", "compared_word": "何必 vs. 为何", "pinyin": "wèihé", "analysis": "为何 is a genuine inquiry asking 'why' (你为何迟到), whereas 何必 implies 'there is no reason to'."}]}, "traps_and_cognates": {"look_alikes": [{"character": "何", "pinyin": "hé", "meaning_en": "what; why", "distinction_note": "Person radical 亻 with 可"}, {"character": "荷", "pinyin": "hé", "meaning_en": "lotus; carry", "distinction_note": "Grass radical 艹 on top of 何"}, {"character": "必", "pinyin": "bì", "meaning_en": "must; necessity", "distinction_note": "Heart 心 pierced with a diagonal slash"}, {"character": "心", "pinyin": "xīn", "meaning_en": "heart; mind", "distinction_note": "Without the piercing diagonal slash"}], "etymological_cognates": [{"character": "需", "pinyin": "xū", "gloss_en": "require; need"}, {"character": "用", "pinyin": "yòng", "gloss_en": "use; need (不用)"}, {"character": "须", "pinyin": "xū", "gloss_en": "must; beard"}, {"character": "宜", "pinyin": "yí", "gloss_en": "fitting; suitable"}]}, "id": "28", "hanzi": "何必", "pinyin": "hé bì", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "used in rhetorical questions to emphasize that something is completely unnecessary or superfluous", "definition_es": "empleado en oraciones retóricas para indicar que algo resulta totalmente innecesario o redundante", "example_phrase": "何必为此大惊小怪呢 (why make such a fuss over this?)"}], "example_sentences": [{"id": "#1", "hanzi": "既然双方在主要商业合作条款上已经达成高度共识，又何必为了几个微不足道的细枝末节争执不休呢。", "pinyin": "Jìrán shuāngfāng zài zhǔyào shāngyè hézuò tiáokuǎn shang yǐjīng dáchéng gāodù gòngshí, yòu hébì wèile jǐ ge wēibùzúdào de xìzhī-mòjié zhēngzhí-bùxiū ne.", "en": "Since both sides have reached strong consensus on main business terms, why bother arguing endlessly over trifling trivialities?", "es": "Si ambas partes concuerdan en los términos sustanciales, ¿qué necesidad hay de disputar interminablemente por nimiedades secundarias?"}, {"id": "#2", "hanzi": "人生苦短且岁月匆匆，我们何必整日为了过去的微小挫折耿耿于怀、自我消耗呢。", "pinyin": "Rénshēng kǔduǎn qiě suìyuè cōngcōng, wǒmen hébì zhěngrì wèile guòqù de wēixiǎo cuòzhé gěnggěng-yùhuái, zìwǒ xiāohào ne.", "en": "Life is brief and years slip swiftly by; why should we brood incessantly over past minor setbacks and consume ourselves in grief?", "es": "La vida es breve y los años fugaces; ¿para qué atormentarse y desgastarse a diario rumiando pequeños tropiezos del pasado?"}], "collocations": [{"hanzi": "何必如此", "en": "why go so far; no need for this"}, {"hanzi": "又何必", "en": "why should; there's even less need to"}, {"hanzi": "何必介意", "en": "why take it to heart; don't mind"}, {"hanzi": "何必当初", "en": "why act thus in the first place"}, {"hanzi": "何必多此一举", "en": "why make an unnecessary move"}, {"hanzi": "何必计较", "en": "why haggle or bother over"}], "idioms": [{"hanzi": "何必当初", "pinyin": "hé bì dāng chū", "meaning_en": "why did one act so initially; hindsight regret (早知今日何必当初)"}, {"hanzi": "画蛇添足", "pinyin": "huà shé tiān zú", "meaning_en": "draw snake and add feet; superfluous over-elaboration"}, {"hanzi": "多此一举", "pinyin": "duō cǐ yī jǔ", "meaning_en": "make a totally unnecessary gesture; redundant act"}, {"hanzi": "庸人自扰", "pinyin": "yōng rén zì rǎo", "meaning_en": "worry about imaginary troubles; create problems out of nothing"}], "character_decomposition": [{"character": "何", "pinyin": "hé", "meaning_en": "why; what; how", "meaning_es": "por qué; qué; cómo", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person carrying burden) + 可 (exclamation)", "sound_component": "可 (kě)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 carrying a pole 可, serving as an interrogative asking why or for what reason.", "visual_mnemonic_story_en": "A traveler (亻) setting down his shoulder pole (可) questioning why to go further (何).", "visual_mnemonic_story_es": "Un viajero (亻) posando su pesada pértiga (可) preguntándose el motivo de tanto afán (何).", "tone_mnemonic_anchor": "35", "cangjie": "ONR", "traditional": "何"}, {"character": "必", "pinyin": "bì", "meaning_en": "must; surely; necessity", "meaning_es": "necesario; deber; ciertamente", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "八 (divide) + line piercing heart 心", "sound_component": "必 (bì)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A decisive line dividing or staking certainty through 心; absolute necessity and certainty.", "visual_mnemonic_story_en": "A firm stake driven into the center of resolve, signaling absolute necessity (必).", "visual_mnemonic_story_es": "Una estaca clavada con aplomo en el centro de la decisión, denotando necesidad imperiosa (必).", "tone_mnemonic_anchor": "51", "cangjie": "PHT", "traditional": "必"}], "extended_reading_passages": [{"id": "#1", "hanzi": "苏轼在《前赤壁赋》中豁达地写道：‘天地之间，物各有主，苟非吾之所有，虽一毫而莫取。’人生在世不过数十寒暑，清风明月皆可取用不竭，我们又何必贪恋身外虚名浮利，徒增无谓的心灵枷锁与身心疲惫呢。", "pinyin": "Sū Shì zài Qián Chìbì Fù zhōng huòdá de xiědào: 'Tiāndì zhījiān, wù gè yǒu zhǔ, gǒu fēi wú zhī suǒyǒu, suī yìháo ér mò qǔ.' Rénshēng zài shì bùguò shùshí hánshǔ, qīngfēng míngyuè jiē kě qǔyòng-bùjié, wǒmen yòu hébì tānliàn shēnwài xūmíng fúlì, tú zēng wúwèi de xīnlíng jiāsuǒ yǔ shēnxīn píbèi ne.", "en": "Su Shi magnanimously noted: in heaven and earth each thing has its master; if not mine, take not a hair. Life is a brief flash; cool breezes and bright moons are inexhaustible. Why covet transient vanities and shackle one's soul?", "es": "Su Shi proclamó con serenidad: cada bien tiene su dueño; no tomes ni una brizna ajena. La brisa y la luna son dádivas inagotables. ¿Para qué codiciar vanidades efímeras que sólo encadenan y fatigan el espíritu?"}, {"id": "#2", "hanzi": "小男孩好奇的质问如雷贯耳：‘大家每次投篮后何必大费周章搬梯子爬上去取球呢？’这句反问瞬间点醒了被条条框框束缚的大人们。是啊，既然目的是投球计分，何必死守着一个带底的完整果筐？锯掉多余的底子，问题便迎刃而解。", "pinyin": "Xiǎo nánhái hàoqí de zhìwèn rúléi-guàn'ěr: 'Dàjiā měicì tóulán hòu hébì dàfèi-zhōuzhāng bān tīzi pá shàngqu qǔ qiú ne?' Zhè jù fǎnwèn shùnjiān diǎnxǐng le bèi tiáotiáo-kuàngkuàng shùfù de dàrenmen. Shì a, jìrán mùdì shì tóu qiú jìfēn, hébì sǐshǒu zhe yí ge dàidǐ de wánzhěng guǒkuāng? Jù diào duōyú de dǐzi, wèntí biàn yíngrèn'érjiě.", "en": "The boy's question rang out: 'Why go to all the trouble of hauling ladders after each score?' This rhetorical query woke adults chained by convention. If the goal is scoring, why cling to a closed basket? Saw off the superfluous bottom, and the knot unties.", "es": "La pregunta del niño resonó con fuerza: '¿Para qué complicarse subiendo a una escalera tras cada tiro?' Aquella duda abrió los ojos a los adultos. Si el fin es encestar, ¿qué necesidad hay de conservar el fondo? Serrarlo disipó el problema."}]}, {"meanings_summary": {"en": "thanks to; luckily; fortunate that", "es": "gracias a; por fortuna; menos mal que"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Having great abundance (多) spared from painful deficit (亏) means expressing heartfelt thanks (多亏).", "composite_memory_hook_es": "Contar con abundancia (多) sin sufrir mengua ni pérdida (亏) es motivo para dar gracias (多亏).", "cultural_and_cognitive_roots": "Grammaticalized colloquial construction expressing appreciative relief when a negative outcome is narrowly averted.", "tone_sandhi_and_pitch_modulation": "Two level high tones: 'duō kuī' (55-55). Maintain sustained high, warm vocal pitch."}, "semantic_boundary_contrasts": {"core_nuance": "多亏 expresses grateful relief that an external person or circumstance averted a looming setback.", "contrasts": [{"id": "1", "compared_word": "多亏 vs. 幸亏", "pinyin": "xìngkuī", "analysis": "幸亏 focuses on impersonal luck or chance (幸亏没下雨), while 多亏 can take direct human grammatical objects of gratitude (多亏了你, 多亏老师指点)."}, {"id": "2", "compared_word": "多亏 vs. 感谢", "pinyin": "gǎnxiè", "analysis": "感谢 is an explicit verb expressing appreciation, while 多亏 functions as a clause connective explaining causality."}, {"id": "3", "compared_word": "多亏 vs. 由于", "pinyin": "yóuyú", "analysis": "由于 is a neutral preposition of cause (can lead to bad or good outcomes), while 多亏 strictly leads to happy relief."}]}, "traps_and_cognates": {"look_alikes": [{"character": "多", "pinyin": "duō", "meaning_en": "many; much", "distinction_note": "Two 夕 stacked vertically"}, {"character": "夕", "pinyin": "xī", "meaning_en": "evening; sunset", "distinction_note": "Single character with 3 strokes"}, {"character": "亏", "pinyin": "kuī", "meaning_en": "loss; luckily", "distinction_note": "3 strokes: horizontal, horizontal, vertical hook with slant"}, {"character": "于", "pinyin": "yú", "meaning_en": "at; in; to", "distinction_note": "Has two horizontal bars and a vertical hook without the curving tail"}], "etymological_cognates": [{"character": "幸", "pinyin": "xìng", "gloss_en": "fortunate; lucky"}, {"character": "赖", "pinyin": "lài", "gloss_en": "rely on; thanks to"}, {"character": "蒙", "pinyin": "méng", "gloss_en": "receive favor; indebted"}, {"character": "谢", "pinyin": "xiè", "gloss_en": "thank; decline"}]}, "id": "29", "hanzi": "多亏", "pinyin": "duō kuī", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to express gratitude that an intervention, help, or lucky circumstance averted disaster or achieved success", "definition_es": "expresa que gracias a determinada ayuda o circunstancia propicia se evitó un mal o se logró un bien", "example_phrase": "多亏了邻居的热心相助 (thanks to the enthusiastic help of our neighbors)"}], "example_sentences": [{"id": "#1", "hanzi": "昨晚突降狂风暴雨，多亏巡查网格员在半夜及时排查隐患，老旧小区的低洼地带才没有发生严重内涝。", "pinyin": "Zuówǎn tūjiàng kuángfēng-bàoyǔ, duōkuī xúnchá wǎnggéyuán zài bànyè jíshí páichá yǐnhuàn, lǎojiù xiǎoqū de dīwā dìdài cái méiyǒu fāshēng yánzhòng nèilào.", "en": "A violent storm struck last night; thanks to the neighborhood inspectors identifying hazards at midnight, the low-lying old community avoided flooding.", "es": "Anoche arreció un temporal; gracias a que los vigilantes revisaron los sumideros a medianoche, la barriada vieja no sufrió inundaciones."}, {"id": "#2", "hanzi": "这次复杂的跨境并购谈判能够圆满成功，多亏了法务专家团队在关键时刻化解了重大合规风险。", "pinyin": "Zhè cì fùzá de kuàjìng bìnggòu tánpàn nénggòu yuánmǎn chénggōng, duōkuī le fǎwù zhuānjiā tuánduì zài guānjiàn shíkè huàjiě le zhòngdà hégūi fēngxiǎn.", "en": "This intricate cross-border merger negotiation succeeded smoothly, thanks to the legal team defusing major compliance risks at critical junctures.", "es": "La compleja negociación de fusión internacional culminó con éxito gracias a que el equipo legal resolvió a tiempo graves escollos normativos."}], "collocations": [{"hanzi": "多亏了", "en": "thanks to; fortunately"}, {"hanzi": "这次多亏你", "en": "I'm indebted to you this time"}, {"hanzi": "多亏及时", "en": "luckily in the nick of time"}, {"hanzi": "多亏有准备", "en": "fortunate that we prepared"}, {"hanzi": "多亏医生抢救", "en": "thanks to doctors' emergency rescue"}, {"hanzi": "多亏提醒", "en": "thanks for the timely reminder"}], "idioms": [{"hanzi": "化险为夷", "pinyin": "huà xiǎn wéi yí", "meaning_en": "turn danger into safety; avert mortal peril"}, {"hanzi": "绝处逢生", "pinyin": "jué chù féng shēng", "meaning_en": "find life in a dead end; rescue from desperate straits"}, {"hanzi": "吉人天相", "pinyin": "jí rén tiān xiàng", "meaning_en": "heaven assists the good; blessed by good fortune"}, {"hanzi": "感激不尽", "pinyin": "gǎn jī bú jìn", "meaning_en": "boundless gratitude; cannot thank enough"}], "character_decomposition": [{"character": "多", "pinyin": "duō", "meaning_en": "many; much; abundant", "meaning_es": "mucho; abundante", "radical": "夕", "radical_meaning_en": "evening", "meaning_component": "two 夕 (crescent moons / pieces of meat) stacked", "sound_component": "多 (duō)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Two portions of sacrificial meat 夕 stacked together in ancient script, denoting abundance and multiplicity.", "visual_mnemonic_story_en": "Two cuts of choice meat (夕) piled generously one over another: great abundance (多).", "visual_mnemonic_story_es": "Dos piezas de carne (夕) apiladas generosamente en el festín: gran abundancia (多).", "tone_mnemonic_anchor": "55", "cangjie": "NINI", "traditional": "多"}, {"character": "亏", "pinyin": "kuī", "meaning_en": "loss; deficit; deficient; luckily", "meaning_es": "déficit; pérdida; menguar; gracia", "radical": "一", "radical_meaning_en": "one", "meaning_component": "breath 丂 failing to rise under the sky 一", "sound_component": "亏 (kuī)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Breath striving upward but hindered by a bar; deficit or losing out; used conversely in '多亏' as indebtedness for spared loss.", "visual_mnemonic_story_en": "A debt or deficit averted in time through fortunate assistance (亏).", "visual_mnemonic_story_es": "Un quebranto o déficit esquivado a tiempo gracias a un providencial auxilio (亏).", "tone_mnemonic_anchor": "55", "cangjie": "MMVS", "traditional": "虧"}], "extended_reading_passages": [{"id": "#1", "hanzi": "回首艰辛的创业岁月，创始人感慨万千：‘当年在最资金链濒临断裂的至暗时刻，多亏了老同学毅然抵押房产为我们注资，多亏了团队骨干通宵达旦拼死攻坚，我们这支年轻的企业才能浴火重生、行稳致远。’", "pinyin": "Huíshǒu jiānxīn de chuàngyè suìyuè, chuàngshǐrén gǎnkǎi-wànqiān: 'Dāngnián zài zuì zījīnliàn bīnlín duànliè de zhì'àn shíkè, duōkuī le lǎo tóngxué yìrán dǐyā fángchǎn wèi wǒmen zhùzī, duōkuī le tuánduì gǔgàn tōngxiāo-dádàn pīnsǐ gōngjiān, wǒmen zhè zhī niánqīng de qǐyè cái néng yùhuǒ-chóngshēng, xíngwěn-zhìyuǎn.'", "en": "Reflecting on arduous startup days, the founder remarked with emotion: 'When funding ran dry, thanks to an old classmate mortgaging his home and our team working day and night, our venture rose from the ashes and prospered.'", "es": "Evocando los duros inicios, el fundador confesó conmovido: 'Al agotarse los fondos, gracias a un viejo amigo que hipotecó su casa y al equipo que bregó sin descanso, esta empresa renació de sus cenizas y prosperó'."}, {"id": "#2", "hanzi": "篮球运动今天能够演变成风靡全球的第一大室内球类项目，多亏了当年那位大胆发问的小男孩。多亏了他一句天真无邪的提醒，工匠们才从僵化死板的思维定势中猛然醒悟，拿起锯子锯开筐底，彻底赋予了比赛畅快淋漓的全新生命力。", "pinyin": "Lánqiú yùndòng jīntiān nénggòu yǎnbiàn wéi fēngmí quánqiú de dì-yī dà shìnèi qiúlèi xiàngmù, duōkuī le dāngnián nà wèi dàdǎn fāwèn de xiǎo nánhái. Duōkuī le tā yí jù tiānzhēn-wúxié de tíxǐng, gōngjiàngmen cái cóng jiānghuà sǐbǎn de sīwéi dìngshì zhōng měngrán xǐngwù, ná qǐ jùzi jù kāi kuāngdǐ, chèdǐ fùyǔ le bǐsài chàngkuài-línlí de quánxīn shēngmìnglì.", "en": "That basketball evolved into the world's premier indoor sport is thanks to that daring little boy. Thanks to his innocent reminder, craftsmen snapped out of rigid assumptions, took up saws to cut the basket bottoms, and breathed vibrant life into the game.", "es": "Si el baloncesto es hoy el rey de los deportes bajo techo, es gracias al niño de la grada. Gracias a su ingeniosa observación, los conserjes quebraron su ceguera mental y abrieron el fondo con la sierra, dotando al juego de vitalidad."}]}, {"meanings_summary": {"en": "promptly; at once; hurriedly; hastily", "es": "en seguida; apresuradamente; con presteza; al punto"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Continuously advancing without delay (连) with a brisk busy pace (忙) means doing something promptly (连忙).", "composite_memory_hook_es": "Avanzar sin pausa (连) con paso diligente y presto (忙) expresa actuar apresuradamente (连忙).", "cultural_and_cognitive_roots": "Captures the instinctive, prompt physical reaction to unexpected events, polite hospitality, or urgent emergencies.", "tone_sandhi_and_pitch_modulation": "Two rising second tones: 'lián máng' (35-35). Both rise in tone with lively, agile rhythm."}, "semantic_boundary_contrasts": {"core_nuance": "连忙 emphasizes prompt, immediate physical reaction in response to external circumstances.", "contrasts": [{"id": "1", "compared_word": "连忙 vs. 急忙", "pinyin": "jímáng", "analysis": "连忙 emphasizes instant promptness in reaction (听到敲门连忙开门), whereas 急忙 highlights anxious internal haste and agitation (急忙赶路)."}, {"id": "2", "compared_word": "连忙 vs. 赶快", "pinyin": "gǎnkuài", "analysis": "赶快 is often used in imperatives urging someone else to hurry (你赶快去吧), while 连忙 describes completed past actions in narration."}, {"id": "3", "compared_word": "连忙 vs. 马上", "pinyin": "mǎshàng", "analysis": "马上 specifies temporal immediacy (I will do it right now), whereas 连忙 denotes brisk responsive physical action."}]}, "traps_and_cognates": {"look_alikes": [{"character": "连", "pinyin": "lián", "meaning_en": "connect; even", "distinction_note": "Movement radical 辶 with 车"}, {"character": "运", "pinyin": "yùn", "meaning_en": "transport; fortune", "distinction_note": "Movement radical 辶 with 云"}, {"character": "忙", "pinyin": "máng", "meaning_en": "busy; hurried", "distinction_note": "Heart radical 忄 on left of 亡"}, {"character": "芒", "pinyin": "máng", "meaning_en": "awn; miscanthus", "distinction_note": "Grass radical 艹 on top of 亡"}], "etymological_cognates": [{"character": "急", "pinyin": "jí", "gloss_en": "urgent; hurried"}, {"character": "赶", "pinyin": "gǎn", "gloss_en": "rush; catch up"}, {"character": "速", "pinyin": "sù", "gloss_en": "fast; rapid"}, {"character": "骤", "pinyin": "zhòu", "gloss_en": "sudden; abrupt"}]}, "id": "30", "hanzi": "连忙", "pinyin": "lián máng", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "acting immediately and hurriedly in prompt response to a situation or request", "definition_es": "actuar con prontitud y rapidez en respuesta inmediata a un estímulo o llamada", "example_phrase": "听到敲门声连忙起身开门 (hurriedly get up to answer the knock on the door)"}], "example_sentences": [{"id": "#1", "hanzi": "看到白发苍苍的老奶奶提着沉重的蔬菜上车，坐在前排的年轻小伙子连忙微笑着起身让座。", "pinyin": "Kàndào báifà-cāngcāng de lǎonǎinai tí zhe chénzhòng de shūcài shàngchē, zuò zài qiánpái de niánqīng xiǎohuǒzi liánmáng wēixiào zhe qǐshēn ràngzuò.", "en": "Seeing an elderly gray-haired grandmother board carrying heavy vegetables, the young man in the front row promptly stood up with a smile to offer his seat.", "es": "Al ver subir al autobús a una anciana con pesadas bolsas de verduras, el joven de la primera fila se levantó de inmediato sonriente para cederle el asiento."}, {"id": "#2", "hanzi": "发现实验室管道接头处有微量气体泄漏，值班技术员连忙按下了紧急切断阀并拉响警报。", "pinyin": "Fāxiàn shíyànshì guǎndào jiētóuchù yǒu wēiliàng qìtǐ xièlòu, zhíbān jìshùyuán liánmáng ànxià le jǐnjí qiēduànfá bìng lāxiǎng jǐngbào.", "en": "Spotting a trace gas leak at the laboratory pipe junction, the technician on duty promptly pressed the emergency shut-off valve and sounded the alarm.", "es": "Al percatarse de una leve fuga en la junta de la tubería, el técnico de guardia accionó al punto la válvula de corte y activó la alarma."}], "collocations": [{"hanzi": "连忙站起来", "en": "promptly stand up"}, {"hanzi": "连忙解释", "en": "hastily explain"}, {"hanzi": "连忙道歉", "en": "hastily apologize"}, {"hanzi": "连忙答应", "en": "promptly agree / consent"}, {"hanzi": "连忙跑过去", "en": "hurriedly run over"}, {"hanzi": "连忙挥手", "en": "hurriedly wave one's hand"}], "idioms": [{"hanzi": "迫不及待", "pinyin": "pò bù jí dài", "meaning_en": "too impatient to wait; eager beyond endurance"}, {"hanzi": "疾足先得", "pinyin": "jí zú xiān dé", "meaning_en": "the swift-footed arrives first; first come first served"}, {"hanzi": "闻风而动", "pinyin": "wén fēng ér dòng", "meaning_en": "act immediately upon hearing news; spring into action"}, {"hanzi": "雷厉风行", "pinyin": "léi lì fēng xíng", "meaning_en": "vigorous and speedy as thunder and wind"}], "character_decomposition": [{"character": "连", "pinyin": "lián", "meaning_en": "connect; join; continuous; even", "meaning_es": "unir; conectar; continuo", "radical": "辶", "radical_meaning_en": "movement", "meaning_component": "辶 (movement / road) + 车 (wheeled chariot)", "sound_component": "车 (chē / connection)", "stroke_count": "7", "composition_type": "半包围结构", "etymology_and_mnemonic": "Chariots 车 advancing in unbroken convoy along the road 辶; continuous link without break.", "visual_mnemonic_story_en": "War chariots (车) linked one behind another on a rapid march (辶).", "visual_mnemonic_story_es": "Carros de combate (车) enlazados en marcha continua por el camino (辶).", "tone_mnemonic_anchor": "35", "cangjie": "YKQ", "traditional": "連"}, {"character": "忙", "pinyin": "máng", "meaning_en": "busy; hurried; rushed", "meaning_es": "ocupado; apresurado; ajetreado", "radical": "忄", "radical_meaning_en": "heart", "meaning_component": "忄 (flustered heart) + 亡 (perish / lose)", "sound_component": "亡 (wáng / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Heart radical 忄 beside 亡; heart overwhelmed by urgent tasks, losing calm in a state of bustling flurry.", "visual_mnemonic_story_en": "A flustered heart (忄) racing frantically as if time were slipping away (亡): being busy (忙).", "visual_mnemonic_story_es": "Un corazón agitado (忄) que late apresurado como si el tiempo se agotara (亡): andar atareado (忙).", "tone_mnemonic_anchor": "35", "cangjie": "PYN", "traditional": "忙"}], "extended_reading_passages": [{"id": "#1", "hanzi": "暮春时节山间气候多变，刚才还是晴空万里，转眼间天际便乌云翻滚。正在山坡上晾晒新茶的农户们见状，连忙抓起竹箩竹匾快步收拾。大家齐心协力赶在大雨倾盆前，将嫩绿芬芳的春茶悉数抢运进了干燥的库房。", "pinyin": "Mùchūn shíjié shānjiān qìhòu duōbiàn, gāngcái háishì qíngkōng-wànlǐ, zhuǎnyǎn jiān tiānjì biàn wūyún fāngǔn. Zhèng zài shānpō shang liàngshài xīnchá de nónghùmen jiànzhuàng, liánmáng zhuā qǐ zhúluó zhúbiǎn kuàibù shōushi. Dàjiā qíxīn-xiélì gǎn zài dàyǔ qīngpén qián, jiāng nènlǜ fēnfāng de chūnchá xīshù qiǎngyùn jìn le gānzào de kùfáng.", "en": "Spring mountain weather is capricious; sunny skies swiftly filled with rolling dark clouds. Tea farmers drying leaves on slopes immediately grabbed wicker trays. Working together, they hustled the fragrant green tea into dry storehouses before downpours struck.", "es": "En primavera el clima serrano es veleidoso; el cielo azul se encapotó al punto de nubarrones. Los campesinos que secaban té recogieron las bateas apresuradamente. En equipo, resguardaron la cosecha fragante en el almacén antes del aguacero."}, {"id": "#2", "hanzi": "当听到围观小男孩那句‘为什么不把筐底剪掉’的天真建议时，在场被死板规则困扰的大人们面面相觑，工匠连忙找来锋利的锯子爬上梯恩子。伴随着一阵清脆的拉锯声，桃筐底部应声脱落，困扰所有人多时的繁琐取球障碍瞬间烟消云散。", "pinyin": "Dāng tīngdào wéiguān xiǎo nánhái nà jù 'wèishénme bù bǎ kuāngdǐ jiǎn diào' de tiānzhēn jiànyì shí, zàichǎng bèi sǐbǎn guīzé kùnrǎo de dàrenmen miànmiàn-xiāngqù, gōngjiàng liánmáng zhǎolái fēnglì de jùzi pá shàng tīzi. Bànsuí zhe yí zhèn qīngcuì de lājù shēng, táokuāng dǐbù yìngshēng tuōluò, kùnrǎo suǒyǒurén duōshí de fánsuǒ qǔ qiú zhàng'ài shùnjiān yānxiāo-yúnsàn.", "en": "Hearing the boy's suggestion: 'Why not cut off the basket bottom?', dumbfounded adults looked at each other. A worker promptly grabbed a sharp saw and climbed the ladder. With rhythmic rasping strokes, the bottom fell away, dissolving the nuisance in an instant.", "es": "Ante la ocurrencia del niño: '¿Por qué no le quitan el fondo?', los adultos se miraron perplejos. El conserje buscó al punto una sierra afilada y subió a la escalera. Al serrar la base, el obstáculo que tanto les agobiaba se esfumó en un abrir y cerrar de ojos."}]}, {"meanings_summary": {"en": "to look; see; glance at", "es": "mirar; ver; echar un vistazo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Directing your attentive eyes (目) with sharp focus (焦) allows you to take a close look (瞧).", "composite_memory_hook_es": "Fijar la mirada (目) con ardiente interés (焦) te permite echar un buen vistazo (瞧).", "cultural_and_cognitive_roots": "Expressive northern Mandarin colloquialism for looking, common in vernacular novels and Beijing dialogue.", "tone_sandhi_and_pitch_modulation": "Rising second tone: 'qiáo' (35). Soar upward smoothly with bright colloquial inflection."}, "semantic_boundary_contrasts": {"core_nuance": "瞧 is an informal, colloquial synonym of 看, often implying a spontaneous glance or evaluation.", "contrasts": [{"id": "1", "compared_word": "瞧 vs. 看", "pinyin": "kàn", "analysis": "看 is neutral and universally used across spoken and written Chinese, while 瞧 is vivid northern colloquial speech."}, {"id": "2", "compared_word": "瞧 vs. 望", "pinyin": "wàng", "analysis": "望 denotes gazing far into the distant horizon or up at stars, whereas 瞧 focuses on nearby objects or people."}, {"id": "3", "compared_word": "瞧 vs. 瞅", "pinyin": "chǒu", "analysis": "瞅 is strongly regional (Northeastern vernacular), while 瞧 is standard colloquial northern Mandarin."}]}, "traps_and_cognates": {"look_alikes": [{"character": "瞧", "pinyin": "qiáo", "meaning_en": "look; see", "distinction_note": "Eye radical 目 on left with 焦"}, {"character": "焦", "pinyin": "jiāo", "meaning_en": "burnt; anxious", "distinction_note": "Without the eye radical on left"}, {"character": "樵", "pinyin": "qiáo", "meaning_en": "woodcutter; gather firewood", "distinction_note": "Tree radical 木 on left of 焦"}, {"character": "礁", "pinyin": "jiāo", "meaning_en": "reef; submerged rock", "distinction_note": "Stone radical 石 on left of 焦"}], "etymological_cognates": [{"character": "看", "pinyin": "kàn", "gloss_en": "look; watch"}, {"character": "望", "pinyin": "wàng", "gloss_en": "gaze into distance; hope"}, {"character": "睹", "pinyin": "dǔ", "gloss_en": "witness; observe"}, {"character": "瞻", "pinyin": "zhān", "gloss_en": "look forward; inspect"}]}, "id": "31", "hanzi": "瞧", "pinyin": "qiáo", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to look at, glance, or observe with the eyes, predominantly used in colloquial spoken Chinese", "definition_es": "mirar u observar con atención; muy habitual en el lenguaje coloquial", "example_phrase": "你快瞧瞧那是什么 (take a look quickly at what that is)"}], "example_sentences": [{"id": "#1", "hanzi": "你快到窗前瞧瞧，昨晚的一场大雪把整个小区的树木都裹上了一层银白色的厚霜。", "pinyin": "Nǐ kuài dào chuāngqián qiáoqiao, zuówǎn de yì chǎng dàxuě bǎ zhěnggè xiǎoqū de shùmù dōu guǒ shàng le yì céng yínbáisè de hòushuāng.", "en": "Quick, come to the window and take a look; last night's heavy snowfall wrapped all trees in the neighborhood in thick silver frost.", "es": "Ven corriendo a la ventana a echar un vistazo; la copiosa nevada de anoche envolvió los árboles de la barriada en una gruesa escarcha plateada."}, {"id": "#2", "hanzi": "他总爱戴着有色眼镜瞧人，这种傲慢偏见的处世态度让身边的很多同事都敬而远之。", "pinyin": "Tā zǒng ài dài zhe yǒusè yǎnjìng qiáo rén, zhè zhǒng àomàn piānjiàn de chǔshì tàidù ràng shēnbiān de hěnduō tóngshì dōu jìng'éryuǎnzhī.", "en": "He always looks at people through tinted glasses; this arrogant and prejudiced attitude causes many colleagues around him to keep their distance.", "es": "Siempre mira a los demás con prejuicios; esa actitud altanera y despectiva hace que sus compañeros de trabajo prefieran guardar las distancias."}], "collocations": [{"hanzi": "瞧一瞧", "en": "have a look; take a glance"}, {"hanzi": "瞧不起", "en": "look down upon; despise"}, {"hanzi": "瞧得起", "en": "think highly of; respect"}, {"hanzi": "瞧见", "en": "catch sight of; see"}, {"hanzi": "瞧病", "en": "see a doctor (colloquial)"}, {"hanzi": "走着瞧", "en": "wait and see (warning/slang)"}], "idioms": [{"hanzi": "另眼相看", "pinyin": "lìng yǎn xiāng kàn", "meaning_en": "view in a new and favorable light; treat with special respect"}, {"hanzi": "刮目相看", "pinyin": "guā mù xiāng kàn", "meaning_en": "rub eyes and look with new respect"}, {"hanzi": "冷眼旁观", "pinyin": "lěng yǎn páng guān", "meaning_en": "look on coldly from the sidelines; detached spectator"}, {"hanzi": "虎视眈眈", "pinyin": "hǔ shì dān dān", "meaning_en": "glare like a tiger eyeing its prey covetously"}], "character_decomposition": [{"character": "瞧", "pinyin": "qiáo", "meaning_en": "look; glance; see", "meaning_es": "mirar; ver", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "目 (eye / gaze) + 焦 (scorched / intense longing)", "sound_component": "焦 (jiāo / phonetic association)", "stroke_count": "17", "composition_type": "左右结构", "etymology_and_mnemonic": "Eye radical 目 beside 焦 (scorched bird over fire); focusing one's eyes with burning intensity to discern something.", "visual_mnemonic_story_en": "Keen eyes (目) focusing through scorched embers (焦) to catch a sharp glance of the truth (瞧).", "visual_mnemonic_story_es": "Ojos atentos (目) que atisban entre ascuas (焦) para divisar con claridad lo que ocurre (瞧).", "tone_mnemonic_anchor": "35", "cangjie": "BUPOG", "traditional": "瞧"}], "extended_reading_passages": [{"id": "#1", "hanzi": "母亲常拉着客人的手亲切地说：‘快进屋瞧瞧，院子里的老茶花开得正艳呢。’那些在岁月风雨中悄然绽放的花瓣红艳似火，映照着小院的宁静祥和，也温暖着每一个远道而来寻访乡愁的游子。", "pinyin": "Mǔqīn cháng lā zhe kèrén de shǒu qīnqiè de shuō: 'Kuài jìn wū qiáoqiao, yuànzi lǐ de lǎo cháhuā kāi de zhèng yàn ne.' Nàxiē zài suìyuè fēngyǔ zhōng qiǎorán zhànfàng de huābàn hóngyàn-sìhuǒ, yìngzhào zhe xiǎoyuàn de níngjìng xiánghé, yě wēnnuǎn zhe měi yí ge yuǎndào'érlái xúnfǎng xiāngchóu de yóuzǐ.", "en": "Mother warmly took guests' hands: 'Come inside and take a look; the old camellias are blooming splendidly.' Blossoms glowing like fire mirrored the tranquil yard, comforting nostalgic travelers from afar.", "es": "La madre tomaba afectuosamente la mano del visitante: 'Pasad a ver qué floridas están las camelias del patio'. Sus pétalos ardientes como fuego acariciaban la paz del hogar, confortando a los viajeros."}, {"id": "#2", "hanzi": "当年路过球场的小男孩好奇地停下脚步，歪着头仔细瞧着那两个挂在高处的桃筐，忍不住随口说了句：‘你们瞧，把筐底直接锯掉不就全解决了吗？’这句看似天真的大实话，瞬间点醒了全场工匠。", "pinyin": "Dāngnián lùguò qiúchǎng de xiǎo nánhái hàoqí de tíngxià jiǎobù, wāi zhe tóu zǐxì qiáo zhe nà liǎng ge guà zài gāochù de táokuāng, rěnbùzhù suíkǒu shuō le jù: 'Nǐmen qiáo, bǎ kuāngdǐ zhíjiē jù diào bù jiù quán jiějué le ma?' Zhè jù kànsì tiānzhēn de dà shíhuà, shùnjiān diǎnxǐng le quánchǎng gōngjiàng.", "en": "The boy passing the court paused curiously, tilting his head to look at the elevated baskets, blurted: 'Look, wouldn't sawing off the bottoms solve everything?' That candid remark instantly woke all the workmen.", "es": "El niño que pasaba se detuvo con curiosidad, contempló las canastas en lo alto y soltó: 'Miren, ¿acaso no se arregla cortando el fondo?' Aquella obviedad inocente iluminó de golpe a todos los presentes."}]}, {"meanings_summary": {"en": "to perplex; trouble; haunt; distress; dilemma", "es": "atormentar; agobiar; desconcertar; quebradero de cabeza"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Being trapped like a walled-in tree (困) while agitated by meddling hands (扰) produces deep distress (困扰).", "composite_memory_hook_es": "Estar acorralado sin salida (困) mientras te inquietan agitaciones ajenas (扰) genera hondo agobio (困扰).", "cultural_and_cognitive_roots": "Blends spatial confinement (困) with psychic agitation (扰) into an evocative compound for modern dilemmas.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by dipping third tone: 'kùn rǎo' (51-214). Drop decisively on 'kùn', then dip low and scoop upward on 'rǎo'."}, "semantic_boundary_contrasts": {"core_nuance": "困扰 denotes persistent psychological vexation or chronic technical dilemmas requiring resolution.", "contrasts": [{"id": "1", "compared_word": "困扰 vs. 骚扰", "pinyin": "sāorǎo", "analysis": "骚扰 involves malicious, intrusive harassment from external predators or spam, whereas 困扰 is an ongoing internal mental distress or technical bottleneck."}, {"id": "2", "compared_word": "困扰 vs. 打扰", "pinyin": "dǎrǎo", "analysis": "打扰 is a polite colloquial term for interrupting someone temporarily (打扰一下), without deep existential anguish."}, {"id": "3", "compared_word": "困扰 vs. 障碍", "pinyin": "zhàng'ài", "analysis": "障碍 refers to concrete tangible physical or policy barriers, while 困扰 is cognitive distress."}]}, "traps_and_cognates": {"look_alikes": [{"character": "困", "pinyin": "kùn", "meaning_en": "trapped; sleepy", "distinction_note": "Tree 木 inside enclosure 囗"}, {"character": "因", "pinyin": "yīn", "meaning_en": "cause; reason", "distinction_note": "Big 大 inside enclosure 囗"}, {"character": "扰", "pinyin": "rǎo", "meaning_en": "disturb", "distinction_note": "Hand radical 扌 on left with 尤"}, {"character": "拢", "pinyin": "lǒng", "meaning_en": "gather; draw together", "distinction_note": "Hand radical 扌 on left with 龙"}], "etymological_cognates": [{"character": "烦", "pinyin": "fán", "gloss_en": "vexed; troublesome"}, {"character": "恼", "pinyin": "nǎo", "gloss_en": "irritated; angry"}, {"character": "缠", "pinyin": "chán", "gloss_en": "entangle; pester"}, {"character": "乱", "pinyin": "luàn", "gloss_en": "chaos; disorder"}]}, "id": "32", "hanzi": "困扰", "pinyin": "kùn rǎo", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cause someone persistent worry, difficulty, or psychological perplexity", "definition_es": "inquietar o causar desazón mental continua ante un problema difícil de resolver", "example_phrase": "深受失眠问题的困扰 (deeply troubled by insomnia problems)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a nagging difficulty, dilemma, or source of perplexity", "definition_es": "motivo de honda preocupación o dilema persistente", "example_phrase": "摆脱长期的生活困扰 (shake off long-term troubles of life)"}], "example_sentences": [{"id": "#1", "hanzi": "连续数周的高强度加班和日益严苛的业绩考核，让这位年轻的项目总监饱受焦虑和失眠的困扰。", "pinyin": "Liánxù shù zhōu de gāo qiángdù jiābān hé rìyì yánkē de yèjì kǎohé, ràng zhè wèi niánqīng de xiàngmù zǒngjiān bǎoshòu jiāolǜ hé shīmián de kùnrǎo.", "en": "Weeks of intense overtime and increasingly harsh performance metrics left the young project director deeply troubled by anxiety and insomnia.", "es": "Semanas consecutivas de horas extras y exigentes evaluaciones de rendimiento dejaron al joven director de proyectos agobiado por el insomnio y la ansiedad."}, {"id": "#2", "hanzi": "长期困扰该地区经济发展的交通瓶颈问题，终于在新建的高速公路通车后得到了根本性缓解。", "pinyin": "Chángqī kùnrǎo gāi dìqū jīngjì fāzhǎn de jiāotōng píngjǐng wèntí, zhōngyú zài xīnjiàn de gāosù gōnglù tōngchē hòu dédào le gēnběnxìng huǎnjiě.", "en": "The transportation bottleneck that had long troubled regional economic development was fundamentally alleviated once the new expressway opened.", "es": "El cuello de botella logístico que atormentaba el desarrollo económico comarcal se resolvió con la inauguración de la nueva autovía."}], "collocations": [{"hanzi": "深受困扰", "en": "deeply troubled / harassed"}, {"hanzi": "摆脱困扰", "en": "cast off troubles / perplexities"}, {"hanzi": "解决困扰", "en": "resolve a nagging difficulty"}, {"hanzi": "带来困扰", "en": "bring distress or trouble"}, {"hanzi": "长期困扰", "en": "long-term dilemma / trouble"}, {"hanzi": "精神困扰", "en": "mental / psychological distress"}], "idioms": [{"hanzi": "焦头烂额", "pinyin": "jiāo tóu làn é", "meaning_en": "scorched head and battered forehead; overwhelmed with distress"}, {"hanzi": "心烦意乱", "pinyin": "xīn fán yì luàn", "meaning_en": "agitated and confused; perturbed in mind"}, {"hanzi": "不知所措", "pinyin": "bù zhī suǒ cuò", "meaning_en": "at one's wits' end; not knowing what to do"}, {"hanzi": "忧心忡忡", "pinyin": "yōu xīn chōng chōng", "meaning_en": "laden with heavy anxieties and care"}], "character_decomposition": [{"character": "困", "pinyin": "kùn", "meaning_en": "trapped; surrounded; hard-pressed", "meaning_es": "acorralado; sitiado; fatigado", "radical": "囗", "radical_meaning_en": "enclosure", "meaning_component": "囗 (enclosing perimeter) + 木 (tree / timber)", "sound_component": "困 (kùn)", "stroke_count": "7", "composition_type": "全包围结构", "etymology_and_mnemonic": "A tree 木 trapped tightly within an enclosure 囗; unable to grow or spread roots, symbolizing being trapped in dire straits.", "visual_mnemonic_story_en": "A leafy tree (木) confined inside a cramped stone wall (囗), stunted and trapped in distress (困).", "visual_mnemonic_story_es": "Un árbol (木) enclaustrado dentro de cuatro muros (囗), asfixiado y atrapado en apuros (困).", "tone_mnemonic_anchor": "51", "cangjie": "WDI", "traditional": "困"}, {"character": "扰", "pinyin": "rǎo", "meaning_en": "disturb; trouble; harass; agitate", "meaning_es": "molestar; perturbar; desasosegar", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (restless hand) + 尤 (outstanding / faulty)", "sound_component": "尤 (yóu / phonetic association)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Hand radical 扌 beside 尤; restless hands stirring up trouble, creating irritation and emotional agitation.", "visual_mnemonic_story_en": "A meddling hand (扌) stirring up trouble (尤) to disturb domestic peace (扰).", "visual_mnemonic_story_es": "Una mano inquieta (扌) que agita y remueve discordias (尤) turbando la paz (扰).", "tone_mnemonic_anchor": "214", "cangjie": "QIKU", "traditional": "擾"}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多职场人在面对海量碎片化信息与无休止的即时通讯时，常常深陷注意力涣散与精神焦虑的困扰。若想重获心灵的宁静与工作的高效，就必须勇于自我设限，学会定期给大脑做‘断舍离’的清理减负。", "pinyin": "Hěnduō zhíchǎngrén zài miànduì hǎiliàng suìpiànhuà xìnxī yǔ wúxiūzhǐ de jíshí tōngxùn shí, chángcháng shēnxiàn zhùyìlì huànsàn yǔ jīngshén jiāolǜ de kùnrǎo. Ruò xiǎng chónghuò xīnlíng de níngjìng yǔ gōngzuò de gāoxiào, jiù bìxū yǒngyú zìwǒ shèxiàn, xuéhuì dìngqī gěi dànǎo zuò 'duànshělí' de qīnglǐ jiǎnfù.", "en": "Faced with fragmented info and endless instant chats, professionals suffer from distraction and anxiety. To regain mental peace and work efficiency, one must dare to set boundaries and declutter the brain regularly.", "es": "Ante la avalancha de mensajes instantáneos, muchos profesionales padecen dispersión y agobio. Para recobrar la calma y rendir con eficacia, urge fijar límites y depurar la sobrecarga mental."}, {"id": "#2", "hanzi": "在篮球运动诞生最初的那段岁月里，每次投篮进球后的强制取球停顿，曾是让所有人焦头烂额的巨大困扰。大家习惯性地在‘如何更省力地把球取出来’的固有逻辑里打转，直到锯开筐底的直截了当，才彻底粉碎了这一旷日持久的困扰。", "pinyin": "Zài lánqiú yùndòng dànshēng zuìchū de nà duàn suìyuè lǐ, měicì tóulán jìnqiú hòu de qiángzhì qǔ qiú tíngdùn, céng shì ràng suǒyǒurén jiāotóu-làn'é de jùdà kùnrǎo. Dàjiā xíguànxìng de zài 'rúhé gèng shěnglì de bǎ qiú qǔ chūlái' de gùyǒu luóji lǐ dǎzhuàn, zhídào jù kāi kuāngdǐ de zhíjié-liǎodàng, cái chèdǐ fěnsuì le zhè yí kuàngrì-jiǔchí de kùnrǎo.", "en": "In basketball's nascent days, retrieving balls after scores was a persistent headache. People circled round the premise of 'how to extract balls with less effort', until sawing off the bottoms shattered this chronic dilemma.", "es": "En la infancia del baloncesto, recuperar el balón tras encestar fue un agobio constante. Todos cavilaban sobre cómo extraerlo con menos esfuerzo, hasta que una sierra abrió la base extirpando el quebradero de cabeza."}]}, {"meanings_summary": {"en": "thinking; thought; cognitive mindset; mental logic", "es": "pensamiento; modo de pensar; lógica mental; intelecto"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The heart-brain pondering (思) woven into a structured mental framework (维) forms cognitive thinking (思维).", "composite_memory_hook_es": "El juicio reflexivo (思) enhebrado en una red conceptual sólida (维) da lugar al pensamiento (思维).", "cultural_and_cognitive_roots": "Represents the intellectual lattice of human reasoning, balancing philosophical insight with practical problem-solving.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by rising second tone: 'sī wéi' (55-35). Hold 'sī' high, then soar gracefully on 'wéi'."}, "semantic_boundary_contrasts": {"core_nuance": "思维 denotes higher-order cognitive faculties, mental paradigms, and structured logical deduction.", "contrasts": [{"id": "1", "compared_word": "思维 vs. 思想", "pinyin": "sīxiǎng", "analysis": "思想 denotes overarching ideological beliefs, philosophical outlooks, or political doctrine, while 思维 refers to cognitive logic and problem-solving patterns."}, {"id": "2", "compared_word": "思维 vs. 想法", "pinyin": "xiǎngfǎ", "analysis": "想法 refers to a specific concrete opinion, notion, or idea on a matter, whereas 思维 is the cognitive apparatus producing ideas."}, {"id": "3", "compared_word": "思维 vs. 情绪", "pinyin": "qíngxù", "analysis": "情绪 encompasses physiological affective moods and feelings, directly contrasting with rational 思维."}]}, "traps_and_cognates": {"look_alikes": [{"character": "思", "pinyin": "sī", "meaning_en": "think; ponder", "distinction_note": "Field 田 over heart 心"}, {"character": "恩", "pinyin": "ēn", "meaning_en": "grace; kindness", "distinction_note": "Cause 因 over heart 心"}, {"character": "维", "pinyin": "wéi", "meaning_en": "maintain; tie", "distinction_note": "Silk radical 纟 on left with 隹"}, {"character": "谁", "pinyin": "shuí", "meaning_en": "who", "distinction_note": "Speech radical 讠 on left with 隹"}], "etymological_cognates": [{"character": "考", "pinyin": "kǎo", "gloss_en": "examine; ponder"}, {"character": "虑", "pinyin": "lǜ", "gloss_en": "consider; deliberate"}, {"character": "想", "pinyin": "xiǎng", "gloss_en": "think; yearn"}, {"character": "念", "pinyin": "niàn", "gloss_en": "recollect; idea"}]}, "id": "33", "hanzi": "思维", "pinyin": "sī wéi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the cognitive process of reflecting, reasoning, and conceptualizing using the human mind", "definition_es": "proceso intelectivo y cognitivo de razonar, abstraer y concebir ideas en la mente", "example_phrase": "逻辑思维能力 (logical thinking ability)"}], "example_sentences": [{"id": "#1", "hanzi": "数学奥林匹克竞赛不仅考核基础公式的计算速度，更着重考察参赛选手严密的抽象逻辑思维能力。", "pinyin": "Shùxué Àolínpǐkè jìngsài bùjǐn kǎohé jīchǔ gōngshì de jìsuàn sùdù, gèng zhuózhòng kǎochá cānsài xuǎnshǒu yánmì de chōuxiàng luóji sīwéi nénglì.", "en": "Math Olympiad competitions test not only speed in calculating basic formulas, but focus primarily on competitors' rigorous abstract logical thinking skills.", "es": "Las Olimpiadas de Matemáticas no sólo evalúan el cálculo de fórmulas, sino el rigor y agudeza del pensamiento lógico abstracto de los participantes."}, {"id": "#2", "hanzi": "面对瞬息万变的技术革命，领导者必须主动打破原有的思维定式，以更加开放包容的心态拥抱未知。", "pinyin": "Miànduì shùnxī-wànbiàn de jìshù gémìng, lǐngdǎozhě bìxū zhǔdòng dǎpò yuányǒu de sīwéi dìngshì, yǐ gèngjiā kāifàng bāoróng de xīntài yōngbào wèizhī.", "en": "Confronted by rapid technological upheaval, leaders must proactively shatter existing cognitive mindsets and embrace the unknown with an open heart.", "es": "Ante la vertiginosa revolución tecnológica, los líderes deben quebrar sus esquemas mentales preconcebidos y acoger lo ignoto con amplitud de miras."}], "collocations": [{"hanzi": "思维定式", "en": "fixed mindset / mental rut"}, {"hanzi": "逻辑思维", "en": "logical thinking"}, {"hanzi": "创新思维", "en": "innovative thinking"}, {"hanzi": "思维能力", "en": "thinking ability / intellect"}, {"hanzi": "思维模式", "en": "thought pattern / paradigm"}, {"hanzi": "批判性思维", "en": "critical thinking"}], "idioms": [{"hanzi": "深谋远虑", "pinyin": "shēn móu yuǎn lǜ", "meaning_en": "plan deeply and foresee distantly; farsighted strategy"}, {"hanzi": "墨守成规", "pinyin": "mò shǒu chéng guī", "meaning_en": "stick stubbornly to obsolete conventions"}, {"hanzi": "见微知著", "pinyin": "jiàn wēi zhī zhù", "meaning_en": "discern future macro trends from minute signs"}, {"hanzi": "运筹帷幄", "pinyin": "yùn chóu wéi wò", "meaning_en": "devise strategies within military tents; mastermind victories"}], "character_decomposition": [{"character": "思", "pinyin": "sī", "meaning_en": "think; consider; deliberate; miss", "meaning_es": "pensar; reflexionar; meditar", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "囟 / 田 (brain cranium fontanelle) + 心 (heart consciousness)", "sound_component": "思 (sī)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Brain cranium 田 (囟) atop heart 心; in classical Chinese philosophy, the heart and brain collaborate as seat of cognition and contemplation.", "visual_mnemonic_story_en": "The brain (田) and the feeling heart (心) harmonizing in quiet reflection (思).", "visual_mnemonic_story_es": "El cerebro pensante (田) y el corazón sensible (心) concertados en profunda meditación (思).", "tone_mnemonic_anchor": "55", "cangjie": "WP", "traditional": "思"}, {"character": "维", "pinyin": "wéi", "meaning_en": "tie; maintain; dimension", "meaning_es": "atar; preservar; dimensión", "radical": "纟", "radical_meaning_en": "silk thread", "meaning_component": "纟 (binding cords) + 隹 (bird with short tail)", "sound_component": "隹 (zhuī / phonetic association)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Silk radical 纟 tethering short-tailed bird 隹; tying corners and cords together, extended to mental fabric, dimensions, and maintenance.", "visual_mnemonic_story_en": "Strong silk cords (纟) tying the corner poles of a tent firmly in multi-dimensional balance (维).", "visual_mnemonic_story_es": "Fuertes cuerdas de seda (纟) tensando los amarres de una tienda en armonía tridimensional (维).", "tone_mnemonic_anchor": "35", "cangjie": "VFOV", "traditional": "維"}], "extended_reading_passages": [{"id": "#1", "hanzi": "哲学家笛卡尔曾留下‘我思故我在’的千古名言，揭示了理性思维是确证个体自我存在与认识宇宙的根本基石。人类唯有保持持续反省与独立深邃的理性思维，才能在纷繁复杂的世俗尘嚣中擦亮双眼，不被盲从的群体偏见所裹挟。", "pinyin": "Zhéxuéjiā Díkǎ'ěr céng liúxià 'wǒ sī gù wǒ zài' de qiāngǔ míngyán, jiēshì le lǐxìng sīwéi shì quèzhèng gètǐ zìwǒ cúnzài yǔ rènzhī yǔzhòu de gēnběn jīshí. Rénlèi wéiyǒu bǎochí chíxù fǎnxǐng yǔ dúlì shēnxuì de lǐxìng sīwéi, cái néng zài fēnfán-fùzá de shìsú chénxiāo zhōng cāliàng shuāngyǎn, bù bèi mángcóng de qúntǐ piānjiàn suǒ guǒxié.", "en": "Descartes coined 'I think, therefore I am', proving rational thought is the bedrock confirming existence. Only by nurturing deep reflective thinking can humanity see clearly amid worldly distractions, resisting herd bias.", "es": "Descartes proclamó 'pienso, luego existo', situando el raciocinio como cimiento del ser. Sólo cultivando un criterio lúcido y reflexivo preservará el ser humano su discernimiento ante el ruido gregario."}, {"id": "#2", "hanzi": "篮球发展史上的‘筐底革命’，本质上是一场颠覆性的思维突破。工匠们最初被‘筐必定有底’的传统经验死死框住，一心只想研制复杂的取球器械。直到有人跳出思维定势，人们才恍然大悟：去掉无用的底子，才是最高明的思维解法。", "pinyin": "Lánqiú fāzhǎnshǐ shang de 'kuāngdǐ gémìng', běnzhì shang shì yì chǎng diānfùxìng de sīwéi tūpò. Gōngjiàngmen zuìchū bèi 'kuāng bìdìng yǒu dǐ' de chuántǒng jīngyàn sǐsǐ kuàng zhù, yìxīn zhǐ xiǎng yánzhì fùzá de qǔ qiú qìxiè. Zhídào yǒurén tiào chū sīwéi dìngshì, rénmen cái huǎngrán-dàwù: qùdiào wúyòng de dǐzi, cái shì zuì gāomíng de sīwéi jiěfǎ.", "en": "The basket revolution in basketball history was at heart a paradigm shift. Craftsmen were trapped by the assumption that 'baskets must have bottoms', scheming complex gizmos. Breaking that mental rut revealed the truth: removing the bottom was the ultimate solution.", "es": "La revolución del fondo de la canasta fue un audaz salto cognitivo. Los conserjes creían a ciegas que 'toda cesta debe tener fondo', discurriendo artificios. Romper ese esquema demostró que eliminar lo sobrante era la solución genial."}]}, {"meanings_summary": {"en": "dull; foolish; blank; to stay; dawdle", "es": "atontado; boquiabierto; torpe; quedarse; permanecer"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Having your mouth open (口) while frozen like a wooden stump (木) makes you look blank and stunned (呆).", "composite_memory_hook_es": "Tener la boca abierta (口) petrificado como un poste de madera (木) te deja boquiabierto (呆).", "cultural_and_cognitive_roots": "Derives from Zhuangzi's fable of the fighting cock (呆若木鸡) which appears motionless and dull but possesses unbeatable calm.", "tone_sandhi_and_pitch_modulation": "Level high tone: 'dāi' (55). Sustain an even high tone without dropping in pitch."}, "semantic_boundary_contrasts": {"core_nuance": "呆 indicates temporary mental blankness, frozen immobility, or colloquially lingering in a location.", "contrasts": [{"id": "1", "compared_word": "呆 vs. 傻", "pinyin": "shǎ", "analysis": "傻 describes innate silliness, naivety, or lack of intelligence, whereas 呆 emphasizes staring blankly or standing frozen in shock."}, {"id": "2", "compared_word": "呆 vs. 留", "pinyin": "liú", "analysis": "留 is formal for staying or detaining (留步, 留学), while 呆 is informal colloquial for hanging around (呆在家里)."}, {"id": "3", "compared_word": "呆 vs. 愣", "pinyin": "lèng", "analysis": "愣 stresses sudden momentary bewilderment or rash impulsiveness (发愣, 愣头青), while 呆 can be prolonged dullness."}]}, "traps_and_cognates": {"look_alikes": [{"character": "呆", "pinyin": "dāi", "meaning_en": "dull; blank; stay", "distinction_note": "Mouth 口 on top over wood 木"}, {"character": "杏", "pinyin": "xìng", "meaning_en": "apricot", "distinction_note": "Wood 木 on top over mouth 口"}, {"character": "困", "pinyin": "kùn", "meaning_en": "trapped; surrounded", "distinction_note": "Wood 木 inside enclosure 囗"}, {"character": "保", "pinyin": "bǎo", "meaning_en": "protect; preserve", "distinction_note": "Person radical 亻 on left of 呆"}], "etymological_cognates": [{"character": "傻", "pinyin": "shǎ", "gloss_en": "foolish; silly"}, {"character": "痴", "pinyin": "chī", "gloss_en": "infatuated; foolish"}, {"character": "滞", "pinyin": "zhì", "gloss_en": "stagnant; sluggish"}, {"character": "钝", "pinyin": "dùn", "gloss_en": "blunt; slow-witted"}]}, "id": "34", "hanzi": "呆", "pinyin": "dāi", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "dull-witted, sluggish, or staring blankly with an immobile expression", "definition_es": "quedarse pasmado, atónito o con la mirada perdida sin reaccionar", "example_phrase": "吓得目瞪口呆 (scared stiff and dumbfounded)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to stay, linger, or remain in a place without moving", "definition_es": "permanecer o quedarse en un sitio durante un tiempo", "example_phrase": "在老家呆了两个星期 (stayed in hometown for two weeks)"}], "example_sentences": [{"id": "#1", "hanzi": "听到突如其来的失业噩耗，他整个人顿时呆立在原地，脑子里一片空白不知该如何是好。", "pinyin": "Tīngdào tūrúqílái de shīyè èhào, tā zhěngrén dùnshí dāi lì zài yuándì, nǎozǐ lǐ yípiàn kòngbái bùzhī gāi rúhé shì hǎo.", "en": "Hearing the abrupt catastrophic news of his layoff, he stood blankly rooted to the spot, his mind an utter void not knowing what to do.", "es": "Al enterarse del repentino despido, se quedó paralizado en el sitio boquiabierto, con la mente en blanco y sin saber cómo reaccionar."}, {"id": "#2", "hanzi": "周末他哪儿也不想去，就喜欢一个人静静地呆在飘着书香的书房里喝茶看书。", "pinyin": "Zhōumò tā nǎr yě bù xiǎng qù, jiù xǐhuan yí ge rén jìngjìng de dāi zài piāozhe shūxiāng de shūfáng lǐ hēchá kànshū.", "en": "On weekends he had no wish to go anywhere, preferring to stay quietly alone in his book-scented study drinking tea and reading.", "es": "Los fines de semana no le apetece salir; prefiere quedarse plácidamente en el estudio disfrutando de la lectura y un té aromático."}], "collocations": [{"hanzi": "目瞪口呆", "en": "dumbfounded; flabbergasted"}, {"hanzi": "发呆", "en": "stare blankly; day-dream"}, {"hanzi": "呆滞", "en": "dull; sluggish; stagnant"}, {"hanzi": "呆板", "en": "inflexible; wooden; rigid"}, {"hanzi": "呆在家里", "en": "stay at home"}, {"hanzi": "看呆了", "en": "watch in stunned bewilderment"}], "idioms": [{"hanzi": "目瞪口呆", "pinyin": "mù dèng kǒu dāi", "meaning_en": "stare wide-eyed and open-mouthed; struck dumb with shock"}, {"hanzi": "呆若木鸡", "pinyin": "dāi ruò mù jī", "meaning_en": "transfixed like a wooden cock; motionless with shock or mastery"}, {"hanzi": "大智若愚", "pinyin": "dà zhì ruò yú", "meaning_en": "supreme wisdom seems like foolishness; profound depth"}, {"hanzi": "死板教条", "pinyin": "sǐ bǎn jiào tiáo", "meaning_en": "dogmatic and rigid in thinking"}], "character_decomposition": [{"character": "呆", "pinyin": "dāi", "meaning_en": "dull; foolish; blank; stay", "meaning_es": "bobo; pasmado; quedarse", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (open mouth) + 木 (wooden post / immobile tree)", "sound_component": "呆 (dāi)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Open mouth 口 resting stiffly on top of wooden post 木; standing frozen with mouth agape like a wooden statue.", "visual_mnemonic_story_en": "Standing stiff as a wooden tree (木) with mouth gaping wide open (口) in stunned silence (呆).", "visual_mnemonic_story_es": "Quedarse inmóvil como un madero seco (木) con la boca abierta (口) atónito de asombro (呆).", "tone_mnemonic_anchor": "55", "cangjie": "RD", "traditional": "呆"}], "extended_reading_passages": [{"id": "#1", "hanzi": "庄子曾借斗鸡寓言阐述‘呆若木鸡’的至高境界。真正顶级的斗鸡既不鸣叫炫耀，也不张牙舞爪，而是如木雕般凝神静气、沉稳呆立，却能令一切对手望而生畏、落荒而逃。这体现了超越浮躁的大智与沉敛。", "pinyin": "Zhuāngzǐ céng jiè dòujī yùyán chǎnshù 'dāiruò-mùjī' de zhìgāo jìngjiè. Zhēnzhèng dǐngjí de dòujī jì bù míngjiào xuànyào, yě bù zhāngyá-wǔzhǎo, érshì rú mùdiāo bān nǐngshén-jìngqì, chénwěn dāi lì, què néng lìng yíqiè duìshǒu wàng'ér-shēngwèi, luòhuāng'értáo. Zhè tǐxiàn le chāoyuè fúzào de dàzhì yǔ chénliǎn.", "en": "Zhuangzi used the gamecock fable to illustrate the supreme state of 'calm like a wooden rooster'. The finest rooster neither crows nor struts, standing immobile like a wood carving, yet terrifies rivals into flight, exuding calm depth.", "es": "Zhuangzi ilustró con el gallo de pelea la cumbre del sosiego impávido. El mejor gallo no cacarea ni aletea; permanece plantado como talla de madera y su aplomo espanta a los rivales, encarnando la serenidad suprema."}, {"id": "#2", "hanzi": "当年在篮球场上，当小男孩说出锯掉筐底的瞬间，满场的大人们全惊呆了。工人们面面相觑地呆立了数秒，随后爆发出一阵如释重负的会心大笑。那一刻的目瞪口呆，正是思维冲破传统牢笼时不可避免的心智激荡。", "pinyin": "Dāngnián zài lánqiúchǎng shang, dāng xiǎo nánhái shuōchū jù diào kuāngdǐ de shùnjiān, mǎn chǎng de dàrenmen quán jīng dāi le. Gōngrénmen miànmiàn-xiāngqù de dāi lì le shù miǎo, suíhòu bàofā chū yí zhèn rúshì-zhòngfù de huìxīn dàxiào. Nà yí kè de mùdèng-kǒudāi, zhèng shì sīwéi chōngpò chuántǒng láolóng shí bùkě-bìmiǎn de xīnjiào jīdàng.", "en": "When the boy suggested sawing off the bottom, the adults on the court were struck dumb. Workers stood staring blankly for seconds before bursting into relieved laughter. That stunned moment captured the shock of minds bursting free from ruts.", "es": "Al proponer el chiquillo recortar el fondo, los adultos se quedaron boquiabiertos. Se miraron atónitos unos instantes antes de romper en risas de alivio. Ese instante de pasmo reflejó el despertar de la mente rompiendo viejas ataduras."}]}, {"meanings_summary": {"en": "to cause; bring about; give rise to (usually negative results)", "es": "causar; provocar; ocasionar; dar lugar a"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Actions actively built and engineered (造) that settle into a lasting result (成) bring about a consequence (造成).", "composite_memory_hook_es": "Actos fraguados con afán (造) que cuajan en un resultado consumado (成) ocasionan una consecuencia (造成).", "cultural_and_cognitive_roots": "Semantic preference: unlike neutral '产生' or positive '促成', '造成' predominantly introduces negative, regrettable outcomes.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by rising second tone: 'zào chéng' (51-35). Drive down forcefully on 'zào', then rise on 'chéng'."}, "semantic_boundary_contrasts": {"core_nuance": "造成 is a causal verb almost exclusively paired with undesirable, negative, or harmful nouns.", "contrasts": [{"id": "1", "compared_word": "造成 vs. 导致", "pinyin": "dǎozhì", "analysis": "导致 can be followed by a full explanatory clause or verb phrase (导致比赛中断), whereas 造成 is strictly paired with a noun object (造成恶劣影响)."}, {"id": "2", "compared_word": "造成 vs. 产生", "pinyin": "chǎnshēng", "analysis": "产生 is completely neutral and can introduce positive breakthroughs (产生灵感, 产生效益), unlike the negative bias of 造成."}, {"id": "3", "compared_word": "造成 vs. 引起", "pinyin": "yǐnqǐ", "analysis": "引起 means to attract or arouse notice, discussion, or reaction (引起广泛关注), without necessarily implying catastrophic damage."}]}, "traps_and_cognates": {"look_alikes": [{"character": "造", "pinyin": "zào", "meaning_en": "create; cause", "distinction_note": "Movement radical 辶 with 告"}, {"character": "选", "pinyin": "xuǎn", "meaning_en": "choose; select", "distinction_note": "Movement radical 辶 with 先"}, {"character": "成", "pinyin": "chéng", "meaning_en": "become; complete", "distinction_note": "6 strokes including slanted hook and 戈 axe"}, {"character": "戍", "pinyin": "shù", "meaning_en": "garrison frontier", "distinction_note": "Has a dot inside the corner"}], "etymological_cognates": [{"character": "致", "pinyin": "zhì", "gloss_en": "cause; lead to"}, {"character": "致", "pinyin": "zhì", "gloss_en": "incur; deliver"}, {"character": "引", "pinyin": "yǐn", "gloss_en": "lead to; trigger"}, {"character": "酿", "pinyin": "niàng", "gloss_en": "ferment; brew crisis"}]}, "id": "35", "hanzi": "造成", "pinyin": "zào chéng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cause, bring about, or result in an unfavorable, problematic, or harmful consequence", "definition_es": "ocasionar, producir o desembocar en una consecuencia perjudicial, dañina o indeseable", "example_phrase": "造成不可挽回的重大损失 (cause irreversible major losses)"}], "example_sentences": [{"id": "#1", "hanzi": "由于施工方在深基坑作业中违规操作，导致地下自来水主管道破裂，给周边居民供水造成了极大不便。", "pinyin": "Yóuyú shīgōngfāng zài shēn jīkēng zuòyè zhōng wéiguī cāozuò, dǎozhì dìxià zìláishuǐ zhǔguǎndào pòliè, gěi zhōubiān jūmín gōngshuǐ zàochéng le jídà búbiàn.", "en": "Due to irregular drilling in deep foundation pits by contractors, the underground water main ruptured, causing severe inconvenience to surrounding residents' water supply.", "es": "Debido a una maniobra antirreglamentaria en las obras, se rompió la tubería principal subterránea, causando graves molestias al suministro vecinal."}, {"id": "#2", "hanzi": "如果不能及时疏导青少年的负面情绪，长期的心理压抑将对其身心健康造成深远的负面影响。", "pinyin": "Rúguǒ bùnéng jíshí shūdǎo qīng-shàonián de fùmiàn qíngxù, chángqī de xīnlǐ yāyì jiāng duì qí shēnxīn jiànkāng zàochéng shēnyuǎn de fùmiàn yǐngxiǎng.", "en": "If adolescents' negative emotions are not channeled in time, prolonged psychological distress will cause profound adverse effects on their well-being.", "es": "Si no se encauzan a tiempo las emociones negativas en adolescentes, la represión psicológica prolongada causará hondos perjuicios a su salud mental."}], "collocations": [{"hanzi": "造成损失", "en": "cause financial loss / damage"}, {"hanzi": "造成严重后果", "en": "cause grave consequences"}, {"hanzi": "造成不良影响", "en": "cause adverse impact"}, {"hanzi": "造成伤亡", "en": "cause casualties"}, {"hanzi": "造成拥堵", "en": "cause traffic congestion"}, {"hanzi": "造成误解", "en": "cause misunderstanding"}], "idioms": [{"hanzi": "祸从口出", "pinyin": "huò cóng kǒu chū", "meaning_en": "disaster comes from careless mouth; loose lips sink ships"}, {"hanzi": "遗祸无穷", "pinyin": "yí huò wú qióng", "meaning_en": "bequeath endless disasters; cause endless trouble"}, {"hanzi": "木已成舟", "pinyin": "mù yǐ chéng zhōu", "meaning_en": "the timber has been carved into a boat; what is done cannot be undone"}, {"hanzi": "后患无穷", "pinyin": "hòu huàn wú qióng", "meaning_en": "breed unending future troubles"}], "character_decomposition": [{"character": "造", "pinyin": "zào", "meaning_en": "create; build; fabricate; cause", "meaning_es": "crear; construir; fabricar; causar", "radical": "辶", "radical_meaning_en": "movement", "meaning_component": "辶 (advance on path) + 告 (announce / sacrifice bull)", "sound_component": "告 (gào / phonetic)", "stroke_count": "10", "composition_type": "半包围结构", "etymology_and_mnemonic": "Advancing on the road 辶 toward sacrifice altars to make prayers 告; extended to manufacturing, constructing, and generating outcomes.", "visual_mnemonic_story_en": "Advancing along a road (辶) while making an official announcement (告) to create a new institution (造).", "visual_mnemonic_story_es": "Avanzar por un camino (辶) proclamando decretos (告) para fundar una nueva obra (造).", "tone_mnemonic_anchor": "51", "cangjie": "YHGR", "traditional": "造"}, {"character": "成", "pinyin": "chéng", "meaning_en": "become; complete; achieve; succeed", "meaning_es": "convertirse; completar; lograr", "radical": "戈", "radical_meaning_en": "halberd / spear", "meaning_component": "戈 (weapon) + 𢦏 (firm foundation wall)", "sound_component": "成 (chéng)", "stroke_count": "6", "composition_type": "单一结构", "etymology_and_mnemonic": "A spear 戈 defending a newly completed fortified wall settlement; accomplishing construction and reaching fruition.", "visual_mnemonic_story_en": "Planting a protective spear (戈) upon the completed stone battlements: full accomplishment (成).", "visual_mnemonic_story_es": "Clavar una lanza (戈) sobre las almenas concluidas de la muralla: obra culminada (成).", "tone_mnemonic_anchor": "35", "cangjie": "IHSH", "traditional": "成"}], "extended_reading_passages": [{"id": "#1", "hanzi": "盲目砍伐原始森林不仅破坏了珍稀野生动物的天然栖息家园，更诱发了严重的水土流失与频繁的山体滑坡，给流域下游居民的生命财产安全造成了巨大威胁。人与自然唯有和谐共生，方能守住绿水青山的美好家园。", "pinyin": "Mángmù kǎnfá yuánshǐ sēnlín bùjǐn pòhuài le zhēnxī yěshēng dòngwù de tiānrán qīxī jiāyuán, gèng yòufā le yánzhòng de shuǐtǔ liúshī yǔ pínfán de shāntǐ huápō, gěi liùyù xiàyóu jūmín de shēngmìng cáichǎn ānquán zàochéng le jùdà wēixié. Rén yǔ zìrán wéiyǒu héxié gòngshēng, fāng néng shǒuzhù lǜshuǐ-qīngshān de měihǎo jiāyuán.", "en": "Deforesting virgin timber not only ravages wildlife habitats, but induces severe soil erosion and landslides, posing grave hazards to downstream communities. Only by living in harmony with nature can humanity safeguard its home.", "es": "La tala indiscriminada devasta los hábitats silvestres y desata deslaves, causando graves estragos en las poblaciones ribereñas. Sólo conviviendo en armonía con la naturaleza preservaremos la belleza de nuestra tierra."}, {"id": "#2", "hanzi": "当年在篮球运动起步阶段，那个未经改造的带底果筐给整场赛事造成了极大的节奏阻碍。每次投篮得分都迫使比赛停摆，频繁的停滞给观众的观赛体验造成了严重破坏。直到有人果断锯掉筐底，才从根源上消除了这个造成混乱的症结。", "pinyin": "Dāngnián zài lánqiú yùndòng qǐbù jiēduàn, nà ge wèijīng gǎizào de dàidǐ guǒkuāng gěi zhěngchǎng sàishì zàochéng le jídà de jiézòu zǔ'ài. Měicì tóulán défēn dōu pòshǐ bǐsài tíngbǎi, pínfán de tíngzhì gěi guānzhòng de guānsài tǐyàn zàochéng le yánzhòng pòhuài. Zhídào yǒurén guǒduàn jù diào kuāngdǐ, cái cóng gēnyuán shang xiāochú le zhè ge zàochéng hùnluàn de zhèngjié.", "en": "At basketball's inception, unadapted closed baskets caused enormous rhythmic bottlenecks. Scores halted play, ruining the spectator experience. Only when someone sawed off the bottoms was this root cause of disruption eliminated for good.", "es": "En los inicios del baloncesto, las cestas ciegas causaron grandes parones en el juego. Cada canasta congelaba el partido, arruinando la emoción del público. Al serrar el fondo, se erradicó de raíz la causa de tanto trastorno."}]}, {"meanings_summary": {"en": "as if; to seem; like; resemblance", "es": "como si; parecer; semejante a; tal parece"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A figure imitating form (仿) glimpsed faintly through misty silhouettes (佛) appears as if real (仿佛).", "composite_memory_hook_es": "Una figura que imita un modelo (仿) divisada entre brumas tenues (佛) se asemeja a una ilusión (仿佛).", "cultural_and_cognitive_roots": "Classical evocative literary conjunction prevalent in poetry and prose (e.g. 朱自清《荷塘月色》) for sensory similes.", "tone_sandhi_and_pitch_modulation": "Dipping third tone followed by rising second tone: 'fǎng fú' (214-35). Note second-tone reading 'fú' (not 'fó')."}, "semantic_boundary_contrasts": {"core_nuance": "仿佛 is a literary connective establishing poetic similes or subjective dreamlike impressions.", "contrasts": [{"id": "1", "compared_word": "仿佛 vs. 好像", "pinyin": "hǎoxiàng", "analysis": "好像 is neutral and ubiquitous in everyday conversation, while 仿佛 carries poetic elegance and literary flavor."}, {"id": "2", "compared_word": "仿佛 vs. 似乎", "pinyin": "sìhū", "analysis": "似乎 conveys logical conjecture or mild uncertainty about facts (他似乎不知道), whereas 仿佛 introduces imaginative figurative similes."}, {"id": "3", "compared_word": "仿佛 vs. 犹如", "pinyin": "yóurú", "analysis": "犹如 is an explicit literary simile marker directly equating two concrete nouns, while 仿佛 can function adverbially across full narrative clauses."}]}, "traps_and_cognates": {"look_alikes": [{"character": "仿", "pinyin": "fǎng", "meaning_en": "resemble; imitate", "distinction_note": "Person radical 亻 on left with 方"}, {"character": "伤", "pinyin": "shāng", "meaning_en": "wound; injure", "distinction_note": "Has 𠂉 and 力 inside"}, {"character": "佛", "pinyin": "fú/fó", "meaning_en": "resemble; Buddha", "distinction_note": "Person radical 亻 on left with 弗"}, {"character": "拂", "pinyin": "fú", "meaning_en": "brush off; whisk", "distinction_note": "Hand radical 扌 on left of 弗"}], "etymological_cognates": [{"character": "宛", "pinyin": "wǎn", "gloss_en": "as if; winding"}, {"character": "似", "pinyin": "sì", "gloss_en": "resemble; like"}, {"character": "像", "pinyin": "xiàng", "gloss_en": "resemble; picture"}, {"character": "若", "pinyin": "ruò", "gloss_en": "seem like; if"}]}, "id": "36", "hanzi": "仿佛", "pinyin": "fǎng fú", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Literary", "definition_en": "seeming as if; resembling in appearance, impression, or feeling", "definition_es": "da la impresión de que; como si; de manera muy semejante o ilusoria", "example_phrase": "仿佛回到了快乐的童年时代 (as if returning to happy childhood days)"}], "example_sentences": [{"id": "#1", "hanzi": "微风吹拂过宁静的湖面，层层荡漾的粼粼波光仿佛无数碎银在月色下欢快跳跃。", "pinyin": "Wēifēng chuīfú guò níngjìng de húmiàn, céngcéng dàngyàng de línlín bōguāng fǎngfú wúshù suìyín zài yuèyè xià huānkuài tiàoyuè.", "en": "Gentle breezes swept across the peaceful lake; rippling glimmering wavelets looked as if countless shards of broken silver were dancing under the moonlight.", "es": "La brisa rozaba el lago plácido; los reflejos centelleantes en las ondas parecían trozos de plata viva danzando bajo la luna."}, {"id": "#2", "hanzi": "听着老艺人悠扬婉转的古筝弹奏，台下观众仿佛置身于烟雨蒙蒙的江南古镇水巷之中。", "pinyin": "Tīng zhe lǎo yìrén yōuyáng wǎnzhuǎn de gǔzhēng tánzòu, táixià guānzhòng fǎngfú zhìshēn yú yānyǔ-méngméng de Jiāngnán gǔzhèn shuǐxiàng zhīzhōng.", "en": "Listening to the veteran artist's melodious guzheng performance, the audience felt as if they were transported into misty water lanes of Jiangnan canal towns.", "es": "Al escuchar las notas cadenciosas del laúd tradicional, el público creyó hallarse inmerso entre los canales neblinosos de las villas ribereñas del sur."}], "collocations": [{"hanzi": "仿佛是", "en": "seeming as if it were"}, {"hanzi": "仿佛置身于", "en": "as if placed in the midst of"}, {"hanzi": "仿佛看到了", "en": "as if having seen"}, {"hanzi": "仿佛在说", "en": "as if saying"}, {"hanzi": "仿佛回到了", "en": "as if having returned to"}, {"hanzi": "神态仿佛", "en": "bearing strikingly resembles"}], "idioms": [{"hanzi": "如梦初醒", "pinyin": "rú mèng chū xǐng", "meaning_en": "as if waking from a dream; sudden awakening"}, {"hanzi": "若即若离", "pinyin": "ruò jí ruò lí", "meaning_en": "seeming both close and distant; keeping at arm's length"}, {"hanzi": "宛若天仙", "pinyin": "wǎn ruò tiān xiān", "meaning_en": "graceful and lovely as a celestial fairy"}, {"hanzi": "栩栩如生", "pinyin": "xǔ xǔ rú shēng", "meaning_en": "lifelike as if alive; vivid artistic realism"}], "character_decomposition": [{"character": "仿", "pinyin": "fǎng", "meaning_en": "imitate; like; resemble", "meaning_es": "imitar; parecerse; semejante", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person model) + 方 (square / directions)", "sound_component": "方 (fāng / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 aligning oneself to standard squares 方; copying models, imitating form, or bearing close likeness.", "visual_mnemonic_story_en": "An artist (亻) copying lines precisely along a carpenter's square pattern (方) to replicate an image (仿).", "visual_mnemonic_story_es": "Un dibujante (亻) guiándose por una escuadra (方) para calcar una figura con exactitud (仿).", "tone_mnemonic_anchor": "214", "cangjie": "OYS", "traditional": "倣"}, {"character": "佛", "pinyin": "fú", "meaning_en": "resemble; like (fú); Buddha (fó)", "meaning_es": "asemejarse; parecer (fú); Buda (fó)", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person) + 弗 (bent bows / negative bound)", "sound_component": "弗 (fú / phonetic)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Person radical 亻 with 弗; phonetic borrowing meaning hazy resemblance; pronounced fú in compound '仿佛'.", "visual_mnemonic_story_en": "A figure (亻) seen faintly through mist like a bending willow bow (弗), appearing as if in a dream (佛).", "visual_mnemonic_story_es": "Una silueta humana (亻) divisada entre brumas (弗), que parece casi una ilusión vaporosa (佛).", "tone_mnemonic_anchor": "35", "cangjie": "OLLN", "traditional": "彿"}], "extended_reading_passages": [{"id": "#1", "hanzi": "漫步在雨后苍翠欲滴的幽静竹林中，泥土的清芬混合着竹叶的幽香沁人心脾。偶尔几声婉转清脆的鸟鸣穿透林间薄雾，让人心旷神怡，仿佛步入了一幅遗世独立的古代水墨写意长卷。", "pinyin": "Mànbù zài yǔhòu cāngcuì-yùdī de yōujìng zhúlín zhōng, nítǔ de qīngfēn hùnhé zhe zhúyè de yōuxiāng qìnrénxīnpí. Ǒu'ěr jǐ shēng wǎnzhuǎn qīngcuì de niǎomíng chuāntòu línjiān báowù, ràng rén xīnkuàng-shényí, fǎngfú bùrù le yì fú yíshì-dúlì de gǔdài shuǐmò xièyì chángjuàn.", "en": "Strolling in verdant bamboo groves after rain, the scent of damp earth and bamboo fragrance was intoxicating. Crisp birdsong pierced thin mists; one felt as though stepping straight into an ancient timeless ink wash scroll.", "es": "Pasear entre bambúes tras la lluvia embriagaba con aroma a tierra húmeda y hojas frescas. Los trinos rompían la neblina; parecía como si uno se adentrara en un cuadro tradicional de tinta china al margen del mundo."}, {"id": "#2", "hanzi": "当工人们终于挥动锯子将桃筐底部锯开的那一刹那，在场的所有人仿佛卸下了一幅沉重不堪的枷锁。篮球在投中后顺滑地穿筐而落，场馆内爆发出雷鸣般的喝彩，现代篮球运动仿佛在这一声落地中重获新生。", "pinyin": "Dāng gōngrénmen zhōngyú huīdòng jùzi jiāng táokuāng dǐbù jù kāi de nà yí chànà, zàichǎng de suǒyǒurén fǎngfú xièxià le yì fú chénzhòng-bùkān de jiāsuǒ. Lánqiú zài tóu zhòng hòu shùnhuá de chuān kuāng ér luò, chǎngguǎn nèi bàofā chū léimíng bān de hècǎi, xiàndài lánqiú yùndòng fǎngfú zài zhè yì shēng luòdì zhōng chónghuò xīnshēng.", "en": "The moment workmen sawed open the basket bottoms, everyone present felt as if a heavy shackle had been lifted. Balls dropped through smoothly; thunderous cheers erupted, as if modern basketball was reborn in that bounce.", "es": "En el instante en que la sierra cercenó el fondo de la cesta, todos sintieron como si se liberaran de un pesado yugo. La bola cayó limpia entre ovaciones atronadoras; el baloncesto moderno parecía renacer con aquel bote."}]}, {"meanings_summary": {"en": "to hinder; obstruct; impede; obstacle; barrier", "es": "obstaculizar; entorpecer; estorbar; traba; obstáculo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Steep mountain cliffs (阻) and giant fallen boulders (碍) combine to form a formidable hindrance (阻碍).", "composite_memory_hook_es": "Riscos empinados (阻) y peñascos caídos en la senda (碍) se conjugan en un gran obstáculo (阻碍).", "cultural_and_cognitive_roots": "Derived from classical geographic hazards (险阻) where cliffs and boulders tested perseverance and road-building ingenuity.", "tone_sandhi_and_pitch_modulation": "Dipping third tone followed by falling fourth tone: 'zǔ 'ài' (214-51). Dip low on 'zǔ', then drop decisively on 'ài'."}, "semantic_boundary_contrasts": {"core_nuance": "阻碍 can be either a verb meaning to impede progress or a noun denoting the obstacle itself.", "contrasts": [{"id": "1", "compared_word": "阻碍 vs. 妨碍", "pinyin": "fáng'ài", "analysis": "妨碍 specifically means causing momentary inconvenience or annoyance to others (妨碍别人休息), while 阻碍 implies major systemic blockages to progress."}, {"id": "2", "compared_word": "阻碍 vs. 阻止", "pinyin": "zǔzhǐ", "analysis": "阻止 means stopping someone from carrying out an action entirely (阻止他犯错), while 阻碍 slows or impairs progress without necessarily halting it."}, {"id": "3", "compared_word": "阻碍 vs. 挫折", "pinyin": "cuòzhé", "analysis": "挫折 refers to emotional setbacks or defeats experienced after failure, whereas 阻碍 is the external hurdle."}]}, "traps_and_cognates": {"look_alikes": [{"character": "阻", "pinyin": "zǔ", "meaning_en": "block; hinder", "distinction_note": "Mound radical 阝 on left with 且"}, {"character": "租", "pinyin": "zū", "meaning_en": "rent; lease", "distinction_note": "Grain radical 禾 on left of 且"}, {"character": "碍", "pinyin": "ài", "meaning_en": "hinder; obstacle", "distinction_note": "Stone radical 石 on left"}, {"character": "得", "pinyin": "dé", "meaning_en": "obtain; get", "distinction_note": "Step radical 彳 on left"}], "etymological_cognates": [{"character": "障", "pinyin": "zhàng", "gloss_en": "screen; barrier"}, {"character": "塞", "pinyin": "sè", "gloss_en": "cork; choke; obstruct"}, {"character": "拦", "pinyin": "lán", "gloss_en": "block; intercept"}, {"character": "抑", "pinyin": "yì", "gloss_en": "restrain; suppress"}]}, "id": "37", "hanzi": "阻碍", "pinyin": "zǔ 'ài", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to block, hinder, or make difficult the progress, movement, or development of something", "definition_es": "dificultar o impedir el paso, avance o desarrollo de algo o alguien", "example_phrase": "阻碍社会经济的健康发展 (hinder healthy socioeconomic development)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a hindrance, obstacle, or impeding condition", "definition_es": "cosa que entorpece o estorba la consecución de un fin", "example_phrase": "扫清前行道路上的一切阻碍 (sweep away all obstacles on the path ahead)"}], "example_sentences": [{"id": "#1", "hanzi": "地方保护主义和各种隐形市场壁垒，严重阻碍了全国统一大市场的建立与生产要素的自由流动。", "pinyin": "Dìfāng bǎohù zhǔyì hé gèzhǒng yǐnxíng shìchǎng bìlěi, yánzhòng zǔ'ài le quánguó tǒngyī dà shìchǎng de jiànlì yǔ shēngchǎn yàosù de zìyóu liúdòng.", "en": "Local protectionism and invisible market barriers severely hinder the formation of a unified national market and the free flow of production factors.", "es": "El proteccionismo local y las trabas invisibles obstaculizan gravemente la articulación de un mercado nacional y la libre circulación productiva."}, {"id": "#2", "hanzi": "坚强的探险家从未被大自然险恶的崇山峻岭所吓倒，所有的严寒险阻都化为了砥砺坚强意志的宝贵财富。", "pinyin": "Jiānqiáng de tànxiǎnjiā cóngwèi bèi zìrán xiǎn'è de chóngshān-jùnlǐng suǒ xiàdǎo, suǒyǒu de yánhán xiǎnzǔ dōu huàwéi le dǐlì jiānqiáng yìzhì de bǎoguì cáifù.", "en": "The intrepid explorer was never daunted by towering perilous peaks; every frost and hindrance became precious assets forging unbreakable resolve.", "es": "El intrépido explorador no se arredró ante los abruptos riscos; el frío y los obstáculos se convirtieron en temple para su inquebrantable voluntad."}], "collocations": [{"hanzi": "清除阻碍", "en": "eliminate / remove obstacles"}, {"hanzi": "阻碍发展", "en": "hinder development"}, {"hanzi": "造成阻碍", "en": "create an obstacle / hindrance"}, {"hanzi": "重大阻碍", "en": "major roadblock / obstacle"}, {"hanzi": "阻碍交通", "en": "obstruct traffic"}, {"hanzi": "破除阻碍", "en": "break through impediments"}], "idioms": [{"hanzi": "排除万难", "pinyin": "pái chú wàn nán", "meaning_en": "surmount all ten thousand difficulties; overcome all obstacles"}, {"hanzi": "披荆斩棘", "pinyin": "pī jīng zhǎn jí", "meaning_en": "hack through brambles and thistles; pioneer through hardships"}, {"hanzi": "艰难险阻", "pinyin": "jiān nán xiǎn zǔ", "meaning_en": "perilous obstacles and hardships along a journey"}, {"hanzi": "畅通无阻", "pinyin": "chàng tōng wú zǔ", "meaning_en": "completely unimpeded; open passage without obstacle"}], "character_decomposition": [{"character": "阻", "pinyin": "zǔ", "meaning_en": "hinder; block; steep mound", "meaning_es": "frenar; obstruir; loma empinada", "radical": "阝", "radical_meaning_en": "mound / hill", "meaning_component": "阝 (steep mountain cliff) + 且 (sacrificial stand / altar)", "sound_component": "且 (qiě / phonetic association)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Mound/hill radical 阝 beside 且; a sheer mountain terrace obstructing travellers' road, requiring arduous detours.", "visual_mnemonic_story_en": "A steep hill cliff (阝) blocking the mountain pass (且), hindering travelers' advance (阻).", "visual_mnemonic_story_es": "Un risco escarpado (阝) cerrando el paso del sendero (且), frenando a los caminantes (阻).", "tone_mnemonic_anchor": "214", "cangjie": "NLBM", "traditional": "阻"}, {"character": "碍", "pinyin": "ài", "meaning_en": "hinder; obstruct; impede", "meaning_es": "estorbar; entorpecer", "radical": "石", "radical_meaning_en": "stone / rock", "meaning_component": "石 (heavy boulder) + 旦 (rising sun blocked)", "sound_component": "得 / 碍 (phonetic)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "Stone radical 石 beside 碍; a massive boulder blocking the roadway, impeding travel and sight lines.", "visual_mnemonic_story_en": "A giant boulder (石) rolled into the middle of the road at dawn (旦), creating an obstacle (碍).", "visual_mnemonic_story_es": "Una enorme roca (石) atravesada al despuntar el día (旦), estorbando el camino (碍).", "tone_mnemonic_anchor": "51", "cangjie": "MRAPM", "traditional": "礙"}], "extended_reading_passages": [{"id": "#1", "hanzi": "改革开放四十多年来的恢弘历程昭示我们，任何社会制度的发展都不可能一帆风顺。唯有敢于直面利益固化的藩篱，敢于破除阻碍创新活力的体制机制障碍，国家才能在风云变幻的国际竞争中勇立潮头、行稳致远。", "pinyin": "Gǎigé-kāifàng sìshí duō nián lái de huīhóng lìchéng zhāoshì wǒmen, rènhé shèhuì zhìdù de fāzhǎn dōu bùkěnéng yīfān-fēngshùn. Wéiyǒu gǎnyú zhímiàn lìyì gùhuà de fānlí, gǎnyú pòchú zǔ'ài chuàngxīn huólì de tǐzhì jīzhì zhàng'ài, guójiā cái néng zài fēngyún-biànhuàn de guójì jìngzhēng zhōng yǒnglì-cháotóu, xíngwěn-zhìyuǎn.", "en": "Decades of reform reveal that no social development enjoys smooth sailing. Only by confronting entrenchment and dismantling institutional roadblocks hindering innovation can a nation ride cresting waves and advance steadily.", "es": "Décadas de reforma demuestran que ningún progreso es coser y cantar. Sólo afrontando los intereses creados y derribando las trabas burocráticas que frenan la innovación, podrá una nación liderar el porvenir con paso firme."}, {"id": "#2", "hanzi": "在人生的漫长赛道上，真正阻碍我们前进步伐的，往往不是外界环境的严苛艰难，而是我们头脑中固步自封的‘思维筐底’。学会用一把锋利的智慧之锯果断锯掉心理上的筐底与局限，所有的阻碍都将化为通向成功的崭新坦途。", "pinyin": "Zài rénshēng de màncháng sàidào shang, zhēnzhèng zǔ'ài wǒmen qiánjìn bùfá de, wǎngwǎng búshì wàijiè huánjìng de yánkē jiānnán, érshì wǒmen tóunǎo zhōng gùbù-zìfēng de 'sīwéi kuāngdǐ'. Xuéhuì yòng yì bǎ fēnglì de zhìhuì zhī jù guǒduàn jù diào xīnlǐ shang de kuāngdǐ yǔ júxiàn, suǒyǒu de zǔ'ài dōu jiāng huàwéi tōngxiàng chénggōng de zhǎnxīn tǎntú.", "en": "On life's long track, what truly hinders our stride is seldom external harshness, but the rigid mental bottoms of our own assumptions. Learn to saw away psychological limitations with wisdom's blade, and every obstacle will transform into an open avenue to triumph.", "es": "En la carrera de la vida, lo que de verdad frena el paso no son los rigores del entorno, sino los fondos ciegos de nuestra mente. Aprender a serrar con sabiduría esos límites psicológicos transformará cualquier tropiezo en una senda despejada hacia el éxito."}]}];
